window.HEAT_BANK = (window.HEAT_BANK || []).concat([
  {"id":"t-without-replacement-1","type":"single","points":1,"stem":"袋中有 5 个红球、4 个蓝球。一次不放回地随机抽取两个球，两个都是红球的概率约是多少？","options":["\\(0.2778\\)","\\(0.1389\\)","\\(0.3086\\)","\\(0.5556\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-without-replacement","explanation":"在不放回抽样中，第二次取红的条件概率为 \\((r-1)/(N-1)\\)。与首次概率 \\(r/N\\) 相乘。 得 \\(0.2778\\)。"},
  {"id":"t-random-walk-origin-1","type":"single","points":2,"stem":"微粒从原点出发，在一条直线上独立地走 4 步，每步等概率向左或向右移动一个单位。最后回到原点的概率约是多少？","options":["\\(0.5\\)","\\(0.0625\\)","\\(0.375\\)","\\(0.2\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-random-walk-origin","explanation":"回到原点要求左右各走一半步数。共有 \\(\\binom{N}{N/2}\\) 条这样的序列，总序列数为 \\(2^N\\)。 得 \\(0.375\\)。"},
  {"id":"t-power-density-1","type":"single","points":3,"stem":"连续随机变量的概率密度在 0 到 2 之间为 \\(f(x)=C x^{1}\\)，区间外为零。该变量落在 0 到 1 之间的概率约是多少？","options":["\\(0.75\\)","\\(0.25\\)","\\(0.5\\)","\\(0.125\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-power-density","explanation":"归一化要求分母为 \\(\\int_0^{L}x^a\\,\\mathrm dx\\)。区间概率是 \\(\\int_0^b x^a\\,\\mathrm dx/\\int_0^L x^a\\,\\mathrm dx=(b/L)^{a+1}\\)。 得 \\(0.25\\)。","reference":"当 \\(a>-1\\) 时，\\(\\int_0^L x^a\\,\\mathrm dx=L^{a+1}/(a+1)\\)。"},
  {"id":"t-rigid-vessel-temperature-1","type":"single","points":1,"stem":"密闭刚性容器里装有一定量理想气体。气体从 250 K 缓慢升温到 340 K，初态绝对压强为 90 kPa。末态压强约是多少？","options":["\\(340\\,\\mathrm{kPa}\\)","\\(66.18\\,\\mathrm{kPa}\\)","\\(90\\,\\mathrm{kPa}\\)","\\(122.4\\,\\mathrm{kPa}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-rigid-vessel-temperature","explanation":"容积和物质的量保持恒定，状态方程给出 \\(p_2/p_1=T_2/T_1\\)。 得 \\(122.4\\,\\mathrm{kPa}\\)。"},
  {"id":"t-dalton-partial-pressure-1","type":"single","points":1,"stem":"两种互不反应的理想气体形成均匀混合气。A 组分有 2 mol，B 组分有 7 mol，总压强为 140 kPa。A 的分压约是多少？","options":["\\(31.11\\,\\mathrm{kPa}\\)","\\(15.56\\,\\mathrm{kPa}\\)","\\(40\\,\\mathrm{kPa}\\)","\\(108.9\\,\\mathrm{kPa}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 2 章","family":"t-dalton-partial-pressure","explanation":"各组分在同一温度和体积下服从状态方程，分压占总压的比例等于摩尔分数。 得 \\(31.11\\,\\mathrm{kPa}\\)。"},
  {"id":"t-joined-vessels-1","type":"single","points":2,"stem":"两个容积分别为 3 L、8 L 的刚性容器分别装有理想气体，压强为 200 kPa、65 kPa。两容器均已与同一恒温浴达到热平衡，打开连通阀直至新平衡。末态总压强约是多少？","options":["\\(163.2\\,\\mathrm{kPa}\\)","\\(265\\,\\mathrm{kPa}\\)","\\(101.8\\,\\mathrm{kPa}\\)","\\(132.5\\,\\mathrm{kPa}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-joined-vessels","explanation":"由初态两侧总物质的量守恒，且温度相同，有 \\(p_f(V_1+V_2)=p_1V_1+p_2V_2\\)。 得 \\(101.8\\,\\mathrm{kPa}\\)。"},
  {"id":"t-gas-mass-pressure-1","type":"single","points":2,"stem":"2 kg 氮气装在体积为 0.8 立方米的容器内，温度为 280 K。把氮气视为理想气体，取其摩尔质量 28 g/mol，求绝对压强。","options":["\\(5820\\,\\mathrm{Pa}\\)","\\(2.078\\times10^{5}\\,\\mathrm{Pa}\\)","\\(2.078\\times10^{8}\\,\\mathrm{Pa}\\)","\\(4.157\\times10^{5}\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-gas-mass-pressure","explanation":"先以 \\(n=m/M\\) 将质量换成摩尔数，再由 \\(p=nRT/V\\) 代入。注意 \\(28\\,\\mathrm{g\\,mol^{-1}}=0.028\\,\\mathrm{kg\\,mol^{-1}}\\)。 得 \\(2.078\\times10^{5}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-van-der-waals-pressure-1","type":"single","points":3,"stem":"某气体每摩尔体积为 0.9 L/mol、温度为 275 K。范德瓦尔斯参数分别为 \\(0.13\\,\\mathrm{Pa\\,m^6\\,mol^{-2}}\\) 和 \\(0.00032\\,\\mathrm{m^3\\,mol^{-1}}\\)。求压强。","options":["\\(3.781\\times10^{6}\\,\\mathrm{Pa}\\)","\\(4.102\\times10^{6}\\,\\mathrm{Pa}\\)","\\(1.714\\times10^{6}\\,\\mathrm{Pa}\\)","\\(2.54\\times10^{6}\\,\\mathrm{Pa}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-van-der-waals-pressure","explanation":"采用摩尔体积形式，\\(p=RT/(V_m-b)-a/V_m^2\\)。体积应先换成 \\(\\mathrm{m^3\\,mol^{-1}}\\)。 得 \\(3.781\\times10^{6}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-mean-free-path-1","type":"single","points":2,"stem":"温度为 270 K、压强为 120 Pa 的稀薄气体由有效直径 0.28 nm 的相同硬球分子组成。估算分子的平均自由程。","options":["\\(0.0002802\\,\\mathrm m\\)","\\(0.0001261\\,\\mathrm m\\)","\\(8.918\\times10^{-5}\\,\\mathrm m\\)","\\(4.459\\times10^{-5}\\,\\mathrm m\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-mean-free-path","explanation":"由 \\(n=p/(k_\\mathrm BT)\\) 求数密度。相同硬球的平均自由程是 \\(\\lambda=1/(\\sqrt2\\,\\pi d^2 n)\\)，其中 \\(\\pi d^2\\) 为碰撞截面。 得 \\(8.918\\times10^{-5}\\,\\mathrm m\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-rms-temperature-1","type":"single","points":2,"stem":"一种理想气体的摩尔质量为 28 g/mol，分子的方均根速率为 440 m/s。求该气体的热力学温度。","options":["\\(217.3\\,\\mathrm{K}\\)","\\(326\\,\\mathrm{K}\\)","\\(652\\,\\mathrm{K}\\)","\\(108.7\\,\\mathrm{K}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-rms-temperature","explanation":"平均平动动能为 \\(3k_\\mathrm BT/2\\)，所以 \\(v_{\\mathrm{rms}}^2=3RT/M\\)。摩尔质量应以 kg/mol 代入。 得 \\(217.3\\,\\mathrm{K}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-kinetic-pressure-1","type":"single","points":2,"stem":"理想气体的压强为 86 kPa，质量密度为 0.68 kg/m³。估计分子的方均根速率。","options":["\\(871.1\\,\\mathrm{m\\,s^{-1}}\\)","\\(616\\,\\mathrm{m\\,s^{-1}}\\)","\\(435.6\\,\\mathrm{m\\,s^{-1}}\\)","\\(355.6\\,\\mathrm{m\\,s^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-kinetic-pressure","explanation":"分子运动论给出 \\(p=\\rho v_{\\mathrm{rms}}^2/3\\)，压强换成 Pa 后求平方根。 得 \\(616\\,\\mathrm{m\\,s^{-1}}\\)。"},
  {"id":"t-collision-frequency-1","type":"single","points":1,"stem":"某稀薄气体分子的平均速率为 370 m/s，平均自由程为 82 nm。估计单个分子的平均碰撞频率。","options":["\\(4.512\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(1.128\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(4.512\\,\\mathrm{s^{-1}}\\)","\\(9.024\\times10^{9}\\,\\mathrm{s^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-collision-frequency","explanation":"在平均意义下，单位时间经历的自由程数约为 \\(\\bar v/\\lambda\\)。将 nm 换成 m 再相除。 得 \\(4.512\\times10^{9}\\,\\mathrm{s^{-1}}\\)。"},
  {"id":"t-maxwell-temperature-ratio-1","type":"single","points":1,"stem":"同一种气体分别处于 250 K 和 310 K 的平衡态。后者与前者的最概然速率之比约是多少？","options":["\\(0.898\\)","\\(0.24\\)","\\(1.114\\)","\\(1.24\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-temperature-ratio","explanation":"同种气体的分子质量相同，最概然速率 \\(v_p=\\sqrt{2RT/M}\\) 与绝对温度的平方根成正比。 得 \\(1.114\\)。"},
  {"id":"t-barometric-ratio-1","type":"single","points":3,"stem":"把大气视为均匀摩尔质量为 27 g/mol 的理想气体，设温度恒为 270 K、重力加速度不随高度改变。海拔比基准面高 1700 m 处的气压是基准面气压的多少倍？","options":["\\(0.8182\\)","\\(1.222\\)","\\(0.1818\\)","\\(0.6695\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-barometric-ratio","explanation":"将静力平衡 \\(\\mathrm dp/\\mathrm dz=-\\rho g\\) 与 \\(\\rho=Mp/(RT)\\) 联立并积分，得到 \\(p(z)/p(0)=\\exp[-Mgz/(RT)]\\)。 得 \\(0.8182\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-two-level-population-1","type":"single","points":3,"stem":"一批可分辨的弱相互作用粒子在 250 K 达到热平衡。每个粒子仅能处在两个非简并能级，上能级比下能级高 \\(3.797\\times10^{-21}\\,\\mathrm{J}\\)。约有多大比例的粒子在上能级？","options":["\\(0.7503\\)","\\(0.3329\\)","\\(0.2497\\)","\\(0.1108\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-two-level-population","explanation":"以上能级和下能级的玻尔兹曼权重分别为 \\(\\exp[-\\Delta E/(k_\\mathrm BT)]\\) 和 1，将上能级权重除以两权重之和。 得 \\(0.2497\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-mixture-equipartition-1","type":"single","points":2,"stem":"1 mol 单原子理想气体与 2 mol 刚性双原子理想气体混合，在 270 K 达到热平衡。忽略双原子分子的振动，混合气体的总内能约是多少？","options":["\\(2.918\\times10^{4}\\,\\mathrm{J}\\)","\\(1.01\\times10^{4}\\,\\mathrm{J}\\)","\\(1.684\\times10^{4}\\,\\mathrm{J}\\)","\\(1.459\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-mixture-equipartition","explanation":"按能量均分，单原子有 3 个自由度，刚性双原子有 5 个自由度。分别计算 \\(f nRT/2\\) 后相加。 得 \\(1.459\\times10^{4}\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-maxwell-concepts-1","type":"multiple","points":2,"stem":"温度为 275 K 的氧气和温度为 316 K 的氮气都处于无宏观流动的平衡态。取氧气、氮气的摩尔质量分别为 32 和 28 g/mol。关于它们的麦克斯韦速率分布，正确的是哪些？","options":["在同一平衡态，任一种气体的最概然速率大于其方均根速率。","氧气与氮气的最概然速率之比约为 \\(0.8726\\)。","氧气的最概然速率低于氮气。","任一种气体的分子平均速度矢量为零。","同一种气体升温，最概然速率增大。"],"answer":[1,2,3,4],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-concepts","explanation":"最概然速率为 \\(v_p=\\sqrt{2RT/M}\\)。两种气体的速率之比由各自的 \\(T/M\\) 决定；升温则最概然速率增大。最概然速率小于方均根速率。平衡态无宏观流动，各方向的速度矢量平均为零。"},
  {"id":"t-isobaric-work-1","type":"single","points":1,"stem":"1.2 mol 理想气体在压强不变的情况下从 290 K 升至 321 K。气体对外做的体积功约是多少？","options":["\\(154.6\\,\\mathrm{J}\\)","\\(309.3\\,\\mathrm{J}\\)","\\(773.2\\,\\mathrm{J}\\)","\\(463.9\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isobaric-work","explanation":"等压过程 \\(W=p(V_2-V_1)\\)。由状态方程，\\(p(V_2-V_1)=nR(T_2-T_1)\\)。 得 \\(309.3\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isochoric-heating-1","type":"single","points":1,"stem":"0.7 mol 单原子理想气体在刚性容器中从 290 K 加热到 317 K，仅交换热量。气体吸热约是多少？","options":["\\(235.7\\,\\mathrm{J}\\)","\\(392.8\\,\\mathrm{J}\\)","\\(471.4\\,\\mathrm{J}\\)","\\(157.1\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isochoric-heating","explanation":"定容过程没有体积功，吸热等于内能增加。单原子理想气体的定容摩尔热容为 \\(3R/2\\)。 得 \\(235.7\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isothermal-work-1","type":"single","points":2,"stem":"0.7 mol 理想气体在 270 K 从体积 2 L 可逆等温膨胀到 3.2 L。气体对外做功约是多少？","options":["\\(942.8\\,\\mathrm{J}\\)","\\(589.3\\,\\mathrm{J}\\)","\\(738.5\\,\\mathrm{J}\\)","\\(369.3\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isothermal-work","explanation":"准静态做功为 \\(\\int p\\,\\mathrm dV\\)。等温时 \\(p=nRT/V\\)，积分得 \\(W=nRT\\ln(V_2/V_1)\\)。 得 \\(738.5\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-adiabatic-expansion-temperature-1","type":"single","points":2,"stem":"0.9 mol 单原子理想气体初温 300 K，可逆绝热膨胀至原体积的 1.7 倍。末温约是多少？","options":["\\(230.1\\,\\mathrm{K}\\)","\\(427.3\\,\\mathrm{K}\\)","\\(176.5\\,\\mathrm{K}\\)","\\(210.6\\,\\mathrm{K}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-adiabatic-expansion-temperature","explanation":"可逆绝热过程 \\(TV^{\\gamma-1}\\) 不变，单原子气体 \\(\\gamma=5/3\\)。据此由体积比求温度比。 得 \\(210.6\\,\\mathrm{K}\\)。"},
  {"id":"t-adiabatic-compression-work-1","type":"single","points":3,"stem":"0.9 mol 刚性双原子理想气体初温为 280 K，经可逆绝热压缩，体积缩小为原来的 1/1.6。外界对气体做的功约是多少？","options":["\\(1517\\,\\mathrm{J}\\)","\\(1083\\,\\mathrm{J}\\)","\\(433.3\\,\\mathrm{J}\\)","\\(984.7\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-adiabatic-compression-work","explanation":"忽略振动时 \\(\\gamma=7/5\\)，由 \\(TV^{\\gamma-1}=\\text{常量}\\) 求末温。因 \\(Q=0\\)，外界做功等于 \\(\\Delta U=\\tfrac52nR(T_2-T_1)\\)。 得 \\(1083\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-linear-path-work-1","type":"single","points":2,"stem":"一份气体在准静态膨胀中体积增加 2 L，压强从 75 kPa 随体积线性升到 170 kPa。气体对外做功是多少？","options":["\\(150\\,\\mathrm{J}\\)","\\(245\\,\\mathrm{J}\\)","\\(190\\,\\mathrm{J}\\)","\\(340\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-linear-path-work","explanation":"沿直线过程，\\(p\\!-\\!V\\) 图下方的梯形面积等于平均压强乘体积变化。\\(1\\,\\mathrm{kPa\\,L}=1\\,\\mathrm J\\)。 得 \\(245\\,\\mathrm{J}\\)。"},
  {"id":"t-rectangular-cycle-1","type":"multiple","points":2,"stem":"理想气体沿顺时针矩形循环运行。两条等压边压强分别为 85 kPa 和 180 kPa，两条等容边体积分别为 3 L 和 8 L。关于整个循环，下列说法正确的是哪些？","options":["气体净对外做功为 \\(475\\,\\mathrm{J}\\)。","一周后气体内能变化为零。","高压等压边与低压等压边的体积功大小相等。","一周后气体总吸热一定为零。","沿两个等容段，体积功均为零。"],"answer":[0,1,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-rectangular-cycle","explanation":"顺时针循环的净功为矩形面积 \\((p_h-p_l)(V_h-V_l)\\)。回到起态时 \\(\\Delta U=0\\)，净吸热等于净功，非零。等容段 \\(\\mathrm dV=0\\)，两条等压边体积改变量大小相同但压强不同。"},
  {"id":"t-isobaric-monatomic-budget-1","type":"multiple","points":2,"stem":"1 mol 单原子理想气体在恒压下从 300 K 加热至 324 K，只做体积功。下列数量关系正确的是哪些？","options":["气体对外做功 \\(199.5\\,\\mathrm{J}\\)。","气体吸收热量 \\(498.8\\,\\mathrm{J}\\)。","气体的焓不变。","气体的内能增加 \\(299.3\\,\\mathrm{J}\\)。","气体吸热等于内能的增加量。"],"answer":[0,1,3],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isobaric-monatomic-budget","explanation":"定压时 \\(W=nR\\Delta T\\)，内能变化为 \\(nC_V\\Delta T\\)，焓变化 \\(nC_p\\Delta T\\) 等于吸热。单原子气体 \\(C_V=3R/2,\\ C_p=5R/2\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-two-stage-heating-expansion-1","type":"single","points":3,"stem":"1 mol 单原子理想气体先定容地从 285 K 加热到 310 K，接着在 310 K 可逆等温膨胀，体积变为原来的 1.4 倍。两阶段总吸热约是多少？","options":["\\(311.8\\,\\mathrm{J}\\)","\\(1387\\,\\mathrm{J}\\)","\\(867.2\\,\\mathrm{J}\\)","\\(1179\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-two-stage-heating-expansion","explanation":"第一段等容，\\(Q_1=\\Delta U_1=\\tfrac32nR(T_2-T_1)\\)。第二段等温，\\(Q_2=W_2=nRT_2\\ln(V_f/V_i)\\)。总吸热为两段之和。 得 \\(1179\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-polytropic-work-1","type":"single","points":3,"stem":"气体从 2.5 L 准静态膨胀至 5 L，初压 90 kPa。过程满足 \\(pV^{1.22}\\) 为常量。气体对外做功约是多少？","options":["\\(156\\,\\mathrm{J}\\)","\\(225\\,\\mathrm{J}\\)","\\(144.6\\,\\mathrm{J}\\)","\\(96.59\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-polytropic-work","explanation":"设 \\(pV^s=C\\)，把 \\(p=CV^{-s}\\) 代入体积功积分，可得 \\(W=(p_2V_2-p_1V_1)/(1-s)\\)。用状态间的多方关系求 \\(p_2\\)。 得 \\(144.6\\,\\mathrm{J}\\)。","reference":"当 \\(a\\ne-1\\) 时，\\(\\int x^a\\,\\mathrm dx=x^{a+1}/(a+1)+C\\)。"},
  {"id":"t-compression-energy-balance-1","type":"multiple","points":2,"stem":"气体在带活塞的容器中被缓慢压缩。过程中气体吸热 900 J，外界对气体做功 250 J，忽略其他能量交换。下列说法正确的是哪些？","options":["气体的内能变化等于 \\(650\\,\\mathrm{J}\\)。","气体一定放热。","气体内能增加 \\(1150\\,\\mathrm{J}\\)。","热量等于外界对气体做的功。","按气体对外做功为正的约定，气体的体积功为 \\(-250\\,\\mathrm{J}\\)。"],"answer":[2,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-compression-energy-balance","explanation":"采用 \\(\\Delta U=Q-W_{\\mathrm{by}}\\)。吸热 \\(Q>0\\)，压缩时气体对外做功 \\(W_{\\mathrm{by}}<0\\)。内能增加量等于吸热量与外界做功之和。"},
  {"id":"t-carnot-absorbed-heat-1","type":"single","points":3,"stem":"一台可逆热机在 470 K 的高温热源与 255 K 的低温热源之间工作，每循环对外净做功 600 J。每循环从高温热源吸热约是多少？","options":["\\(600\\,\\mathrm{J}\\)","\\(1312\\,\\mathrm{J}\\)","\\(1106\\,\\mathrm{J}\\)","\\(274.5\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-absorbed-heat","explanation":"卡诺效率 \\(\\eta=1-T_\\mathrm c/T_\\mathrm h\\)，同时 \\(\\eta=W/Q_\\mathrm h\\)。把两式联立求 \\(Q_\\mathrm h\\)。 得 \\(1312\\,\\mathrm{J}\\)。"},
  {"id":"t-carnot-heat-balance-1","type":"multiple","points":2,"stem":"卡诺热机在 510 K、290 K 的两个热源之间运行，每周吸收高温热量 1000 J。下列说法正确的是哪些？","options":["工质每周的熵变为零。","两热源的总熵在每周内严格增加。","每周净输出功约 \\(431.4\\,\\mathrm{J}\\)。","高温热源每周熵增约 \\(1.961\\,\\mathrm{J\\,K^{-1}}\\)。","每周向低温热源放热约 \\(568.6\\,\\mathrm{J}\\)。"],"answer":[0,2,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-heat-balance","explanation":"卡诺循环可逆，有 \\(Q_\\mathrm h/T_\\mathrm h=Q_\\mathrm c/T_\\mathrm c\\)。净功为两热量之差，工质状态复原。低温热源的正熵变与高温热源的负熵变抵消。"},
  {"id":"t-carnot-refrigerator-1","type":"multiple","points":2,"stem":"可逆制冷机的冷端为 247 K、热端为 315 K，每周期从冷端移走 500 J。下列说法正确的是哪些？","options":["热端每周期得到的热量小于冷端失去的热量。","热端每周期得到热量 \\(637.7\\,\\mathrm{J}\\)。","外界每周期至少输入功 \\(137.7\\,\\mathrm{J}\\)。","制冷系数约为 \\(3.632\\)。","在保持热端温度不变时，降低冷端温度会提高制冷系数。"],"answer":[1,2,3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-carnot-refrigerator","explanation":"制冷机的卡诺制冷系数为 \\(T_\\mathrm c/(T_\\mathrm h-T_\\mathrm c)\\)。由 \\(W=Q_\\mathrm c/\\varepsilon\\) 求输入功，再用 \\(Q_\\mathrm h=Q_\\mathrm c+W\\)。冷端温度降低时制冷更困难。"},
  {"id":"t-reservoir-transfer-entropy-1","type":"single","points":2,"stem":"1000 J 热量自行从恒温 380 K 的热源传给恒温 265 K 的热源，无其他作用。两个热源的总熵增约是多少？","options":["\\(6.405\\,\\mathrm{J\\,K^{-1}}\\)","\\(1.142\\,\\mathrm{J\\,K^{-1}}\\)","\\(-1.142\\,\\mathrm{J\\,K^{-1}}\\)","\\(3.774\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-reservoir-transfer-entropy","explanation":"冷热源各自在恒温下交换热量。热源失热熵变 \\(-Q/T_\\mathrm h\\)，冷源得热熵变 \\(Q/T_\\mathrm c\\)，二者相加。 得 \\(1.142\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-insulated-free-expansion-1","type":"multiple","points":2,"stem":"0.8 mol 理想气体在绝热刚性容器中，撤去隔板后向真空自由膨胀，最终占据原来的 1.45 倍体积。下列说法正确的是哪些？","options":["初态和末态温度相同。","气体和外界之间没有热传递，也没有体积功。","这个过程可以仅靠气体自身逆向恢复而不引起其他变化。","因为过程绝热，所以气体熵变为零。","气体熵增约 \\(2.471\\,\\mathrm{J\\,K^{-1}}\\)。"],"answer":[0,1,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-insulated-free-expansion","explanation":"自由膨胀无外压，且绝热，因此 \\(\\Delta U=0\\)。理想气体的内能只由温度决定，初末温度相同。熵是状态函数，可用连接两平衡态的可逆等温膨胀计算 \\(\\Delta S=nR\\ln(V_f/V_i)>0\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-finite-bodies-entropy-1","type":"single","points":3,"stem":"绝热容器内有两个只交换热量的物体。第一物体热容 180 J/K、初温 300 K，第二物体热容 270 J/K、初温 365 K。热容均为常数。到达共同温度后，两物体总熵增加约多少？","options":["\\(2.047\\,\\mathrm{J\\,K^{-1}}\\)","\\(22\\,\\mathrm{J\\,K^{-1}}\\)","\\(19.95\\,\\mathrm{J\\,K^{-1}}\\)","\\(-2.047\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-finite-bodies-entropy","explanation":"先用能量守恒求共同温度 \\(T_f=(C_1T_1+C_2T_2)/(C_1+C_2)\\)。各物体的熵变分别是 \\(C_i\\ln(T_f/T_i)\\)，将一正一负的两项相加。 得 \\(2.047\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-ideal-mixture-entropy-1","type":"single","points":3,"stem":"绝热刚性容器中有 1.1 mol A 和 2.4 mol B，均为不同的理想气体，初态分置两隔间，温度和压强都相同。撤去隔板后两气体完全混合。混合熵约是多少？","options":["\\(18.11\\,\\mathrm{J\\,K^{-1}}\\)","\\(29.1\\,\\mathrm{J\\,K^{-1}}\\)","\\(10.59\\,\\mathrm{J\\,K^{-1}}\\)","\\(7.528\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-ideal-mixture-entropy","explanation":"相同初始温压下，初体积占比等于摩尔分数 \\(x_i\\)。混合后每一组分可及体积为总容积，等效可逆等温膨胀的熵增为 \\(-n_iR\\ln x_i\\)。相加得到混合熵。 得 \\(18.11\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-entropy-temperature-volume-1","type":"single","points":3,"stem":"1.15 mol 刚性双原子理想气体从 285 K 变为 342 K，体积同时扩大至原来的 1.25 倍。忽略振动，求气体的熵变。","options":["\\(2.224\\,\\mathrm{J\\,K^{-1}}\\)","\\(6.491\\,\\mathrm{J\\,K^{-1}}\\)","\\(2.133\\,\\mathrm{J\\,K^{-1}}\\)","\\(4.358\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-entropy-temperature-volume","explanation":"可选先等容升温再等温膨胀作为可逆辅助路径。分别积出 \\(nC_V\\ln(T_2/T_1)\\) 和 \\(nR\\ln(V_2/V_1)\\)，相加。 得 \\(6.491\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-steady-conduction-1","type":"single","points":2,"stem":"面积为 0.14 m²、厚度 14 mm 的均匀平板，导热系数为 0.42 W/(m·K)，两表面恒温 340 K 和 293 K。忽略侧面漏热，稳定导热速率约是多少？","options":["\\(0.1974\\,\\mathrm W\\)","\\(394.8\\,\\mathrm W\\)","\\(1410\\,\\mathrm W\\)","\\(197.4\\,\\mathrm W\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-steady-conduction","explanation":"稳定的一维傅里叶导热通量为 \\(j_Q=k(T_h-T_c)/L\\)。总导热速率还要乘面积，厚度从毫米换成米。 得 \\(197.4\\,\\mathrm W\\)。"},
  {"id":"t-series-conduction-1","type":"single","points":3,"stem":"面积 0.2 m² 的双层墙，第一层厚 25 mm、导热系数 0.21 W/(m·K)，第二层厚 42 mm、导热系数 0.48 W/(m·K)。外表面温差为 31 K，层间接触热阻忽略。稳定导热功率约是多少？","options":["\\(30.02\\,\\mathrm W\\)","\\(63.85\\,\\mathrm W\\)","\\(70.86\\,\\mathrm W\\)","\\(52.08\\,\\mathrm W\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-series-conduction","explanation":"两层串联时同一功率穿过每层，热阻为 \\(L/(kA)\\)。把热阻相加，外表面温差除以总热阻。 得 \\(30.02\\,\\mathrm W\\)。"},
  {"id":"t-couette-shear-1","type":"single","points":2,"stem":"两块平行板间夹有牛顿流体，板间距 4 mm，流体动力黏度 0.06 Pa·s。下板固定，上板以 0.45 m/s 匀速移动。忽略边缘效应，若上板接触面积 0.11 m²，流体对上板黏滞力的大小约是多少？","options":["\\(0.0007425\\,\\mathrm N\\)","\\(6.75\\,\\mathrm N\\)","\\(0.7425\\,\\mathrm N\\)","\\(1.485\\,\\mathrm N\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-couette-shear","explanation":"平板间的速度梯度为 \\(u/h\\)。牛顿黏性定律给出剪应力 \\(\\eta u/h\\)，再乘受力面积。 得 \\(0.7425\\,\\mathrm N\\)。"},
  {"id":"t-fick-steady-flow-1","type":"single","points":2,"stem":"两侧浓度分别为 1.75、0.48 mol/m³，扩散距离 2 cm，面积 0.03 m²。浓度沿程线性，扩散系数为 \\(1.6\\times10^{-5}\\,\\mathrm{m^2\\,s^{-1}}\\)。求通过整个截面的物质的量输运速率大小。","options":["\\(3.048\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.003048\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.001016\\,\\mathrm{mol\\,s^{-1}}\\)","\\(5.352\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-fick-steady-flow","explanation":"菲克定律给出的通量大小为 \\(D|\\mathrm dc/\\mathrm dx|\\)，浓度线性时是 \\(D|c_1-c_2|/L\\)。乘以截面积得到总速率。 得 \\(3.048\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)。"},
  {"id":"t-linear-expansion-1","type":"single","points":1,"stem":"自由伸缩的细杆初长 1.1 m，线膨胀系数近似恒为 \\(1.1\\times10^{-5}\\,\\mathrm{K^{-1}}\\)。升温 39 K 后，长度增加量约是多少？","options":["\\(0.0004719\\,\\mathrm m\\)","\\(0.001416\\,\\mathrm m\\)","\\(0.000429\\,\\mathrm m\\)","\\(4.719\\times10^{-7}\\,\\mathrm m\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-linear-expansion","explanation":"一阶近似下 \\(\\Delta L=\\alpha L_0\\Delta T\\)。长度和温差直接以题设单位代入。 得 \\(0.0004719\\,\\mathrm m\\)。"},
  {"id":"t-curved-interfaces-1","type":"multiple","points":2,"stem":"一个液滴与一个薄壁肥皂泡的半径均为 0.55 mm，界面张力均为 0.061 N/m。忽略重力导致的变形。下列说法正确的是哪些？","options":["肥皂泡内外压差约 \\(443.6\\,\\mathrm{Pa}\\)。","液滴内外压差约 \\(221.8\\,\\mathrm{Pa}\\)。","相同界面张力下，把肥皂泡的半径加倍，其内外压差减半。","肥皂膜只有一个气液界面。","液滴内部压强小于外界。"],"answer":[0,1,2],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-curved-interfaces","explanation":"球形单界面的拉普拉斯压差是 \\(2\\sigma/r\\)。液滴仅一个界面，薄壁肥皂泡近似有两个等半径的界面，两个压差相加。压差均与半径成反比。"},
  {"id":"t-capillary-rise-1","type":"single","points":2,"stem":"毛细管内半径 0.3 mm，液体完全润湿管壁，液体密度 900 kg/m³、表面张力 0.046 N/m。忽略管外液面变化，管内液面约上升多高？","options":["\\(0.01737\\,\\mathrm m\\)","\\(0.03473\\,\\mathrm m\\)","\\(34.73\\,\\mathrm m\\)","\\(0.06947\\,\\mathrm m\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-capillary-rise","explanation":"完全润湿时接触角为零。竖直表面张力为 \\(2\\pi r\\sigma\\)，平衡液柱重力 \\(\\rho g\\pi r^2 h\\)。联立求高度。 得 \\(0.03473\\,\\mathrm m\\)。","reference":"重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。"},
  {"id":"t-heating-partial-vaporization-1","type":"single","points":3,"stem":"常压下质量 0.14 kg 的水从 18 ℃ 加热到 100 ℃，随后其质量的 14% 在 100 ℃ 汽化。取水的比热容为 4180 J/(kg·K)，汽化潜热为 \\(2.25\\times10^{6}\\,\\mathrm{J\\,kg^{-1}}\\)。忽略热损失，总吸热约是多少？","options":["\\(4.41\\times10^{4}\\,\\mathrm{J}\\)","\\(3.63\\times10^{5}\\,\\mathrm{J}\\)","\\(4.799\\times10^{4}\\,\\mathrm{J}\\)","\\(9.209\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 8 章","family":"t-heating-partial-vaporization","explanation":"升温吸热 \\(Q_1=mc\\Delta T\\)。汽化阶段只用实际汽化的质量乘潜热，\\(Q_2=mfL_v\\)。总吸热为两项之和。 得 \\(9.209\\times10^{4}\\,\\mathrm{J}\\)。"},
  {"id":"t-reversible-melting-entropy-1","type":"single","points":2,"stem":"某纯物质在规定压强下的熔点为 240 K，熔化潜热为 \\(2.8\\times10^{5}\\,\\mathrm{J\\,kg^{-1}}\\)。将处于熔点的 0.15 kg 固体缓慢熔化成同温液体。物质的熵变约是多少？","options":["\\(-175\\,\\mathrm{J\\,K^{-1}}\\)","\\(4.2\\times10^{4}\\,\\mathrm{J\\,K^{-1}}\\)","\\(175\\,\\mathrm{J\\,K^{-1}}\\)","\\(1167\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-reversible-melting-entropy","explanation":"熔点处可逆等温熔化需吸收 \\(Q=mL_f\\)。等温可逆相变的熵变为 \\(Q/T_m\\)，吸热时为正。 得 \\(175\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-clapeyron-slope-1","type":"single","points":3,"stem":"某纯物质处在 320 K 的液气平衡线上。该点的摩尔汽化潜热为 28 kJ/mol，气相和液相的摩尔体积差为 0.017 m³/mol。求该点饱和压强对温度的斜率。","options":["\\(-5147\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(5147\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(16.08\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(87.5\\,\\mathrm{Pa\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-clapeyron-slope","explanation":"克拉珀龙方程 \\( \\mathrm dp_\\mathrm{sat}/\\mathrm dT=L_m/[T(V_{m,g}-V_{m,l})] \\)。把摩尔潜热从 kJ/mol 换成 J/mol 后代入，气相摩尔体积更大，因此斜率为正。 得 \\(5147\\,\\mathrm{Pa\\,K^{-1}}\\)。"},
  {"id":"t-without-replacement-2","type":"single","points":1,"stem":"袋中有 6 个红球、5 个蓝球。一次不放回地随机抽取两个球，两个都是红球的概率约是多少？","options":["\\(0.1364\\)","\\(0.2727\\)","\\(0.2975\\)","\\(0.5455\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-without-replacement","explanation":"在不放回抽样中，第二次取红的条件概率为 \\((r-1)/(N-1)\\)。与首次概率 \\(r/N\\) 相乘。 得 \\(0.2727\\)。"},
  {"id":"t-random-walk-origin-2","type":"single","points":2,"stem":"微粒从原点出发，在一条直线上独立地走 6 步，每步等概率向左或向右移动一个单位。最后回到原点的概率约是多少？","options":["\\(0.3125\\)","\\(0.1429\\)","\\(0.5\\)","\\(0.01562\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-random-walk-origin","explanation":"回到原点要求左右各走一半步数。共有 \\(\\binom{N}{N/2}\\) 条这样的序列，总序列数为 \\(2^N\\)。 得 \\(0.3125\\)。"},
  {"id":"t-power-density-2","type":"single","points":3,"stem":"连续随机变量的概率密度在 0 到 3 之间为 \\(f(x)=C x^{2}\\)，区间外为零。该变量落在 0 到 1 之间的概率约是多少？","options":["\\(0.01235\\)","\\(0.963\\)","\\(0.03704\\)","\\(0.3333\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-power-density","explanation":"归一化要求分母为 \\(\\int_0^{L}x^a\\,\\mathrm dx\\)。区间概率是 \\(\\int_0^b x^a\\,\\mathrm dx/\\int_0^L x^a\\,\\mathrm dx=(b/L)^{a+1}\\)。 得 \\(0.03704\\)。","reference":"当 \\(a>-1\\) 时，\\(\\int_0^L x^a\\,\\mathrm dx=L^{a+1}/(a+1)\\)。"},
  {"id":"t-rigid-vessel-temperature-2","type":"single","points":1,"stem":"密闭刚性容器里装有一定量理想气体。气体从 260 K 缓慢升温到 349 K，初态绝对压强为 97 kPa。末态压强约是多少？","options":["\\(97\\,\\mathrm{kPa}\\)","\\(72.26\\,\\mathrm{kPa}\\)","\\(380.4\\,\\mathrm{kPa}\\)","\\(130.2\\,\\mathrm{kPa}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-rigid-vessel-temperature","explanation":"容积和物质的量保持恒定，状态方程给出 \\(p_2/p_1=T_2/T_1\\)。 得 \\(130.2\\,\\mathrm{kPa}\\)。"},
  {"id":"t-dalton-partial-pressure-2","type":"single","points":1,"stem":"两种互不反应的理想气体形成均匀混合气。A 组分有 3 mol，B 组分有 9 mol，总压强为 151 kPa。A 的分压约是多少？","options":["\\(37.75\\,\\mathrm{kPa}\\)","\\(113.2\\,\\mathrm{kPa}\\)","\\(12.58\\,\\mathrm{kPa}\\)","\\(50.33\\,\\mathrm{kPa}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 2 章","family":"t-dalton-partial-pressure","explanation":"各组分在同一温度和体积下服从状态方程，分压占总压的比例等于摩尔分数。 得 \\(37.75\\,\\mathrm{kPa}\\)。"},
  {"id":"t-joined-vessels-2","type":"single","points":2,"stem":"两个容积分别为 4 L、10 L 的刚性容器分别装有理想气体，压强为 210 kPa、69 kPa。两容器均已与同一恒温浴达到热平衡，打开连通阀直至新平衡。末态总压强约是多少？","options":["\\(109.3\\,\\mathrm{kPa}\\)","\\(169.7\\,\\mathrm{kPa}\\)","\\(279\\,\\mathrm{kPa}\\)","\\(139.5\\,\\mathrm{kPa}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-joined-vessels","explanation":"由初态两侧总物质的量守恒，且温度相同，有 \\(p_f(V_1+V_2)=p_1V_1+p_2V_2\\)。 得 \\(109.3\\,\\mathrm{kPa}\\)。"},
  {"id":"t-gas-mass-pressure-2","type":"single","points":2,"stem":"2.5 kg 氮气装在体积为 0.9 立方米的容器内，温度为 292 K。把氮气视为理想气体，取其摩尔质量 28 g/mol，求绝对压强。","options":["\\(2.408\\times10^{5}\\,\\mathrm{Pa}\\)","\\(6744\\,\\mathrm{Pa}\\)","\\(4.817\\times10^{5}\\,\\mathrm{Pa}\\)","\\(2.408\\times10^{8}\\,\\mathrm{Pa}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-gas-mass-pressure","explanation":"先以 \\(n=m/M\\) 将质量换成摩尔数，再由 \\(p=nRT/V\\) 代入。注意 \\(28\\,\\mathrm{g\\,mol^{-1}}=0.028\\,\\mathrm{kg\\,mol^{-1}}\\)。 得 \\(2.408\\times10^{5}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-van-der-waals-pressure-2","type":"single","points":3,"stem":"某气体每摩尔体积为 0.97 L/mol、温度为 281 K。范德瓦尔斯参数分别为 \\(0.143\\,\\mathrm{Pa\\,m^6\\,mol^{-2}}\\) 和 \\(0.000345\\,\\mathrm{m^3\\,mol^{-1}}\\)。求压强。","options":["\\(3.586\\times10^{6}\\,\\mathrm{Pa}\\)","\\(2.408\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.89\\times10^{6}\\,\\mathrm{Pa}\\)","\\(1.625\\times10^{6}\\,\\mathrm{Pa}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-van-der-waals-pressure","explanation":"采用摩尔体积形式，\\(p=RT/(V_m-b)-a/V_m^2\\)。体积应先换成 \\(\\mathrm{m^3\\,mol^{-1}}\\)。 得 \\(3.586\\times10^{6}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-mean-free-path-2","type":"single","points":2,"stem":"温度为 277 K、压强为 130 Pa 的稀薄气体由有效直径 0.3 nm 的相同硬球分子组成。估算分子的平均自由程。","options":["\\(0.0002311\\,\\mathrm m\\)","\\(7.357\\times10^{-5}\\,\\mathrm m\\)","\\(3.679\\times10^{-5}\\,\\mathrm m\\)","\\(0.000104\\,\\mathrm m\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-mean-free-path","explanation":"由 \\(n=p/(k_\\mathrm BT)\\) 求数密度。相同硬球的平均自由程是 \\(\\lambda=1/(\\sqrt2\\,\\pi d^2 n)\\)，其中 \\(\\pi d^2\\) 为碰撞截面。 得 \\(7.357\\times10^{-5}\\,\\mathrm m\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-rms-temperature-2","type":"single","points":2,"stem":"一种理想气体的摩尔质量为 32 g/mol，分子的方均根速率为 460 m/s。求该气体的热力学温度。","options":["\\(271.5\\,\\mathrm{K}\\)","\\(135.7\\,\\mathrm{K}\\)","\\(814.4\\,\\mathrm{K}\\)","\\(407.2\\,\\mathrm{K}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-rms-temperature","explanation":"平均平动动能为 \\(3k_\\mathrm BT/2\\)，所以 \\(v_{\\mathrm{rms}}^2=3RT/M\\)。摩尔质量应以 kg/mol 代入。 得 \\(271.5\\,\\mathrm{K}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-kinetic-pressure-2","type":"single","points":2,"stem":"理想气体的压强为 94 kPa，质量密度为 0.75 kg/m³。估计分子的方均根速率。","options":["\\(867.2\\,\\mathrm{m\\,s^{-1}}\\)","\\(613.2\\,\\mathrm{m\\,s^{-1}}\\)","\\(354\\,\\mathrm{m\\,s^{-1}}\\)","\\(433.6\\,\\mathrm{m\\,s^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-kinetic-pressure","explanation":"分子运动论给出 \\(p=\\rho v_{\\mathrm{rms}}^2/3\\)，压强换成 Pa 后求平方根。 得 \\(613.2\\,\\mathrm{m\\,s^{-1}}\\)。"},
  {"id":"t-collision-frequency-2","type":"single","points":1,"stem":"某稀薄气体分子的平均速率为 395 m/s，平均自由程为 94 nm。估计单个分子的平均碰撞频率。","options":["\\(1.051\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(4.202\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(4.202\\,\\mathrm{s^{-1}}\\)","\\(8.404\\times10^{9}\\,\\mathrm{s^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-collision-frequency","explanation":"在平均意义下，单位时间经历的自由程数约为 \\(\\bar v/\\lambda\\)。将 nm 换成 m 再相除。 得 \\(4.202\\times10^{9}\\,\\mathrm{s^{-1}}\\)。"},
  {"id":"t-maxwell-temperature-ratio-2","type":"single","points":1,"stem":"同一种气体分别处于 270 K 和 345 K 的平衡态。后者与前者的最概然速率之比约是多少？","options":["\\(1.278\\)","\\(0.2778\\)","\\(1.13\\)","\\(0.8847\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-temperature-ratio","explanation":"同种气体的分子质量相同，最概然速率 \\(v_p=\\sqrt{2RT/M}\\) 与绝对温度的平方根成正比。 得 \\(1.13\\)。"},
  {"id":"t-barometric-ratio-2","type":"single","points":3,"stem":"把大气视为均匀摩尔质量为 28 g/mol 的理想气体，设温度恒为 274 K、重力加速度不随高度改变。海拔比基准面高 2050 m 处的气压是基准面气压的多少倍？","options":["\\(0.219\\)","\\(0.781\\)","\\(1.28\\)","\\(0.61\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-barometric-ratio","explanation":"将静力平衡 \\(\\mathrm dp/\\mathrm dz=-\\rho g\\) 与 \\(\\rho=Mp/(RT)\\) 联立并积分，得到 \\(p(z)/p(0)=\\exp[-Mgz/(RT)]\\)。 得 \\(0.781\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-two-level-population-2","type":"single","points":3,"stem":"一批可分辨的弱相互作用粒子在 280 K 达到热平衡。每个粒子仅能处在两个非简并能级，上能级比下能级高 \\(5.296\\times10^{-21}\\,\\mathrm{J}\\)。约有多大比例的粒子在上能级？","options":["\\(0.7974\\)","\\(0.2026\\)","\\(0.2541\\)","\\(0.06457\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-two-level-population","explanation":"以上能级和下能级的玻尔兹曼权重分别为 \\(\\exp[-\\Delta E/(k_\\mathrm BT)]\\) 和 1，将上能级权重除以两权重之和。 得 \\(0.2026\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-mixture-equipartition-2","type":"single","points":2,"stem":"2 mol 单原子理想气体与 3 mol 刚性双原子理想气体混合，在 281 K 达到热平衡。忽略双原子分子的振动，混合气体的总内能约是多少？","options":["\\(1.752\\times10^{4}\\,\\mathrm{J}\\)","\\(2.453\\times10^{4}\\,\\mathrm{J}\\)","\\(2.92\\times10^{4}\\,\\mathrm{J}\\)","\\(4.906\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-mixture-equipartition","explanation":"按能量均分，单原子有 3 个自由度，刚性双原子有 5 个自由度。分别计算 \\(f nRT/2\\) 后相加。 得 \\(2.453\\times10^{4}\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-maxwell-concepts-2","type":"multiple","points":2,"stem":"温度为 301 K 的氧气和温度为 308 K 的氮气都处于无宏观流动的平衡态。取氧气、氮气的摩尔质量分别为 32 和 28 g/mol。关于它们的麦克斯韦速率分布，正确的是哪些？","options":["任一种气体的分子平均速度矢量为零。","氧气的最概然速率低于氮气。","氧气与氮气的最概然速率之比约为 \\(0.9247\\)。","同一种气体升温，最概然速率增大。","在同一平衡态，任一种气体的最概然速率大于其方均根速率。"],"answer":[0,1,2,3],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-concepts","explanation":"最概然速率为 \\(v_p=\\sqrt{2RT/M}\\)。两种气体的速率之比由各自的 \\(T/M\\) 决定；升温则最概然速率增大。最概然速率小于方均根速率。平衡态无宏观流动，各方向的速度矢量平均为零。"},
  {"id":"t-isobaric-work-2","type":"single","points":1,"stem":"1.5 mol 理想气体在压强不变的情况下从 293 K 升至 330 K。气体对外做的体积功约是多少？","options":["\\(1154\\,\\mathrm{J}\\)","\\(230.7\\,\\mathrm{J}\\)","\\(461.4\\,\\mathrm{J}\\)","\\(692.1\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isobaric-work","explanation":"等压过程 \\(W=p(V_2-V_1)\\)。由状态方程，\\(p(V_2-V_1)=nR(T_2-T_1)\\)。 得 \\(461.4\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isochoric-heating-2","type":"single","points":1,"stem":"0.9 mol 单原子理想气体在刚性容器中从 293 K 加热到 324 K，仅交换热量。气体吸热约是多少？","options":["\\(347.9\\,\\mathrm{J}\\)","\\(232\\,\\mathrm{J}\\)","\\(579.9\\,\\mathrm{J}\\)","\\(695.9\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isochoric-heating","explanation":"定容过程没有体积功，吸热等于内能增加。单原子理想气体的定容摩尔热容为 \\(3R/2\\)。 得 \\(347.9\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isothermal-work-2","type":"single","points":2,"stem":"0.85 mol 理想气体在 282 K 从体积 3 L 可逆等温膨胀到 5.49 L。气体对外做功约是多少？","options":["\\(1654\\,\\mathrm{J}\\)","\\(602.2\\,\\mathrm{J}\\)","\\(903.9\\,\\mathrm{J}\\)","\\(1204\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isothermal-work","explanation":"准静态做功为 \\(\\int p\\,\\mathrm dV\\)。等温时 \\(p=nRT/V\\)，积分得 \\(W=nRT\\ln(V_2/V_1)\\)。 得 \\(1204\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-adiabatic-expansion-temperature-2","type":"single","points":2,"stem":"1.1 mol 单原子理想气体初温 310 K，可逆绝热膨胀至原体积的 1.9 倍。末温约是多少？","options":["\\(202.1\\,\\mathrm{K}\\)","\\(163.2\\,\\mathrm{K}\\)","\\(475.6\\,\\mathrm{K}\\)","\\(224.9\\,\\mathrm{K}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-adiabatic-expansion-temperature","explanation":"可逆绝热过程 \\(TV^{\\gamma-1}\\) 不变，单原子气体 \\(\\gamma=5/3\\)。据此由体积比求温度比。 得 \\(202.1\\,\\mathrm{K}\\)。"},
  {"id":"t-adiabatic-compression-work-2","type":"single","points":3,"stem":"1.2 mol 刚性双原子理想气体初温为 290 K，经可逆绝热压缩，体积缩小为原来的 1/1.84。外界对气体做的功约是多少？","options":["\\(2797\\,\\mathrm{J}\\)","\\(1998\\,\\mathrm{J}\\)","\\(799.2\\,\\mathrm{J}\\)","\\(1764\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-adiabatic-compression-work","explanation":"忽略振动时 \\(\\gamma=7/5\\)，由 \\(TV^{\\gamma-1}=\\text{常量}\\) 求末温。因 \\(Q=0\\)，外界做功等于 \\(\\Delta U=\\tfrac52nR(T_2-T_1)\\)。 得 \\(1998\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-linear-path-work-2","type":"single","points":2,"stem":"一份气体在准静态膨胀中体积增加 2.4 L，压强从 80 kPa 随体积线性升到 182 kPa。气体对外做功是多少？","options":["\\(314.4\\,\\mathrm{J}\\)","\\(192\\,\\mathrm{J}\\)","\\(436.8\\,\\mathrm{J}\\)","\\(244.8\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-linear-path-work","explanation":"沿直线过程，\\(p\\!-\\!V\\) 图下方的梯形面积等于平均压强乘体积变化。\\(1\\,\\mathrm{kPa\\,L}=1\\,\\mathrm J\\)。 得 \\(314.4\\,\\mathrm{J}\\)。"},
  {"id":"t-rectangular-cycle-2","type":"multiple","points":2,"stem":"理想气体沿顺时针矩形循环运行。两条等压边压强分别为 90 kPa 和 195 kPa，两条等容边体积分别为 4 L 和 10 L。关于整个循环，下列说法正确的是哪些？","options":["一周后气体总吸热一定为零。","高压等压边与低压等压边的体积功大小相等。","沿两个等容段，体积功均为零。","一周后气体内能变化为零。","气体净对外做功为 \\(630\\,\\mathrm{J}\\)。"],"answer":[2,3,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-rectangular-cycle","explanation":"顺时针循环的净功为矩形面积 \\((p_h-p_l)(V_h-V_l)\\)。回到起态时 \\(\\Delta U=0\\)，净吸热等于净功，非零。等容段 \\(\\mathrm dV=0\\)，两条等压边体积改变量大小相同但压强不同。"},
  {"id":"t-isobaric-monatomic-budget-2","type":"multiple","points":2,"stem":"1.5 mol 单原子理想气体在恒压下从 306 K 加热至 337 K，只做体积功。下列数量关系正确的是哪些？","options":["气体对外做功 \\(386.6\\,\\mathrm{J}\\)。","气体吸收热量 \\(966.5\\,\\mathrm{J}\\)。","气体的内能增加 \\(579.9\\,\\mathrm{J}\\)。","气体的焓不变。","气体吸热等于内能的增加量。"],"answer":[0,1,2],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isobaric-monatomic-budget","explanation":"定压时 \\(W=nR\\Delta T\\)，内能变化为 \\(nC_V\\Delta T\\)，焓变化 \\(nC_p\\Delta T\\) 等于吸热。单原子气体 \\(C_V=3R/2,\\ C_p=5R/2\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-two-stage-heating-expansion-2","type":"single","points":3,"stem":"1.4 mol 单原子理想气体先定容地从 290 K 加热到 320 K，接着在 320 K 可逆等温膨胀，体积变为原来的 1.6 倍。两阶段总吸热约是多少？","options":["\\(2274\\,\\mathrm{J}\\)","\\(1751\\,\\mathrm{J}\\)","\\(523.8\\,\\mathrm{J}\\)","\\(2624\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-two-stage-heating-expansion","explanation":"第一段等容，\\(Q_1=\\Delta U_1=\\tfrac32nR(T_2-T_1)\\)。第二段等温，\\(Q_2=W_2=nRT_2\\ln(V_f/V_i)\\)。总吸热为两段之和。 得 \\(2274\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-polytropic-work-2","type":"single","points":3,"stem":"气体从 3 L 准静态膨胀至 6.1 L，初压 98 kPa。过程满足 \\(pV^{1.265}\\) 为常量。气体对外做功约是多少？","options":["\\(303.8\\,\\mathrm{J}\\)","\\(190.2\\,\\mathrm{J}\\)","\\(208.6\\,\\mathrm{J}\\)","\\(123.8\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-polytropic-work","explanation":"设 \\(pV^s=C\\)，把 \\(p=CV^{-s}\\) 代入体积功积分，可得 \\(W=(p_2V_2-p_1V_1)/(1-s)\\)。用状态间的多方关系求 \\(p_2\\)。 得 \\(190.2\\,\\mathrm{J}\\)。","reference":"当 \\(a\\ne-1\\) 时，\\(\\int x^a\\,\\mathrm dx=x^{a+1}/(a+1)+C\\)。"},
  {"id":"t-compression-energy-balance-2","type":"multiple","points":2,"stem":"气体在带活塞的容器中被缓慢压缩。过程中气体吸热 1075 J，外界对气体做功 293 J，忽略其他能量交换。下列说法正确的是哪些？","options":["气体一定放热。","按气体对外做功为正的约定，气体的体积功为 \\(-293\\,\\mathrm{J}\\)。","气体内能增加 \\(1368\\,\\mathrm{J}\\)。","热量等于外界对气体做的功。","气体的内能变化等于 \\(782\\,\\mathrm{J}\\)。"],"answer":[1,2],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-compression-energy-balance","explanation":"采用 \\(\\Delta U=Q-W_{\\mathrm{by}}\\)。吸热 \\(Q>0\\)，压缩时气体对外做功 \\(W_{\\mathrm{by}}<0\\)。内能增加量等于吸热量与外界做功之和。"},
  {"id":"t-carnot-absorbed-heat-2","type":"single","points":3,"stem":"一台可逆热机在 505 K 的高温热源与 267 K 的低温热源之间工作，每循环对外净做功 770 J。每循环从高温热源吸热约是多少？","options":["\\(1456\\,\\mathrm{J}\\)","\\(770\\,\\mathrm{J}\\)","\\(1634\\,\\mathrm{J}\\)","\\(362.9\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-absorbed-heat","explanation":"卡诺效率 \\(\\eta=1-T_\\mathrm c/T_\\mathrm h\\)，同时 \\(\\eta=W/Q_\\mathrm h\\)。把两式联立求 \\(Q_\\mathrm h\\)。 得 \\(1634\\,\\mathrm{J}\\)。"},
  {"id":"t-carnot-heat-balance-2","type":"multiple","points":2,"stem":"卡诺热机在 542 K、299 K 的两个热源之间运行，每周吸收高温热量 1250 J。下列说法正确的是哪些？","options":["每周净输出功约 \\(560.4\\,\\mathrm{J}\\)。","高温热源每周熵增约 \\(2.306\\,\\mathrm{J\\,K^{-1}}\\)。","每周向低温热源放热约 \\(689.6\\,\\mathrm{J}\\)。","工质每周的熵变为零。","两热源的总熵在每周内严格增加。"],"answer":[0,2,3],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-heat-balance","explanation":"卡诺循环可逆，有 \\(Q_\\mathrm h/T_\\mathrm h=Q_\\mathrm c/T_\\mathrm c\\)。净功为两热量之差，工质状态复原。低温热源的正熵变与高温热源的负熵变抵消。"},
  {"id":"t-carnot-refrigerator-2","type":"multiple","points":2,"stem":"可逆制冷机的冷端为 252 K、热端为 321 K，每周期从冷端移走 600 J。下列说法正确的是哪些？","options":["热端每周期得到热量 \\(764.3\\,\\mathrm{J}\\)。","制冷系数约为 \\(3.652\\)。","热端每周期得到的热量小于冷端失去的热量。","在保持热端温度不变时，降低冷端温度会提高制冷系数。","外界每周期至少输入功 \\(164.3\\,\\mathrm{J}\\)。"],"answer":[0,1,4],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-carnot-refrigerator","explanation":"制冷机的卡诺制冷系数为 \\(T_\\mathrm c/(T_\\mathrm h-T_\\mathrm c)\\)。由 \\(W=Q_\\mathrm c/\\varepsilon\\) 求输入功，再用 \\(Q_\\mathrm h=Q_\\mathrm c+W\\)。冷端温度降低时制冷更困难。"},
  {"id":"t-reservoir-transfer-entropy-2","type":"single","points":2,"stem":"1280 J 热量自行从恒温 399 K 的热源传给恒温 277 K 的热源，无其他作用。两个热源的总熵增约是多少？","options":["\\(4.621\\,\\mathrm{J\\,K^{-1}}\\)","\\(-1.413\\,\\mathrm{J\\,K^{-1}}\\)","\\(7.829\\,\\mathrm{J\\,K^{-1}}\\)","\\(1.413\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-reservoir-transfer-entropy","explanation":"冷热源各自在恒温下交换热量。热源失热熵变 \\(-Q/T_\\mathrm h\\)，冷源得热熵变 \\(Q/T_\\mathrm c\\)，二者相加。 得 \\(1.413\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-insulated-free-expansion-2","type":"multiple","points":2,"stem":"1.1 mol 理想气体在绝热刚性容器中，撤去隔板后向真空自由膨胀，最终占据原来的 1.7 倍体积。下列说法正确的是哪些？","options":["这个过程可以仅靠气体自身逆向恢复而不引起其他变化。","气体熵增约 \\(4.853\\,\\mathrm{J\\,K^{-1}}\\)。","因为过程绝热，所以气体熵变为零。","初态和末态温度相同。","气体和外界之间没有热传递，也没有体积功。"],"answer":[1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-insulated-free-expansion","explanation":"自由膨胀无外压，且绝热，因此 \\(\\Delta U=0\\)。理想气体的内能只由温度决定，初末温度相同。熵是状态函数，可用连接两平衡态的可逆等温膨胀计算 \\(\\Delta S=nR\\ln(V_f/V_i)>0\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-finite-bodies-entropy-2","type":"single","points":3,"stem":"绝热容器内有两个只交换热量的物体。第一物体热容 215 J/K、初温 303 K，第二物体热容 309 J/K、初温 377 K。热容均为常数。到达共同温度后，两物体总熵增加约多少？","options":["\\(25.95\\,\\mathrm{J\\,K^{-1}}\\)","\\(2.982\\,\\mathrm{J\\,K^{-1}}\\)","\\(-2.982\\,\\mathrm{J\\,K^{-1}}\\)","\\(28.93\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-finite-bodies-entropy","explanation":"先用能量守恒求共同温度 \\(T_f=(C_1T_1+C_2T_2)/(C_1+C_2)\\)。各物体的熵变分别是 \\(C_i\\ln(T_f/T_i)\\)，将一正一负的两项相加。 得 \\(2.982\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-ideal-mixture-entropy-2","type":"single","points":3,"stem":"绝热刚性容器中有 1.4 mol A 和 2.8 mol B，均为不同的理想气体，初态分置两隔间，温度和压强都相同。撤去隔板后两气体完全混合。混合熵约是多少？","options":["\\(9.439\\,\\mathrm{J\\,K^{-1}}\\)","\\(12.79\\,\\mathrm{J\\,K^{-1}}\\)","\\(22.23\\,\\mathrm{J\\,K^{-1}}\\)","\\(34.92\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-ideal-mixture-entropy","explanation":"相同初始温压下，初体积占比等于摩尔分数 \\(x_i\\)。混合后每一组分可及体积为总容积，等效可逆等温膨胀的熵增为 \\(-n_iR\\ln x_i\\)。相加得到混合熵。 得 \\(22.23\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-entropy-temperature-volume-2","type":"single","points":3,"stem":"1.35 mol 刚性双原子理想气体从 290 K 变为 354 K，体积同时扩大至原来的 1.34 倍。忽略振动，求气体的熵变。","options":["\\(2.311\\,\\mathrm{J\\,K^{-1}}\\)","\\(3.285\\,\\mathrm{J\\,K^{-1}}\\)","\\(8.88\\,\\mathrm{J\\,K^{-1}}\\)","\\(5.596\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-entropy-temperature-volume","explanation":"可选先等容升温再等温膨胀作为可逆辅助路径。分别积出 \\(nC_V\\ln(T_2/T_1)\\) 和 \\(nR\\ln(V_2/V_1)\\)，相加。 得 \\(8.88\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-steady-conduction-2","type":"single","points":2,"stem":"面积为 0.17 m²、厚度 16 mm 的均匀平板，导热系数为 0.47 W/(m·K)，两表面恒温 345 K 和 296 K。忽略侧面漏热，稳定导热速率约是多少？","options":["\\(1439\\,\\mathrm W\\)","\\(489.4\\,\\mathrm W\\)","\\(0.2447\\,\\mathrm W\\)","\\(244.7\\,\\mathrm W\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-steady-conduction","explanation":"稳定的一维傅里叶导热通量为 \\(j_Q=k(T_h-T_c)/L\\)。总导热速率还要乘面积，厚度从毫米换成米。 得 \\(244.7\\,\\mathrm W\\)。"},
  {"id":"t-series-conduction-2","type":"single","points":3,"stem":"面积 0.22 m² 的双层墙，第一层厚 28 mm、导热系数 0.23 W/(m·K)，第二层厚 44 mm、导热系数 0.52 W/(m·K)。外表面温差为 35 K，层间接触热阻忽略。稳定导热功率约是多少？","options":["\\(37.31\\,\\mathrm W\\)","\\(91\\,\\mathrm W\\)","\\(63.25\\,\\mathrm W\\)","\\(80.21\\,\\mathrm W\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-series-conduction","explanation":"两层串联时同一功率穿过每层，热阻为 \\(L/(kA)\\)。把热阻相加，外表面温差除以总热阻。 得 \\(37.31\\,\\mathrm W\\)。"},
  {"id":"t-couette-shear-2","type":"single","points":2,"stem":"两块平行板间夹有牛顿流体，板间距 4.4 mm，流体动力黏度 0.075 Pa·s。下板固定，上板以 0.58 m/s 匀速移动。忽略边缘效应，若上板接触面积 0.135 m²，流体对上板黏滞力的大小约是多少？","options":["\\(0.001335\\,\\mathrm N\\)","\\(9.886\\,\\mathrm N\\)","\\(1.335\\,\\mathrm N\\)","\\(2.669\\,\\mathrm N\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-couette-shear","explanation":"平板间的速度梯度为 \\(u/h\\)。牛顿黏性定律给出剪应力 \\(\\eta u/h\\)，再乘受力面积。 得 \\(1.335\\,\\mathrm N\\)。"},
  {"id":"t-fick-steady-flow-2","type":"single","points":2,"stem":"两侧浓度分别为 1.97、0.59 mol/m³，扩散距离 2.6 cm，面积 0.04 m²。浓度沿程线性，扩散系数为 \\(1.88\\times10^{-5}\\,\\mathrm{m^2\\,s^{-1}}\\)。求通过整个截面的物质的量输运速率大小。","options":["\\(0.003991\\,\\mathrm{mol\\,s^{-1}}\\)","\\(7.404\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(3.991\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.0009978\\,\\mathrm{mol\\,s^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-fick-steady-flow","explanation":"菲克定律给出的通量大小为 \\(D|\\mathrm dc/\\mathrm dx|\\)，浓度线性时是 \\(D|c_1-c_2|/L\\)。乘以截面积得到总速率。 得 \\(3.991\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)。"},
  {"id":"t-linear-expansion-2","type":"single","points":1,"stem":"自由伸缩的细杆初长 1.4 m，线膨胀系数近似恒为 \\(1.21\\times10^{-5}\\,\\mathrm{K^{-1}}\\)。升温 46 K 后，长度增加量约是多少？","options":["\\(0.002338\\,\\mathrm m\\)","\\(0.0005566\\,\\mathrm m\\)","\\(7.792\\times10^{-7}\\,\\mathrm m\\)","\\(0.0007792\\,\\mathrm m\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-linear-expansion","explanation":"一阶近似下 \\(\\Delta L=\\alpha L_0\\Delta T\\)。长度和温差直接以题设单位代入。 得 \\(0.0007792\\,\\mathrm m\\)。"},
  {"id":"t-curved-interfaces-2","type":"multiple","points":2,"stem":"一个液滴与一个薄壁肥皂泡的半径均为 0.64 mm，界面张力均为 0.063 N/m。忽略重力导致的变形。下列说法正确的是哪些？","options":["液滴内外压差约 \\(196.9\\,\\mathrm{Pa}\\)。","液滴内部压强小于外界。","相同界面张力下，把肥皂泡的半径加倍，其内外压差减半。","肥皂泡内外压差约 \\(393.7\\,\\mathrm{Pa}\\)。","肥皂膜只有一个气液界面。"],"answer":[0,2,3],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-curved-interfaces","explanation":"球形单界面的拉普拉斯压差是 \\(2\\sigma/r\\)。液滴仅一个界面，薄壁肥皂泡近似有两个等半径的界面，两个压差相加。压差均与半径成反比。"},
  {"id":"t-capillary-rise-2","type":"single","points":2,"stem":"毛细管内半径 0.34 mm，液体完全润湿管壁，液体密度 920 kg/m³、表面张力 0.049 N/m。忽略管外液面变化，管内液面约上升多高？","options":["\\(31.94\\,\\mathrm m\\)","\\(0.01597\\,\\mathrm m\\)","\\(0.03194\\,\\mathrm m\\)","\\(0.06387\\,\\mathrm m\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-capillary-rise","explanation":"完全润湿时接触角为零。竖直表面张力为 \\(2\\pi r\\sigma\\)，平衡液柱重力 \\(\\rho g\\pi r^2 h\\)。联立求高度。 得 \\(0.03194\\,\\mathrm m\\)。","reference":"重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。"},
  {"id":"t-heating-partial-vaporization-2","type":"single","points":3,"stem":"常压下质量 0.165 kg 的水从 20 ℃ 加热到 100 ℃，随后其质量的 18% 在 100 ℃ 汽化。取水的比热容为 4180 J/(kg·K)，汽化潜热为 \\(2.25\\times10^{6}\\,\\mathrm{J\\,kg^{-1}}\\)。忽略热损失，总吸热约是多少？","options":["\\(4.264\\times10^{5}\\,\\mathrm{J}\\)","\\(1.22\\times10^{5}\\,\\mathrm{J}\\)","\\(5.518\\times10^{4}\\,\\mathrm{J}\\)","\\(6.683\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 8 章","family":"t-heating-partial-vaporization","explanation":"升温吸热 \\(Q_1=mc\\Delta T\\)。汽化阶段只用实际汽化的质量乘潜热，\\(Q_2=mfL_v\\)。总吸热为两项之和。 得 \\(1.22\\times10^{5}\\,\\mathrm{J}\\)。"},
  {"id":"t-reversible-melting-entropy-2","type":"single","points":2,"stem":"某纯物质在规定压强下的熔点为 245 K，熔化潜热为 \\(2.9\\times10^{5}\\,\\mathrm{J\\,kg^{-1}}\\)。将处于熔点的 0.19 kg 固体缓慢熔化成同温液体。物质的熵变约是多少？","options":["\\(-224.9\\,\\mathrm{J\\,K^{-1}}\\)","\\(224.9\\,\\mathrm{J\\,K^{-1}}\\)","\\(1184\\,\\mathrm{J\\,K^{-1}}\\)","\\(5.51\\times10^{4}\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-reversible-melting-entropy","explanation":"熔点处可逆等温熔化需吸收 \\(Q=mL_f\\)。等温可逆相变的熵变为 \\(Q/T_m\\)，吸热时为正。 得 \\(224.9\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-clapeyron-slope-2","type":"single","points":3,"stem":"某纯物质处在 327 K 的液气平衡线上。该点的摩尔汽化潜热为 29.8 kJ/mol，气相和液相的摩尔体积差为 0.018 m³/mol。求该点饱和压强对温度的斜率。","options":["\\(91.13\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(5063\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(-5063\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(15.48\\,\\mathrm{Pa\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-clapeyron-slope","explanation":"克拉珀龙方程 \\( \\mathrm dp_\\mathrm{sat}/\\mathrm dT=L_m/[T(V_{m,g}-V_{m,l})] \\)。把摩尔潜热从 kJ/mol 换成 J/mol 后代入，气相摩尔体积更大，因此斜率为正。 得 \\(5063\\,\\mathrm{Pa\\,K^{-1}}\\)。"},
  {"id":"t-without-replacement-3","type":"single","points":1,"stem":"袋中有 7 个红球、6 个蓝球。一次不放回地随机抽取两个球，两个都是红球的概率约是多少？","options":["\\(0.1346\\)","\\(0.2899\\)","\\(0.2692\\)","\\(0.5385\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-without-replacement","explanation":"在不放回抽样中，第二次取红的条件概率为 \\((r-1)/(N-1)\\)。与首次概率 \\(r/N\\) 相乘。 得 \\(0.2692\\)。"},
  {"id":"t-random-walk-origin-3","type":"single","points":2,"stem":"微粒从原点出发，在一条直线上独立地走 8 步，每步等概率向左或向右移动一个单位。最后回到原点的概率约是多少？","options":["\\(0.5\\)","\\(0.1111\\)","\\(0.003906\\)","\\(0.2734\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-random-walk-origin","explanation":"回到原点要求左右各走一半步数。共有 \\(\\binom{N}{N/2}\\) 条这样的序列，总序列数为 \\(2^N\\)。 得 \\(0.2734\\)。"},
  {"id":"t-power-density-3","type":"single","points":3,"stem":"连续随机变量的概率密度在 0 到 4 之间为 \\(f(x)=C x^{3}\\)，区间外为零。该变量落在 0 到 1 之间的概率约是多少？","options":["\\(0.0009766\\)","\\(0.25\\)","\\(0.9961\\)","\\(0.003906\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-power-density","explanation":"归一化要求分母为 \\(\\int_0^{L}x^a\\,\\mathrm dx\\)。区间概率是 \\(\\int_0^b x^a\\,\\mathrm dx/\\int_0^L x^a\\,\\mathrm dx=(b/L)^{a+1}\\)。 得 \\(0.003906\\)。","reference":"当 \\(a>-1\\) 时，\\(\\int_0^L x^a\\,\\mathrm dx=L^{a+1}/(a+1)\\)。"},
  {"id":"t-rigid-vessel-temperature-3","type":"single","points":1,"stem":"密闭刚性容器里装有一定量理想气体。气体从 270 K 缓慢升温到 358 K，初态绝对压强为 104 kPa。末态压强约是多少？","options":["\\(78.44\\,\\mathrm{kPa}\\)","\\(104\\,\\mathrm{kPa}\\)","\\(137.9\\,\\mathrm{kPa}\\)","\\(423.1\\,\\mathrm{kPa}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-rigid-vessel-temperature","explanation":"容积和物质的量保持恒定，状态方程给出 \\(p_2/p_1=T_2/T_1\\)。 得 \\(137.9\\,\\mathrm{kPa}\\)。"},
  {"id":"t-dalton-partial-pressure-3","type":"single","points":1,"stem":"两种互不反应的理想气体形成均匀混合气。A 组分有 4 mol，B 组分有 11 mol，总压强为 162 kPa。A 的分压约是多少？","options":["\\(58.91\\,\\mathrm{kPa}\\)","\\(43.2\\,\\mathrm{kPa}\\)","\\(10.8\\,\\mathrm{kPa}\\)","\\(118.8\\,\\mathrm{kPa}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 2 章","family":"t-dalton-partial-pressure","explanation":"各组分在同一温度和体积下服从状态方程，分压占总压的比例等于摩尔分数。 得 \\(43.2\\,\\mathrm{kPa}\\)。"},
  {"id":"t-joined-vessels-3","type":"single","points":2,"stem":"两个容积分别为 5 L、12 L 的刚性容器分别装有理想气体，压强为 220 kPa、73 kPa。两容器均已与同一恒温浴达到热平衡，打开连通阀直至新平衡。末态总压强约是多少？","options":["\\(116.2\\,\\mathrm{kPa}\\)","\\(176.8\\,\\mathrm{kPa}\\)","\\(146.5\\,\\mathrm{kPa}\\)","\\(293\\,\\mathrm{kPa}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-joined-vessels","explanation":"由初态两侧总物质的量守恒，且温度相同，有 \\(p_f(V_1+V_2)=p_1V_1+p_2V_2\\)。 得 \\(116.2\\,\\mathrm{kPa}\\)。"},
  {"id":"t-gas-mass-pressure-3","type":"single","points":2,"stem":"3 kg 氮气装在体积为 1 立方米的容器内，温度为 304 K。把氮气视为理想气体，取其摩尔质量 28 g/mol，求绝对压强。","options":["\\(2.708\\times10^{8}\\,\\mathrm{Pa}\\)","\\(2.708\\times10^{5}\\,\\mathrm{Pa}\\)","\\(7582\\,\\mathrm{Pa}\\)","\\(5.416\\times10^{5}\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-gas-mass-pressure","explanation":"先以 \\(n=m/M\\) 将质量换成摩尔数，再由 \\(p=nRT/V\\) 代入。注意 \\(28\\,\\mathrm{g\\,mol^{-1}}=0.028\\,\\mathrm{kg\\,mol^{-1}}\\)。 得 \\(2.708\\times10^{5}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-van-der-waals-pressure-3","type":"single","points":3,"stem":"某气体每摩尔体积为 1.04 L/mol、温度为 287 K。范德瓦尔斯参数分别为 \\(0.156\\,\\mathrm{Pa\\,m^6\\,mol^{-2}}\\) 和 \\(0.00037\\,\\mathrm{m^3\\,mol^{-1}}\\)。求压强。","options":["\\(1.548\\times10^{6}\\,\\mathrm{Pa}\\)","\\(2.294\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.706\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.417\\times10^{6}\\,\\mathrm{Pa}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-van-der-waals-pressure","explanation":"采用摩尔体积形式，\\(p=RT/(V_m-b)-a/V_m^2\\)。体积应先换成 \\(\\mathrm{m^3\\,mol^{-1}}\\)。 得 \\(3.417\\times10^{6}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-mean-free-path-3","type":"single","points":2,"stem":"温度为 284 K、压强为 140 Pa 的稀薄气体由有效直径 0.32 nm 的相同硬球分子组成。估算分子的平均自由程。","options":["\\(0.0001934\\,\\mathrm m\\)","\\(8.706\\times10^{-5}\\,\\mathrm m\\)","\\(3.078\\times10^{-5}\\,\\mathrm m\\)","\\(6.156\\times10^{-5}\\,\\mathrm m\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-mean-free-path","explanation":"由 \\(n=p/(k_\\mathrm BT)\\) 求数密度。相同硬球的平均自由程是 \\(\\lambda=1/(\\sqrt2\\,\\pi d^2 n)\\)，其中 \\(\\pi d^2\\) 为碰撞截面。 得 \\(6.156\\times10^{-5}\\,\\mathrm m\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-rms-temperature-3","type":"single","points":2,"stem":"一种理想气体的摩尔质量为 36 g/mol，分子的方均根速率为 480 m/s。求该气体的热力学温度。","options":["\\(166.3\\,\\mathrm{K}\\)","\\(332.5\\,\\mathrm{K}\\)","\\(498.8\\,\\mathrm{K}\\)","\\(997.6\\,\\mathrm{K}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-rms-temperature","explanation":"平均平动动能为 \\(3k_\\mathrm BT/2\\)，所以 \\(v_{\\mathrm{rms}}^2=3RT/M\\)。摩尔质量应以 kg/mol 代入。 得 \\(332.5\\,\\mathrm{K}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-kinetic-pressure-3","type":"single","points":2,"stem":"理想气体的压强为 102 kPa，质量密度为 0.82 kg/m³。估计分子的方均根速率。","options":["\\(863.9\\,\\mathrm{m\\,s^{-1}}\\)","\\(352.7\\,\\mathrm{m\\,s^{-1}}\\)","\\(432\\,\\mathrm{m\\,s^{-1}}\\)","\\(610.9\\,\\mathrm{m\\,s^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-kinetic-pressure","explanation":"分子运动论给出 \\(p=\\rho v_{\\mathrm{rms}}^2/3\\)，压强换成 Pa 后求平方根。 得 \\(610.9\\,\\mathrm{m\\,s^{-1}}\\)。"},
  {"id":"t-collision-frequency-3","type":"single","points":1,"stem":"某稀薄气体分子的平均速率为 420 m/s，平均自由程为 106 nm。估计单个分子的平均碰撞频率。","options":["\\(3.962\\,\\mathrm{s^{-1}}\\)","\\(3.962\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(7.925\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(9.906\\times10^{8}\\,\\mathrm{s^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-collision-frequency","explanation":"在平均意义下，单位时间经历的自由程数约为 \\(\\bar v/\\lambda\\)。将 nm 换成 m 再相除。 得 \\(3.962\\times10^{9}\\,\\mathrm{s^{-1}}\\)。"},
  {"id":"t-maxwell-temperature-ratio-3","type":"single","points":1,"stem":"同一种气体分别处于 290 K 和 380 K 的平衡态。后者与前者的最概然速率之比约是多少？","options":["\\(0.8736\\)","\\(1.145\\)","\\(0.3103\\)","\\(1.31\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-temperature-ratio","explanation":"同种气体的分子质量相同，最概然速率 \\(v_p=\\sqrt{2RT/M}\\) 与绝对温度的平方根成正比。 得 \\(1.145\\)。"},
  {"id":"t-barometric-ratio-3","type":"single","points":3,"stem":"把大气视为均匀摩尔质量为 29 g/mol 的理想气体，设温度恒为 278 K、重力加速度不随高度改变。海拔比基准面高 2400 m 处的气压是基准面气压的多少倍？","options":["\\(0.2558\\)","\\(1.344\\)","\\(0.7442\\)","\\(0.5539\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-barometric-ratio","explanation":"将静力平衡 \\(\\mathrm dp/\\mathrm dz=-\\rho g\\) 与 \\(\\rho=Mp/(RT)\\) 联立并积分，得到 \\(p(z)/p(0)=\\exp[-Mgz/(RT)]\\)。 得 \\(0.7442\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-two-level-population-3","type":"single","points":3,"stem":"一批可分辨的弱相互作用粒子在 310 K 达到热平衡。每个粒子仅能处在两个非简并能级，上能级比下能级高 \\(7.019\\times10^{-21}\\,\\mathrm{J}\\)。约有多大比例的粒子在上能级？","options":["\\(0.194\\)","\\(0.03763\\)","\\(0.1625\\)","\\(0.8375\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-two-level-population","explanation":"以上能级和下能级的玻尔兹曼权重分别为 \\(\\exp[-\\Delta E/(k_\\mathrm BT)]\\) 和 1，将上能级权重除以两权重之和。 得 \\(0.1625\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-mixture-equipartition-3","type":"single","points":2,"stem":"3 mol 单原子理想气体与 4 mol 刚性双原子理想气体混合，在 292 K 达到热平衡。忽略双原子分子的振动，混合气体的总内能约是多少？","options":["\\(3.52\\times10^{4}\\,\\mathrm{J}\\)","\\(2.549\\times10^{4}\\,\\mathrm{J}\\)","\\(4.248\\times10^{4}\\,\\mathrm{J}\\)","\\(7.04\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-mixture-equipartition","explanation":"按能量均分，单原子有 3 个自由度，刚性双原子有 5 个自由度。分别计算 \\(f nRT/2\\) 后相加。 得 \\(3.52\\times10^{4}\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-maxwell-concepts-3","type":"multiple","points":2,"stem":"温度为 327 K 的氧气和温度为 300 K 的氮气都处于无宏观流动的平衡态。取氧气、氮气的摩尔质量分别为 32 和 28 g/mol。关于它们的麦克斯韦速率分布，正确的是哪些？","options":["氧气与氮气的最概然速率之比约为 \\(0.9766\\)。","同一种气体升温，最概然速率增大。","在同一平衡态，任一种气体的最概然速率大于其方均根速率。","氧气的最概然速率低于氮气。","任一种气体的分子平均速度矢量为零。"],"answer":[0,1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-concepts","explanation":"最概然速率为 \\(v_p=\\sqrt{2RT/M}\\)。两种气体的速率之比由各自的 \\(T/M\\) 决定；升温则最概然速率增大。最概然速率小于方均根速率。平衡态无宏观流动，各方向的速度矢量平均为零。"},
  {"id":"t-isobaric-work-3","type":"single","points":1,"stem":"1.8 mol 理想气体在压强不变的情况下从 296 K 升至 339 K。气体对外做的体积功约是多少？","options":["\\(965.3\\,\\mathrm{J}\\)","\\(643.5\\,\\mathrm{J}\\)","\\(1609\\,\\mathrm{J}\\)","\\(321.8\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isobaric-work","explanation":"等压过程 \\(W=p(V_2-V_1)\\)。由状态方程，\\(p(V_2-V_1)=nR(T_2-T_1)\\)。 得 \\(643.5\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isochoric-heating-3","type":"single","points":1,"stem":"1.1 mol 单原子理想气体在刚性容器中从 296 K 加热到 331 K，仅交换热量。气体吸热约是多少？","options":["\\(320.1\\,\\mathrm{J}\\)","\\(480.1\\,\\mathrm{J}\\)","\\(960.3\\,\\mathrm{J}\\)","\\(800.2\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isochoric-heating","explanation":"定容过程没有体积功，吸热等于内能增加。单原子理想气体的定容摩尔热容为 \\(3R/2\\)。 得 \\(480.1\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isothermal-work-3","type":"single","points":2,"stem":"1 mol 理想气体在 294 K 从体积 4 L 可逆等温膨胀到 8.24 L。气体对外做功约是多少？","options":["\\(883.3\\,\\mathrm{J}\\)","\\(1258\\,\\mathrm{J}\\)","\\(2591\\,\\mathrm{J}\\)","\\(1767\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isothermal-work","explanation":"准静态做功为 \\(\\int p\\,\\mathrm dV\\)。等温时 \\(p=nRT/V\\)，积分得 \\(W=nRT\\ln(V_2/V_1)\\)。 得 \\(1767\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-adiabatic-expansion-temperature-3","type":"single","points":2,"stem":"1.3 mol 单原子理想气体初温 320 K，可逆绝热膨胀至原体积的 2.1 倍。末温约是多少？","options":["\\(152.4\\,\\mathrm{K}\\)","\\(220.8\\,\\mathrm{K}\\)","\\(524.8\\,\\mathrm{K}\\)","\\(195.1\\,\\mathrm{K}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-adiabatic-expansion-temperature","explanation":"可逆绝热过程 \\(TV^{\\gamma-1}\\) 不变，单原子气体 \\(\\gamma=5/3\\)。据此由体积比求温度比。 得 \\(195.1\\,\\mathrm{K}\\)。"},
  {"id":"t-adiabatic-compression-work-3","type":"single","points":3,"stem":"1.5 mol 刚性双原子理想气体初温为 300 K，经可逆绝热压缩，体积缩小为原来的 1/2.08。外界对气体做的功约是多少？","options":["\\(4457\\,\\mathrm{J}\\)","\\(2740\\,\\mathrm{J}\\)","\\(1273\\,\\mathrm{J}\\)","\\(3184\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-adiabatic-compression-work","explanation":"忽略振动时 \\(\\gamma=7/5\\)，由 \\(TV^{\\gamma-1}=\\text{常量}\\) 求末温。因 \\(Q=0\\)，外界做功等于 \\(\\Delta U=\\tfrac52nR(T_2-T_1)\\)。 得 \\(3184\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-linear-path-work-3","type":"single","points":2,"stem":"一份气体在准静态膨胀中体积增加 2.8 L，压强从 85 kPa 随体积线性升到 194 kPa。气体对外做功是多少？","options":["\\(543.2\\,\\mathrm{J}\\)","\\(238\\,\\mathrm{J}\\)","\\(305.2\\,\\mathrm{J}\\)","\\(390.6\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-linear-path-work","explanation":"沿直线过程，\\(p\\!-\\!V\\) 图下方的梯形面积等于平均压强乘体积变化。\\(1\\,\\mathrm{kPa\\,L}=1\\,\\mathrm J\\)。 得 \\(390.6\\,\\mathrm{J}\\)。"},
  {"id":"t-rectangular-cycle-3","type":"multiple","points":2,"stem":"理想气体沿顺时针矩形循环运行。两条等压边压强分别为 95 kPa 和 210 kPa，两条等容边体积分别为 5 L 和 12 L。关于整个循环，下列说法正确的是哪些？","options":["一周后气体总吸热一定为零。","沿两个等容段，体积功均为零。","气体净对外做功为 \\(805\\,\\mathrm{J}\\)。","一周后气体内能变化为零。","高压等压边与低压等压边的体积功大小相等。"],"answer":[1,2,3],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-rectangular-cycle","explanation":"顺时针循环的净功为矩形面积 \\((p_h-p_l)(V_h-V_l)\\)。回到起态时 \\(\\Delta U=0\\)，净吸热等于净功，非零。等容段 \\(\\mathrm dV=0\\)，两条等压边体积改变量大小相同但压强不同。"},
  {"id":"t-isobaric-monatomic-budget-3","type":"multiple","points":2,"stem":"2 mol 单原子理想气体在恒压下从 312 K 加热至 350 K，只做体积功。下列数量关系正确的是哪些？","options":["气体吸热等于内能的增加量。","气体的焓不变。","气体对外做功 \\(631.9\\,\\mathrm{J}\\)。","气体吸收热量 \\(1580\\,\\mathrm{J}\\)。","气体的内能增加 \\(947.8\\,\\mathrm{J}\\)。"],"answer":[2,3,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isobaric-monatomic-budget","explanation":"定压时 \\(W=nR\\Delta T\\)，内能变化为 \\(nC_V\\Delta T\\)，焓变化 \\(nC_p\\Delta T\\) 等于吸热。单原子气体 \\(C_V=3R/2,\\ C_p=5R/2\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-two-stage-heating-expansion-3","type":"single","points":3,"stem":"1.8 mol 单原子理想气体先定容地从 295 K 加热到 330 K，接着在 330 K 可逆等温膨胀，体积变为原来的 1.8 倍。两阶段总吸热约是多少？","options":["\\(4212\\,\\mathrm{J}\\)","\\(2903\\,\\mathrm{J}\\)","\\(3688\\,\\mathrm{J}\\)","\\(785.7\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-two-stage-heating-expansion","explanation":"第一段等容，\\(Q_1=\\Delta U_1=\\tfrac32nR(T_2-T_1)\\)。第二段等温，\\(Q_2=W_2=nRT_2\\ln(V_f/V_i)\\)。总吸热为两段之和。 得 \\(3688\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-polytropic-work-3","type":"single","points":3,"stem":"气体从 3.5 L 准静态膨胀至 7.2 L，初压 106 kPa。过程满足 \\(pV^{1.31}\\) 为常量。气体对外做功约是多少？","options":["\\(152.5\\,\\mathrm{J}\\)","\\(239.8\\,\\mathrm{J}\\)","\\(392.2\\,\\mathrm{J}\\)","\\(267.6\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-polytropic-work","explanation":"设 \\(pV^s=C\\)，把 \\(p=CV^{-s}\\) 代入体积功积分，可得 \\(W=(p_2V_2-p_1V_1)/(1-s)\\)。用状态间的多方关系求 \\(p_2\\)。 得 \\(239.8\\,\\mathrm{J}\\)。","reference":"当 \\(a\\ne-1\\) 时，\\(\\int x^a\\,\\mathrm dx=x^{a+1}/(a+1)+C\\)。"},
  {"id":"t-compression-energy-balance-3","type":"multiple","points":2,"stem":"气体在带活塞的容器中被缓慢压缩。过程中气体吸热 1250 J，外界对气体做功 336 J，忽略其他能量交换。下列说法正确的是哪些？","options":["气体的内能变化等于 \\(914\\,\\mathrm{J}\\)。","热量等于外界对气体做的功。","按气体对外做功为正的约定，气体的体积功为 \\(-336\\,\\mathrm{J}\\)。","气体一定放热。","气体内能增加 \\(1586\\,\\mathrm{J}\\)。"],"answer":[2,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-compression-energy-balance","explanation":"采用 \\(\\Delta U=Q-W_{\\mathrm{by}}\\)。吸热 \\(Q>0\\)，压缩时气体对外做功 \\(W_{\\mathrm{by}}<0\\)。内能增加量等于吸热量与外界做功之和。"},
  {"id":"t-carnot-absorbed-heat-3","type":"single","points":3,"stem":"一台可逆热机在 540 K 的高温热源与 279 K 的低温热源之间工作，每循环对外净做功 940 J。每循环从高温热源吸热约是多少？","options":["\\(1819\\,\\mathrm{J}\\)","\\(454.3\\,\\mathrm{J}\\)","\\(940\\,\\mathrm{J}\\)","\\(1945\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-absorbed-heat","explanation":"卡诺效率 \\(\\eta=1-T_\\mathrm c/T_\\mathrm h\\)，同时 \\(\\eta=W/Q_\\mathrm h\\)。把两式联立求 \\(Q_\\mathrm h\\)。 得 \\(1945\\,\\mathrm{J}\\)。"},
  {"id":"t-carnot-heat-balance-3","type":"multiple","points":2,"stem":"卡诺热机在 574 K、308 K 的两个热源之间运行，每周吸收高温热量 1500 J。下列说法正确的是哪些？","options":["每周向低温热源放热约 \\(804.9\\,\\mathrm{J}\\)。","两热源的总熵在每周内严格增加。","工质每周的熵变为零。","高温热源每周熵增约 \\(2.613\\,\\mathrm{J\\,K^{-1}}\\)。","每周净输出功约 \\(695.1\\,\\mathrm{J}\\)。"],"answer":[0,2,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-heat-balance","explanation":"卡诺循环可逆，有 \\(Q_\\mathrm h/T_\\mathrm h=Q_\\mathrm c/T_\\mathrm c\\)。净功为两热量之差，工质状态复原。低温热源的正熵变与高温热源的负熵变抵消。"},
  {"id":"t-carnot-refrigerator-3","type":"multiple","points":2,"stem":"可逆制冷机的冷端为 257 K、热端为 327 K，每周期从冷端移走 700 J。下列说法正确的是哪些？","options":["制冷系数约为 \\(3.671\\)。","外界每周期至少输入功 \\(190.7\\,\\mathrm{J}\\)。","热端每周期得到的热量小于冷端失去的热量。","热端每周期得到热量 \\(890.7\\,\\mathrm{J}\\)。","在保持热端温度不变时，降低冷端温度会提高制冷系数。"],"answer":[0,1,3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-carnot-refrigerator","explanation":"制冷机的卡诺制冷系数为 \\(T_\\mathrm c/(T_\\mathrm h-T_\\mathrm c)\\)。由 \\(W=Q_\\mathrm c/\\varepsilon\\) 求输入功，再用 \\(Q_\\mathrm h=Q_\\mathrm c+W\\)。冷端温度降低时制冷更困难。"},
  {"id":"t-reservoir-transfer-entropy-3","type":"single","points":2,"stem":"1560 J 热量自行从恒温 418 K 的热源传给恒温 289 K 的热源，无其他作用。两个热源的总熵增约是多少？","options":["\\(-1.666\\,\\mathrm{J\\,K^{-1}}\\)","\\(5.398\\,\\mathrm{J\\,K^{-1}}\\)","\\(9.13\\,\\mathrm{J\\,K^{-1}}\\)","\\(1.666\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-reservoir-transfer-entropy","explanation":"冷热源各自在恒温下交换热量。热源失热熵变 \\(-Q/T_\\mathrm h\\)，冷源得热熵变 \\(Q/T_\\mathrm c\\)，二者相加。 得 \\(1.666\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-insulated-free-expansion-3","type":"multiple","points":2,"stem":"1.4 mol 理想气体在绝热刚性容器中，撤去隔板后向真空自由膨胀，最终占据原来的 1.95 倍体积。下列说法正确的是哪些？","options":["初态和末态温度相同。","气体和外界之间没有热传递，也没有体积功。","这个过程可以仅靠气体自身逆向恢复而不引起其他变化。","因为过程绝热，所以气体熵变为零。","气体熵增约 \\(7.773\\,\\mathrm{J\\,K^{-1}}\\)。"],"answer":[0,1,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-insulated-free-expansion","explanation":"自由膨胀无外压，且绝热，因此 \\(\\Delta U=0\\)。理想气体的内能只由温度决定，初末温度相同。熵是状态函数，可用连接两平衡态的可逆等温膨胀计算 \\(\\Delta S=nR\\ln(V_f/V_i)>0\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-finite-bodies-entropy-3","type":"single","points":3,"stem":"绝热容器内有两个只交换热量的物体。第一物体热容 250 J/K、初温 306 K，第二物体热容 348 J/K、初温 389 K。热容均为常数。到达共同温度后，两物体总熵增加约多少？","options":["\\(-4.126\\,\\mathrm{J\\,K^{-1}}\\)","\\(4.126\\,\\mathrm{J\\,K^{-1}}\\)","\\(32.51\\,\\mathrm{J\\,K^{-1}}\\)","\\(36.64\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-finite-bodies-entropy","explanation":"先用能量守恒求共同温度 \\(T_f=(C_1T_1+C_2T_2)/(C_1+C_2)\\)。各物体的熵变分别是 \\(C_i\\ln(T_f/T_i)\\)，将一正一负的两项相加。 得 \\(4.126\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-ideal-mixture-entropy-3","type":"single","points":3,"stem":"绝热刚性容器中有 1.7 mol A 和 3.2 mol B，均为不同的理想气体，初态分置两隔间，温度和压强都相同。撤去隔板后两气体完全混合。混合熵约是多少？","options":["\\(26.3\\,\\mathrm{J\\,K^{-1}}\\)","\\(11.34\\,\\mathrm{J\\,K^{-1}}\\)","\\(14.96\\,\\mathrm{J\\,K^{-1}}\\)","\\(40.74\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-ideal-mixture-entropy","explanation":"相同初始温压下，初体积占比等于摩尔分数 \\(x_i\\)。混合后每一组分可及体积为总容积，等效可逆等温膨胀的熵增为 \\(-n_iR\\ln x_i\\)。相加得到混合熵。 得 \\(26.3\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-entropy-temperature-volume-3","type":"single","points":3,"stem":"1.55 mol 刚性双原子理想气体从 295 K 变为 366 K，体积同时扩大至原来的 1.43 倍。忽略振动，求气体的熵变。","options":["\\(6.948\\,\\mathrm{J\\,K^{-1}}\\)","\\(2.339\\,\\mathrm{J\\,K^{-1}}\\)","\\(11.56\\,\\mathrm{J\\,K^{-1}}\\)","\\(4.609\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-entropy-temperature-volume","explanation":"可选先等容升温再等温膨胀作为可逆辅助路径。分别积出 \\(nC_V\\ln(T_2/T_1)\\) 和 \\(nR\\ln(V_2/V_1)\\)，相加。 得 \\(11.56\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-steady-conduction-3","type":"single","points":2,"stem":"面积为 0.2 m²、厚度 18 mm 的均匀平板，导热系数为 0.52 W/(m·K)，两表面恒温 350 K 和 299 K。忽略侧面漏热，稳定导热速率约是多少？","options":["\\(294.7\\,\\mathrm W\\)","\\(1473\\,\\mathrm W\\)","\\(0.2947\\,\\mathrm W\\)","\\(589.3\\,\\mathrm W\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-steady-conduction","explanation":"稳定的一维傅里叶导热通量为 \\(j_Q=k(T_h-T_c)/L\\)。总导热速率还要乘面积，厚度从毫米换成米。 得 \\(294.7\\,\\mathrm W\\)。"},
  {"id":"t-series-conduction-3","type":"single","points":3,"stem":"面积 0.24 m² 的双层墙，第一层厚 31 mm、导热系数 0.25 W/(m·K)，第二层厚 46 mm、导热系数 0.56 W/(m·K)。外表面温差为 39 K，层间接触热阻忽略。稳定导热功率约是多少？","options":["\\(113.9\\,\\mathrm W\\)","\\(98.46\\,\\mathrm W\\)","\\(75.48\\,\\mathrm W\\)","\\(45.41\\,\\mathrm W\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-series-conduction","explanation":"两层串联时同一功率穿过每层，热阻为 \\(L/(kA)\\)。把热阻相加，外表面温差除以总热阻。 得 \\(45.41\\,\\mathrm W\\)。"},
  {"id":"t-couette-shear-3","type":"single","points":2,"stem":"两块平行板间夹有牛顿流体，板间距 4.8 mm，流体动力黏度 0.09 Pa·s。下板固定，上板以 0.71 m/s 匀速移动。忽略边缘效应，若上板接触面积 0.16 m²，流体对上板黏滞力的大小约是多少？","options":["\\(0.00213\\,\\mathrm N\\)","\\(13.31\\,\\mathrm N\\)","\\(2.13\\,\\mathrm N\\)","\\(4.26\\,\\mathrm N\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-couette-shear","explanation":"平板间的速度梯度为 \\(u/h\\)。牛顿黏性定律给出剪应力 \\(\\eta u/h\\)，再乘受力面积。 得 \\(2.13\\,\\mathrm N\\)。"},
  {"id":"t-fick-steady-flow-3","type":"single","points":2,"stem":"两侧浓度分别为 2.19、0.7 mol/m³，扩散距离 3.2 cm，面积 0.05 m²。浓度沿程线性，扩散系数为 \\(2.16\\times10^{-5}\\,\\mathrm{m^2\\,s^{-1}}\\)。求通过整个截面的物质的量输运速率大小。","options":["\\(0.005029\\,\\mathrm{mol\\,s^{-1}}\\)","\\(5.029\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(9.754\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.001006\\,\\mathrm{mol\\,s^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-fick-steady-flow","explanation":"菲克定律给出的通量大小为 \\(D|\\mathrm dc/\\mathrm dx|\\)，浓度线性时是 \\(D|c_1-c_2|/L\\)。乘以截面积得到总速率。 得 \\(5.029\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)。"},
  {"id":"t-linear-expansion-3","type":"single","points":1,"stem":"自由伸缩的细杆初长 1.7 m，线膨胀系数近似恒为 \\(1.32\\times10^{-5}\\,\\mathrm{K^{-1}}\\)。升温 53 K 后，长度增加量约是多少？","options":["\\(0.001189\\,\\mathrm m\\)","\\(1.189\\times10^{-6}\\,\\mathrm m\\)","\\(0.0006996\\,\\mathrm m\\)","\\(0.003568\\,\\mathrm m\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-linear-expansion","explanation":"一阶近似下 \\(\\Delta L=\\alpha L_0\\Delta T\\)。长度和温差直接以题设单位代入。 得 \\(0.001189\\,\\mathrm m\\)。"},
  {"id":"t-curved-interfaces-3","type":"multiple","points":2,"stem":"一个液滴与一个薄壁肥皂泡的半径均为 0.73 mm，界面张力均为 0.065 N/m。忽略重力导致的变形。下列说法正确的是哪些？","options":["液滴内部压强小于外界。","肥皂泡内外压差约 \\(356.2\\,\\mathrm{Pa}\\)。","肥皂膜只有一个气液界面。","液滴内外压差约 \\(178.1\\,\\mathrm{Pa}\\)。","相同界面张力下，把肥皂泡的半径加倍，其内外压差减半。"],"answer":[1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-curved-interfaces","explanation":"球形单界面的拉普拉斯压差是 \\(2\\sigma/r\\)。液滴仅一个界面，薄壁肥皂泡近似有两个等半径的界面，两个压差相加。压差均与半径成反比。"},
  {"id":"t-capillary-rise-3","type":"single","points":2,"stem":"毛细管内半径 0.38 mm，液体完全润湿管壁，液体密度 940 kg/m³、表面张力 0.052 N/m。忽略管外液面变化，管内液面约上升多高？","options":["\\(0.01484\\,\\mathrm m\\)","\\(29.68\\,\\mathrm m\\)","\\(0.05936\\,\\mathrm m\\)","\\(0.02968\\,\\mathrm m\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-capillary-rise","explanation":"完全润湿时接触角为零。竖直表面张力为 \\(2\\pi r\\sigma\\)，平衡液柱重力 \\(\\rho g\\pi r^2 h\\)。联立求高度。 得 \\(0.02968\\,\\mathrm m\\)。","reference":"重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。"},
  {"id":"t-heating-partial-vaporization-3","type":"single","points":3,"stem":"常压下质量 0.19 kg 的水从 22 ℃ 加热到 100 ℃，随后其质量的 22% 在 100 ℃ 汽化。取水的比热容为 4180 J/(kg·K)，汽化潜热为 \\(2.25\\times10^{6}\\,\\mathrm{J\\,kg^{-1}}\\)。忽略热损失，总吸热约是多少？","options":["\\(1.56\\times10^{5}\\,\\mathrm{J}\\)","\\(6.195\\times10^{4}\\,\\mathrm{J}\\)","\\(9.405\\times10^{4}\\,\\mathrm{J}\\)","\\(4.894\\times10^{5}\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 8 章","family":"t-heating-partial-vaporization","explanation":"升温吸热 \\(Q_1=mc\\Delta T\\)。汽化阶段只用实际汽化的质量乘潜热，\\(Q_2=mfL_v\\)。总吸热为两项之和。 得 \\(1.56\\times10^{5}\\,\\mathrm{J}\\)。"},
  {"id":"t-reversible-melting-entropy-3","type":"single","points":2,"stem":"某纯物质在规定压强下的熔点为 250 K，熔化潜热为 \\(3\\times10^{5}\\,\\mathrm{J\\,kg^{-1}}\\)。将处于熔点的 0.23 kg 固体缓慢熔化成同温液体。物质的熵变约是多少？","options":["\\(6.9\\times10^{4}\\,\\mathrm{J\\,K^{-1}}\\)","\\(276\\,\\mathrm{J\\,K^{-1}}\\)","\\(-276\\,\\mathrm{J\\,K^{-1}}\\)","\\(1200\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-reversible-melting-entropy","explanation":"熔点处可逆等温熔化需吸收 \\(Q=mL_f\\)。等温可逆相变的熵变为 \\(Q/T_m\\)，吸热时为正。 得 \\(276\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-clapeyron-slope-3","type":"single","points":3,"stem":"某纯物质处在 334 K 的液气平衡线上。该点的摩尔汽化潜热为 31.6 kJ/mol，气相和液相的摩尔体积差为 0.019 m³/mol。求该点饱和压强对温度的斜率。","options":["\\(-4980\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(14.91\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(4980\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(94.61\\,\\mathrm{Pa\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-clapeyron-slope","explanation":"克拉珀龙方程 \\( \\mathrm dp_\\mathrm{sat}/\\mathrm dT=L_m/[T(V_{m,g}-V_{m,l})] \\)。把摩尔潜热从 kJ/mol 换成 J/mol 后代入，气相摩尔体积更大，因此斜率为正。 得 \\(4980\\,\\mathrm{Pa\\,K^{-1}}\\)。"},
  {"id":"t-without-replacement-4","type":"single","points":1,"stem":"袋中有 8 个红球、4 个蓝球。一次不放回地随机抽取两个球，两个都是红球的概率约是多少？","options":["\\(0.2121\\)","\\(0.4444\\)","\\(0.4242\\)","\\(0.6667\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-without-replacement","explanation":"在不放回抽样中，第二次取红的条件概率为 \\((r-1)/(N-1)\\)。与首次概率 \\(r/N\\) 相乘。 得 \\(0.4242\\)。"},
  {"id":"t-random-walk-origin-4","type":"single","points":2,"stem":"微粒从原点出发，在一条直线上独立地走 10 步，每步等概率向左或向右移动一个单位。最后回到原点的概率约是多少？","options":["\\(0.2461\\)","\\(0.5\\)","\\(0.0009766\\)","\\(0.09091\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-random-walk-origin","explanation":"回到原点要求左右各走一半步数。共有 \\(\\binom{N}{N/2}\\) 条这样的序列，总序列数为 \\(2^N\\)。 得 \\(0.2461\\)。"},
  {"id":"t-power-density-4","type":"single","points":3,"stem":"连续随机变量的概率密度在 0 到 5 之间为 \\(f(x)=C x^{1}\\)，区间外为零。该变量落在 0 到 1 之间的概率约是多少？","options":["\\(0.04\\)","\\(0.96\\)","\\(0.008\\)","\\(0.2\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-power-density","explanation":"归一化要求分母为 \\(\\int_0^{L}x^a\\,\\mathrm dx\\)。区间概率是 \\(\\int_0^b x^a\\,\\mathrm dx/\\int_0^L x^a\\,\\mathrm dx=(b/L)^{a+1}\\)。 得 \\(0.04\\)。","reference":"当 \\(a>-1\\) 时，\\(\\int_0^L x^a\\,\\mathrm dx=L^{a+1}/(a+1)\\)。"},
  {"id":"t-rigid-vessel-temperature-4","type":"single","points":1,"stem":"密闭刚性容器里装有一定量理想气体。气体从 280 K 缓慢升温到 367 K，初态绝对压强为 111 kPa。末态压强约是多少？","options":["\\(84.69\\,\\mathrm{kPa}\\)","\\(145.5\\,\\mathrm{kPa}\\)","\\(468.2\\,\\mathrm{kPa}\\)","\\(111\\,\\mathrm{kPa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-rigid-vessel-temperature","explanation":"容积和物质的量保持恒定，状态方程给出 \\(p_2/p_1=T_2/T_1\\)。 得 \\(145.5\\,\\mathrm{kPa}\\)。"},
  {"id":"t-dalton-partial-pressure-4","type":"single","points":1,"stem":"两种互不反应的理想气体形成均匀混合气。A 组分有 5 mol，B 组分有 13 mol，总压强为 173 kPa。A 的分压约是多少？","options":["\\(66.54\\,\\mathrm{kPa}\\)","\\(9.611\\,\\mathrm{kPa}\\)","\\(48.06\\,\\mathrm{kPa}\\)","\\(124.9\\,\\mathrm{kPa}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 2 章","family":"t-dalton-partial-pressure","explanation":"各组分在同一温度和体积下服从状态方程，分压占总压的比例等于摩尔分数。 得 \\(48.06\\,\\mathrm{kPa}\\)。"},
  {"id":"t-joined-vessels-4","type":"single","points":2,"stem":"两个容积分别为 6 L、14 L 的刚性容器分别装有理想气体，压强为 230 kPa、77 kPa。两容器均已与同一恒温浴达到热平衡，打开连通阀直至新平衡。末态总压强约是多少？","options":["\\(153.5\\,\\mathrm{kPa}\\)","\\(122.9\\,\\mathrm{kPa}\\)","\\(184.1\\,\\mathrm{kPa}\\)","\\(307\\,\\mathrm{kPa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-joined-vessels","explanation":"由初态两侧总物质的量守恒，且温度相同，有 \\(p_f(V_1+V_2)=p_1V_1+p_2V_2\\)。 得 \\(122.9\\,\\mathrm{kPa}\\)。"},
  {"id":"t-gas-mass-pressure-4","type":"single","points":2,"stem":"3.5 kg 氮气装在体积为 1.1 立方米的容器内，温度为 316 K。把氮气视为理想气体，取其摩尔质量 28 g/mol，求绝对压强。","options":["\\(5.971\\times10^{5}\\,\\mathrm{Pa}\\)","\\(2.985\\times10^{5}\\,\\mathrm{Pa}\\)","\\(8359\\,\\mathrm{Pa}\\)","\\(2.985\\times10^{8}\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-gas-mass-pressure","explanation":"先以 \\(n=m/M\\) 将质量换成摩尔数，再由 \\(p=nRT/V\\) 代入。注意 \\(28\\,\\mathrm{g\\,mol^{-1}}=0.028\\,\\mathrm{kg\\,mol^{-1}}\\)。 得 \\(2.985\\times10^{5}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-van-der-waals-pressure-4","type":"single","points":3,"stem":"某气体每摩尔体积为 1.11 L/mol、温度为 293 K。范德瓦尔斯参数分别为 \\(0.169\\,\\mathrm{Pa\\,m^6\\,mol^{-2}}\\) 和 \\(0.000395\\,\\mathrm{m^3\\,mol^{-1}}\\)。求压强。","options":["\\(1.481\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.27\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.544\\times10^{6}\\,\\mathrm{Pa}\\)","\\(2.195\\times10^{6}\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-van-der-waals-pressure","explanation":"采用摩尔体积形式，\\(p=RT/(V_m-b)-a/V_m^2\\)。体积应先换成 \\(\\mathrm{m^3\\,mol^{-1}}\\)。 得 \\(3.27\\times10^{6}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-mean-free-path-4","type":"single","points":2,"stem":"温度为 291 K、压强为 150 Pa 的稀薄气体由有效直径 0.34 nm 的相同硬球分子组成。估算分子的平均自由程。","options":["\\(2.608\\times10^{-5}\\,\\mathrm m\\)","\\(5.215\\times10^{-5}\\,\\mathrm m\\)","\\(0.0001638\\,\\mathrm m\\)","\\(7.375\\times10^{-5}\\,\\mathrm m\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-mean-free-path","explanation":"由 \\(n=p/(k_\\mathrm BT)\\) 求数密度。相同硬球的平均自由程是 \\(\\lambda=1/(\\sqrt2\\,\\pi d^2 n)\\)，其中 \\(\\pi d^2\\) 为碰撞截面。 得 \\(5.215\\times10^{-5}\\,\\mathrm m\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-rms-temperature-4","type":"single","points":2,"stem":"一种理想气体的摩尔质量为 40 g/mol，分子的方均根速率为 500 m/s。求该气体的热力学温度。","options":["\\(1203\\,\\mathrm{K}\\)","\\(400.9\\,\\mathrm{K}\\)","\\(200.5\\,\\mathrm{K}\\)","\\(601.4\\,\\mathrm{K}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-rms-temperature","explanation":"平均平动动能为 \\(3k_\\mathrm BT/2\\)，所以 \\(v_{\\mathrm{rms}}^2=3RT/M\\)。摩尔质量应以 kg/mol 代入。 得 \\(400.9\\,\\mathrm{K}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-kinetic-pressure-4","type":"single","points":2,"stem":"理想气体的压强为 110 kPa，质量密度为 0.89 kg/m³。估计分子的方均根速率。","options":["\\(861.1\\,\\mathrm{m\\,s^{-1}}\\)","\\(351.6\\,\\mathrm{m\\,s^{-1}}\\)","\\(430.6\\,\\mathrm{m\\,s^{-1}}\\)","\\(608.9\\,\\mathrm{m\\,s^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-kinetic-pressure","explanation":"分子运动论给出 \\(p=\\rho v_{\\mathrm{rms}}^2/3\\)，压强换成 Pa 后求平方根。 得 \\(608.9\\,\\mathrm{m\\,s^{-1}}\\)。"},
  {"id":"t-collision-frequency-4","type":"single","points":1,"stem":"某稀薄气体分子的平均速率为 445 m/s，平均自由程为 118 nm。估计单个分子的平均碰撞频率。","options":["\\(3.771\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(3.771\\,\\mathrm{s^{-1}}\\)","\\(7.542\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(9.428\\times10^{8}\\,\\mathrm{s^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-collision-frequency","explanation":"在平均意义下，单位时间经历的自由程数约为 \\(\\bar v/\\lambda\\)。将 nm 换成 m 再相除。 得 \\(3.771\\times10^{9}\\,\\mathrm{s^{-1}}\\)。"},
  {"id":"t-maxwell-temperature-ratio-4","type":"single","points":1,"stem":"同一种气体分别处于 310 K 和 415 K 的平衡态。后者与前者的最概然速率之比约是多少？","options":["\\(0.8643\\)","\\(1.157\\)","\\(0.3387\\)","\\(1.339\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-temperature-ratio","explanation":"同种气体的分子质量相同，最概然速率 \\(v_p=\\sqrt{2RT/M}\\) 与绝对温度的平方根成正比。 得 \\(1.157\\)。"},
  {"id":"t-barometric-ratio-4","type":"single","points":3,"stem":"把大气视为均匀摩尔质量为 30 g/mol 的理想气体，设温度恒为 282 K、重力加速度不随高度改变。海拔比基准面高 2750 m 处的气压是基准面气压的多少倍？","options":["\\(0.7081\\)","\\(1.412\\)","\\(0.2919\\)","\\(0.5014\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-barometric-ratio","explanation":"将静力平衡 \\(\\mathrm dp/\\mathrm dz=-\\rho g\\) 与 \\(\\rho=Mp/(RT)\\) 联立并积分，得到 \\(p(z)/p(0)=\\exp[-Mgz/(RT)]\\)。 得 \\(0.7081\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-two-level-population-4","type":"single","points":3,"stem":"一批可分辨的弱相互作用粒子在 340 K 达到热平衡。每个粒子仅能处在两个非简并能级，上能级比下能级高 \\(8.966\\times10^{-21}\\,\\mathrm{J}\\)。约有多大比例的粒子在上能级？","options":["\\(0.1481\\)","\\(0.871\\)","\\(0.129\\)","\\(0.02193\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-two-level-population","explanation":"以上能级和下能级的玻尔兹曼权重分别为 \\(\\exp[-\\Delta E/(k_\\mathrm BT)]\\) 和 1，将上能级权重除以两权重之和。 得 \\(0.129\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-mixture-equipartition-4","type":"single","points":2,"stem":"4 mol 单原子理想气体与 5 mol 刚性双原子理想气体混合，在 303 K 达到热平衡。忽略双原子分子的振动，混合气体的总内能约是多少？","options":["\\(3.401\\times10^{4}\\,\\mathrm{J}\\)","\\(9.321\\times10^{4}\\,\\mathrm{J}\\)","\\(4.66\\times10^{4}\\,\\mathrm{J}\\)","\\(5.668\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-mixture-equipartition","explanation":"按能量均分，单原子有 3 个自由度，刚性双原子有 5 个自由度。分别计算 \\(f nRT/2\\) 后相加。 得 \\(4.66\\times10^{4}\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-maxwell-concepts-4","type":"multiple","points":2,"stem":"温度为 353 K 的氧气和温度为 292 K 的氮气都处于无宏观流动的平衡态。取氧气、氮气的摩尔质量分别为 32 和 28 g/mol。关于它们的麦克斯韦速率分布，正确的是哪些？","options":["任一种气体的分子平均速度矢量为零。","氧气与氮气的最概然速率之比约为 \\(1.028\\)。","同一种气体升温，最概然速率增大。","氧气的最概然速率低于氮气。","在同一平衡态，任一种气体的最概然速率大于其方均根速率。"],"answer":[0,1,2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-concepts","explanation":"最概然速率为 \\(v_p=\\sqrt{2RT/M}\\)。两种气体的速率之比由各自的 \\(T/M\\) 决定；升温则最概然速率增大。最概然速率小于方均根速率。平衡态无宏观流动，各方向的速度矢量平均为零。"},
  {"id":"t-isobaric-work-4","type":"single","points":1,"stem":"2.1 mol 理想气体在压强不变的情况下从 299 K 升至 348 K。气体对外做的体积功约是多少？","options":["\\(427.8\\,\\mathrm{J}\\)","\\(1283\\,\\mathrm{J}\\)","\\(2139\\,\\mathrm{J}\\)","\\(855.5\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isobaric-work","explanation":"等压过程 \\(W=p(V_2-V_1)\\)。由状态方程，\\(p(V_2-V_1)=nR(T_2-T_1)\\)。 得 \\(855.5\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isochoric-heating-4","type":"single","points":1,"stem":"1.3 mol 单原子理想气体在刚性容器中从 299 K 加热到 338 K，仅交换热量。气体吸热约是多少？","options":["\\(1265\\,\\mathrm{J}\\)","\\(421.5\\,\\mathrm{J}\\)","\\(632.3\\,\\mathrm{J}\\)","\\(1054\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isochoric-heating","explanation":"定容过程没有体积功，吸热等于内能增加。单原子理想气体的定容摩尔热容为 \\(3R/2\\)。 得 \\(632.3\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isothermal-work-4","type":"single","points":2,"stem":"1.15 mol 理想气体在 306 K 从体积 5 L 可逆等温膨胀到 11.45 L。气体对外做功约是多少？","options":["\\(3774\\,\\mathrm{J}\\)","\\(1212\\,\\mathrm{J}\\)","\\(1648\\,\\mathrm{J}\\)","\\(2424\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isothermal-work","explanation":"准静态做功为 \\(\\int p\\,\\mathrm dV\\)。等温时 \\(p=nRT/V\\)，积分得 \\(W=nRT\\ln(V_2/V_1)\\)。 得 \\(2424\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-adiabatic-expansion-temperature-4","type":"single","points":2,"stem":"1.5 mol 单原子理想气体初温 330 K，可逆绝热膨胀至原体积的 2.3 倍。末温约是多少？","options":["\\(189.4\\,\\mathrm{K}\\)","\\(143.5\\,\\mathrm{K}\\)","\\(575\\,\\mathrm{K}\\)","\\(217.6\\,\\mathrm{K}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-adiabatic-expansion-temperature","explanation":"可逆绝热过程 \\(TV^{\\gamma-1}\\) 不变，单原子气体 \\(\\gamma=5/3\\)。据此由体积比求温度比。 得 \\(189.4\\,\\mathrm{K}\\)。"},
  {"id":"t-adiabatic-compression-work-4","type":"single","points":3,"stem":"1.8 mol 刚性双原子理想气体初温为 310 K，经可逆绝热压缩，体积缩小为原来的 1/2.32。外界对气体做的功约是多少？","options":["\\(1857\\,\\mathrm{J}\\)","\\(6498\\,\\mathrm{J}\\)","\\(4642\\,\\mathrm{J}\\)","\\(3904\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-adiabatic-compression-work","explanation":"忽略振动时 \\(\\gamma=7/5\\)，由 \\(TV^{\\gamma-1}=\\text{常量}\\) 求末温。因 \\(Q=0\\)，外界做功等于 \\(\\Delta U=\\tfrac52nR(T_2-T_1)\\)。 得 \\(4642\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-linear-path-work-4","type":"single","points":2,"stem":"一份气体在准静态膨胀中体积增加 3.2 L，压强从 90 kPa 随体积线性升到 206 kPa。气体对外做功是多少？","options":["\\(473.6\\,\\mathrm{J}\\)","\\(659.2\\,\\mathrm{J}\\)","\\(288\\,\\mathrm{J}\\)","\\(371.2\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-linear-path-work","explanation":"沿直线过程，\\(p\\!-\\!V\\) 图下方的梯形面积等于平均压强乘体积变化。\\(1\\,\\mathrm{kPa\\,L}=1\\,\\mathrm J\\)。 得 \\(473.6\\,\\mathrm{J}\\)。"},
  {"id":"t-rectangular-cycle-4","type":"multiple","points":2,"stem":"理想气体沿顺时针矩形循环运行。两条等压边压强分别为 100 kPa 和 225 kPa，两条等容边体积分别为 6 L 和 14 L。关于整个循环，下列说法正确的是哪些？","options":["气体净对外做功为 \\(1000\\,\\mathrm{J}\\)。","一周后气体内能变化为零。","沿两个等容段，体积功均为零。","一周后气体总吸热一定为零。","高压等压边与低压等压边的体积功大小相等。"],"answer":[0,1,2],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-rectangular-cycle","explanation":"顺时针循环的净功为矩形面积 \\((p_h-p_l)(V_h-V_l)\\)。回到起态时 \\(\\Delta U=0\\)，净吸热等于净功，非零。等容段 \\(\\mathrm dV=0\\)，两条等压边体积改变量大小相同但压强不同。"},
  {"id":"t-isobaric-monatomic-budget-4","type":"multiple","points":2,"stem":"2.5 mol 单原子理想气体在恒压下从 318 K 加热至 363 K，只做体积功。下列数量关系正确的是哪些？","options":["气体吸热等于内能的增加量。","气体吸收热量 \\(2338\\,\\mathrm{J}\\)。","气体的内能增加 \\(1403\\,\\mathrm{J}\\)。","气体的焓不变。","气体对外做功 \\(935.3\\,\\mathrm{J}\\)。"],"answer":[1,2,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isobaric-monatomic-budget","explanation":"定压时 \\(W=nR\\Delta T\\)，内能变化为 \\(nC_V\\Delta T\\)，焓变化 \\(nC_p\\Delta T\\) 等于吸热。单原子气体 \\(C_V=3R/2,\\ C_p=5R/2\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-two-stage-heating-expansion-4","type":"single","points":3,"stem":"2.2 mol 单原子理想气体先定容地从 300 K 加热到 340 K，接着在 340 K 可逆等温膨胀，体积变为原来的 2 倍。两阶段总吸热约是多少？","options":["\\(4311\\,\\mathrm{J}\\)","\\(6140\\,\\mathrm{J}\\)","\\(1097\\,\\mathrm{J}\\)","\\(5408\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-two-stage-heating-expansion","explanation":"第一段等容，\\(Q_1=\\Delta U_1=\\tfrac32nR(T_2-T_1)\\)。第二段等温，\\(Q_2=W_2=nRT_2\\ln(V_f/V_i)\\)。总吸热为两段之和。 得 \\(5408\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-polytropic-work-4","type":"single","points":3,"stem":"气体从 4 L 准静态膨胀至 8.3 L，初压 114 kPa。过程满足 \\(pV^{1.355}\\) 为常量。气体对外做功约是多少？","options":["\\(293.2\\,\\mathrm{J}\\)","\\(182.3\\,\\mathrm{J}\\)","\\(490.2\\,\\mathrm{J}\\)","\\(332.9\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-polytropic-work","explanation":"设 \\(pV^s=C\\)，把 \\(p=CV^{-s}\\) 代入体积功积分，可得 \\(W=(p_2V_2-p_1V_1)/(1-s)\\)。用状态间的多方关系求 \\(p_2\\)。 得 \\(293.2\\,\\mathrm{J}\\)。","reference":"当 \\(a\\ne-1\\) 时，\\(\\int x^a\\,\\mathrm dx=x^{a+1}/(a+1)+C\\)。"},
  {"id":"t-compression-energy-balance-4","type":"multiple","points":2,"stem":"气体在带活塞的容器中被缓慢压缩。过程中气体吸热 1425 J，外界对气体做功 379 J，忽略其他能量交换。下列说法正确的是哪些？","options":["按气体对外做功为正的约定，气体的体积功为 \\(-379\\,\\mathrm{J}\\)。","热量等于外界对气体做的功。","气体内能增加 \\(1804\\,\\mathrm{J}\\)。","气体一定放热。","气体的内能变化等于 \\(1046\\,\\mathrm{J}\\)。"],"answer":[0,2],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-compression-energy-balance","explanation":"采用 \\(\\Delta U=Q-W_{\\mathrm{by}}\\)。吸热 \\(Q>0\\)，压缩时气体对外做功 \\(W_{\\mathrm{by}}<0\\)。内能增加量等于吸热量与外界做功之和。"},
  {"id":"t-carnot-absorbed-heat-4","type":"single","points":3,"stem":"一台可逆热机在 575 K 的高温热源与 291 K 的低温热源之间工作，每循环对外净做功 1110 J。每循环从高温热源吸热约是多少？","options":["\\(2247\\,\\mathrm{J}\\)","\\(2193\\,\\mathrm{J}\\)","\\(1110\\,\\mathrm{J}\\)","\\(548.2\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-absorbed-heat","explanation":"卡诺效率 \\(\\eta=1-T_\\mathrm c/T_\\mathrm h\\)，同时 \\(\\eta=W/Q_\\mathrm h\\)。把两式联立求 \\(Q_\\mathrm h\\)。 得 \\(2247\\,\\mathrm{J}\\)。"},
  {"id":"t-carnot-heat-balance-4","type":"multiple","points":2,"stem":"卡诺热机在 606 K、317 K 的两个热源之间运行，每周吸收高温热量 1750 J。下列说法正确的是哪些？","options":["高温热源每周熵增约 \\(2.888\\,\\mathrm{J\\,K^{-1}}\\)。","每周向低温热源放热约 \\(915.4\\,\\mathrm{J}\\)。","工质每周的熵变为零。","两热源的总熵在每周内严格增加。","每周净输出功约 \\(834.6\\,\\mathrm{J}\\)。"],"answer":[1,2,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-heat-balance","explanation":"卡诺循环可逆，有 \\(Q_\\mathrm h/T_\\mathrm h=Q_\\mathrm c/T_\\mathrm c\\)。净功为两热量之差，工质状态复原。低温热源的正熵变与高温热源的负熵变抵消。"},
  {"id":"t-carnot-refrigerator-4","type":"multiple","points":2,"stem":"可逆制冷机的冷端为 262 K、热端为 333 K，每周期从冷端移走 800 J。下列说法正确的是哪些？","options":["在保持热端温度不变时，降低冷端温度会提高制冷系数。","热端每周期得到的热量小于冷端失去的热量。","热端每周期得到热量 \\(1017\\,\\mathrm{J}\\)。","外界每周期至少输入功 \\(216.8\\,\\mathrm{J}\\)。","制冷系数约为 \\(3.69\\)。"],"answer":[2,3,4],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-carnot-refrigerator","explanation":"制冷机的卡诺制冷系数为 \\(T_\\mathrm c/(T_\\mathrm h-T_\\mathrm c)\\)。由 \\(W=Q_\\mathrm c/\\varepsilon\\) 求输入功，再用 \\(Q_\\mathrm h=Q_\\mathrm c+W\\)。冷端温度降低时制冷更困难。"},
  {"id":"t-reservoir-transfer-entropy-4","type":"single","points":2,"stem":"1840 J 热量自行从恒温 437 K 的热源传给恒温 301 K 的热源，无其他作用。两个热源的总熵增约是多少？","options":["\\(1.902\\,\\mathrm{J\\,K^{-1}}\\)","\\(-1.902\\,\\mathrm{J\\,K^{-1}}\\)","\\(10.32\\,\\mathrm{J\\,K^{-1}}\\)","\\(6.113\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-reservoir-transfer-entropy","explanation":"冷热源各自在恒温下交换热量。热源失热熵变 \\(-Q/T_\\mathrm h\\)，冷源得热熵变 \\(Q/T_\\mathrm c\\)，二者相加。 得 \\(1.902\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-insulated-free-expansion-4","type":"multiple","points":2,"stem":"1.7 mol 理想气体在绝热刚性容器中，撤去隔板后向真空自由膨胀，最终占据原来的 2.2 倍体积。下列说法正确的是哪些？","options":["因为过程绝热，所以气体熵变为零。","气体熵增约 \\(11.14\\,\\mathrm{J\\,K^{-1}}\\)。","这个过程可以仅靠气体自身逆向恢复而不引起其他变化。","初态和末态温度相同。","气体和外界之间没有热传递，也没有体积功。"],"answer":[1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-insulated-free-expansion","explanation":"自由膨胀无外压，且绝热，因此 \\(\\Delta U=0\\)。理想气体的内能只由温度决定，初末温度相同。熵是状态函数，可用连接两平衡态的可逆等温膨胀计算 \\(\\Delta S=nR\\ln(V_f/V_i)>0\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-finite-bodies-entropy-4","type":"single","points":3,"stem":"绝热容器内有两个只交换热量的物体。第一物体热容 285 J/K、初温 309 K，第二物体热容 387 J/K、初温 401 K。热容均为常数。到达共同温度后，两物体总熵增加约多少？","options":["\\(5.486\\,\\mathrm{J\\,K^{-1}}\\)","\\(45.1\\,\\mathrm{J\\,K^{-1}}\\)","\\(-5.486\\,\\mathrm{J\\,K^{-1}}\\)","\\(39.62\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-finite-bodies-entropy","explanation":"先用能量守恒求共同温度 \\(T_f=(C_1T_1+C_2T_2)/(C_1+C_2)\\)。各物体的熵变分别是 \\(C_i\\ln(T_f/T_i)\\)，将一正一负的两项相加。 得 \\(5.486\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-ideal-mixture-entropy-4","type":"single","points":3,"stem":"绝热刚性容器中有 2 mol A 和 3.6 mol B，均为不同的理想气体，初态分置两隔间，温度和压强都相同。撤去隔板后两气体完全混合。混合熵约是多少？","options":["\\(13.22\\,\\mathrm{J\\,K^{-1}}\\)","\\(30.34\\,\\mathrm{J\\,K^{-1}}\\)","\\(17.12\\,\\mathrm{J\\,K^{-1}}\\)","\\(46.56\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-ideal-mixture-entropy","explanation":"相同初始温压下，初体积占比等于摩尔分数 \\(x_i\\)。混合后每一组分可及体积为总容积，等效可逆等温膨胀的熵增为 \\(-n_iR\\ln x_i\\)。相加得到混合熵。 得 \\(30.34\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-entropy-temperature-volume-4","type":"single","points":3,"stem":"1.75 mol 刚性双原子理想气体从 300 K 变为 378 K，体积同时扩大至原来的 1.52 倍。忽略振动，求气体的熵变。","options":["\\(14.5\\,\\mathrm{J\\,K^{-1}}\\)","\\(8.406\\,\\mathrm{J\\,K^{-1}}\\)","\\(6.092\\,\\mathrm{J\\,K^{-1}}\\)","\\(2.314\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-entropy-temperature-volume","explanation":"可选先等容升温再等温膨胀作为可逆辅助路径。分别积出 \\(nC_V\\ln(T_2/T_1)\\) 和 \\(nR\\ln(V_2/V_1)\\)，相加。 得 \\(14.5\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-steady-conduction-4","type":"single","points":2,"stem":"面积为 0.23 m²、厚度 20 mm 的均匀平板，导热系数为 0.57 W/(m·K)，两表面恒温 355 K 和 302 K。忽略侧面漏热，稳定导热速率约是多少？","options":["\\(694.8\\,\\mathrm W\\)","\\(1511\\,\\mathrm W\\)","\\(347.4\\,\\mathrm W\\)","\\(0.3474\\,\\mathrm W\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-steady-conduction","explanation":"稳定的一维傅里叶导热通量为 \\(j_Q=k(T_h-T_c)/L\\)。总导热速率还要乘面积，厚度从毫米换成米。 得 \\(347.4\\,\\mathrm W\\)。"},
  {"id":"t-series-conduction-4","type":"single","points":3,"stem":"面积 0.26 m² 的双层墙，第一层厚 34 mm、导热系数 0.27 W/(m·K)，第二层厚 48 mm、导热系数 0.6 W/(m·K)。外表面温差为 43 K，层间接触热阻忽略。稳定导热功率约是多少？","options":["\\(88.78\\,\\mathrm W\\)","\\(54.29\\,\\mathrm W\\)","\\(139.8\\,\\mathrm W\\)","\\(118.6\\,\\mathrm W\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-series-conduction","explanation":"两层串联时同一功率穿过每层，热阻为 \\(L/(kA)\\)。把热阻相加，外表面温差除以总热阻。 得 \\(54.29\\,\\mathrm W\\)。"},
  {"id":"t-couette-shear-4","type":"single","points":2,"stem":"两块平行板间夹有牛顿流体，板间距 5.2 mm，流体动力黏度 0.105 Pa·s。下板固定，上板以 0.84 m/s 匀速移动。忽略边缘效应，若上板接触面积 0.185 m²，流体对上板黏滞力的大小约是多少？","options":["\\(0.003138\\,\\mathrm N\\)","\\(3.138\\,\\mathrm N\\)","\\(6.276\\,\\mathrm N\\)","\\(16.96\\,\\mathrm N\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-couette-shear","explanation":"平板间的速度梯度为 \\(u/h\\)。牛顿黏性定律给出剪应力 \\(\\eta u/h\\)，再乘受力面积。 得 \\(3.138\\,\\mathrm N\\)。"},
  {"id":"t-fick-steady-flow-4","type":"single","points":2,"stem":"两侧浓度分别为 2.41、0.81 mol/m³，扩散距离 3.8 cm，面积 0.06 m²。浓度沿程线性，扩散系数为 \\(2.44\\times10^{-5}\\,\\mathrm{m^2\\,s^{-1}}\\)。求通过整个截面的物质的量输运速率大小。","options":["\\(0.006164\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.0001241\\,\\mathrm{mol\\,s^{-1}}\\)","\\(6.164\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.001027\\,\\mathrm{mol\\,s^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-fick-steady-flow","explanation":"菲克定律给出的通量大小为 \\(D|\\mathrm dc/\\mathrm dx|\\)，浓度线性时是 \\(D|c_1-c_2|/L\\)。乘以截面积得到总速率。 得 \\(6.164\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)。"},
  {"id":"t-linear-expansion-4","type":"single","points":1,"stem":"自由伸缩的细杆初长 2 m，线膨胀系数近似恒为 \\(1.43\\times10^{-5}\\,\\mathrm{K^{-1}}\\)。升温 60 K 后，长度增加量约是多少？","options":["\\(0.005148\\,\\mathrm m\\)","\\(0.000858\\,\\mathrm m\\)","\\(0.001716\\,\\mathrm m\\)","\\(1.716\\times10^{-6}\\,\\mathrm m\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-linear-expansion","explanation":"一阶近似下 \\(\\Delta L=\\alpha L_0\\Delta T\\)。长度和温差直接以题设单位代入。 得 \\(0.001716\\,\\mathrm m\\)。"},
  {"id":"t-curved-interfaces-4","type":"multiple","points":2,"stem":"一个液滴与一个薄壁肥皂泡的半径均为 0.82 mm，界面张力均为 0.067 N/m。忽略重力导致的变形。下列说法正确的是哪些？","options":["肥皂膜只有一个气液界面。","液滴内外压差约 \\(163.4\\,\\mathrm{Pa}\\)。","肥皂泡内外压差约 \\(326.8\\,\\mathrm{Pa}\\)。","相同界面张力下，把肥皂泡的半径加倍，其内外压差减半。","液滴内部压强小于外界。"],"answer":[1,2,3],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-curved-interfaces","explanation":"球形单界面的拉普拉斯压差是 \\(2\\sigma/r\\)。液滴仅一个界面，薄壁肥皂泡近似有两个等半径的界面，两个压差相加。压差均与半径成反比。"},
  {"id":"t-capillary-rise-4","type":"single","points":2,"stem":"毛细管内半径 0.42 mm，液体完全润湿管壁，液体密度 960 kg/m³、表面张力 0.055 N/m。忽略管外液面变化，管内液面约上升多高？","options":["\\(0.01391\\,\\mathrm m\\)","\\(27.81\\,\\mathrm m\\)","\\(0.05562\\,\\mathrm m\\)","\\(0.02781\\,\\mathrm m\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-capillary-rise","explanation":"完全润湿时接触角为零。竖直表面张力为 \\(2\\pi r\\sigma\\)，平衡液柱重力 \\(\\rho g\\pi r^2 h\\)。联立求高度。 得 \\(0.02781\\,\\mathrm m\\)。","reference":"重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。"},
  {"id":"t-heating-partial-vaporization-4","type":"single","points":3,"stem":"常压下质量 0.215 kg 的水从 24 ℃ 加热到 100 ℃，随后其质量的 26% 在 100 ℃ 汽化。取水的比热容为 4180 J/(kg·K)，汽化潜热为 \\(2.25\\times10^{6}\\,\\mathrm{J\\,kg^{-1}}\\)。忽略热损失，总吸热约是多少？","options":["\\(5.521\\times10^{5}\\,\\mathrm{J}\\)","\\(1.941\\times10^{5}\\,\\mathrm{J}\\)","\\(6.83\\times10^{4}\\,\\mathrm{J}\\)","\\(1.258\\times10^{5}\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 8 章","family":"t-heating-partial-vaporization","explanation":"升温吸热 \\(Q_1=mc\\Delta T\\)。汽化阶段只用实际汽化的质量乘潜热，\\(Q_2=mfL_v\\)。总吸热为两项之和。 得 \\(1.941\\times10^{5}\\,\\mathrm{J}\\)。"},
  {"id":"t-reversible-melting-entropy-4","type":"single","points":2,"stem":"某纯物质在规定压强下的熔点为 255 K，熔化潜热为 \\(3.1\\times10^{5}\\,\\mathrm{J\\,kg^{-1}}\\)。将处于熔点的 0.27 kg 固体缓慢熔化成同温液体。物质的熵变约是多少？","options":["\\(328.2\\,\\mathrm{J\\,K^{-1}}\\)","\\(8.37\\times10^{4}\\,\\mathrm{J\\,K^{-1}}\\)","\\(-328.2\\,\\mathrm{J\\,K^{-1}}\\)","\\(1216\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-reversible-melting-entropy","explanation":"熔点处可逆等温熔化需吸收 \\(Q=mL_f\\)。等温可逆相变的熵变为 \\(Q/T_m\\)，吸热时为正。 得 \\(328.2\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-clapeyron-slope-4","type":"single","points":3,"stem":"某纯物质处在 341 K 的液气平衡线上。该点的摩尔汽化潜热为 33.4 kJ/mol，气相和液相的摩尔体积差为 0.02 m³/mol。求该点饱和压强对温度的斜率。","options":["\\(14.36\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(-4897\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(97.95\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(4897\\,\\mathrm{Pa\\,K^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-clapeyron-slope","explanation":"克拉珀龙方程 \\( \\mathrm dp_\\mathrm{sat}/\\mathrm dT=L_m/[T(V_{m,g}-V_{m,l})] \\)。把摩尔潜热从 kJ/mol 换成 J/mol 后代入，气相摩尔体积更大，因此斜率为正。 得 \\(4897\\,\\mathrm{Pa\\,K^{-1}}\\)。"},
  {"id":"t-without-replacement-5","type":"single","points":1,"stem":"袋中有 9 个红球、5 个蓝球。一次不放回地随机抽取两个球，两个都是红球的概率约是多少？","options":["\\(0.4133\\)","\\(0.1978\\)","\\(0.6429\\)","\\(0.3956\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-without-replacement","explanation":"在不放回抽样中，第二次取红的条件概率为 \\((r-1)/(N-1)\\)。与首次概率 \\(r/N\\) 相乘。 得 \\(0.3956\\)。"},
  {"id":"t-random-walk-origin-5","type":"single","points":2,"stem":"微粒从原点出发，在一条直线上独立地走 12 步，每步等概率向左或向右移动一个单位。最后回到原点的概率约是多少？","options":["\\(0.2256\\)","\\(0.0002441\\)","\\(0.5\\)","\\(0.07692\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-random-walk-origin","explanation":"回到原点要求左右各走一半步数。共有 \\(\\binom{N}{N/2}\\) 条这样的序列，总序列数为 \\(2^N\\)。 得 \\(0.2256\\)。"},
  {"id":"t-power-density-5","type":"single","points":3,"stem":"连续随机变量的概率密度在 0 到 6 之间为 \\(f(x)=C x^{2}\\)，区间外为零。该变量落在 0 到 1 之间的概率约是多少？","options":["\\(0.1667\\)","\\(0.0007716\\)","\\(0.00463\\)","\\(0.9954\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-power-density","explanation":"归一化要求分母为 \\(\\int_0^{L}x^a\\,\\mathrm dx\\)。区间概率是 \\(\\int_0^b x^a\\,\\mathrm dx/\\int_0^L x^a\\,\\mathrm dx=(b/L)^{a+1}\\)。 得 \\(0.00463\\)。","reference":"当 \\(a>-1\\) 时，\\(\\int_0^L x^a\\,\\mathrm dx=L^{a+1}/(a+1)\\)。"},
  {"id":"t-rigid-vessel-temperature-5","type":"single","points":1,"stem":"密闭刚性容器里装有一定量理想气体。气体从 290 K 缓慢升温到 376 K，初态绝对压强为 118 kPa。末态压强约是多少？","options":["\\(153\\,\\mathrm{kPa}\\)","\\(515.9\\,\\mathrm{kPa}\\)","\\(91.01\\,\\mathrm{kPa}\\)","\\(118\\,\\mathrm{kPa}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-rigid-vessel-temperature","explanation":"容积和物质的量保持恒定，状态方程给出 \\(p_2/p_1=T_2/T_1\\)。 得 \\(153\\,\\mathrm{kPa}\\)。"},
  {"id":"t-dalton-partial-pressure-5","type":"single","points":1,"stem":"两种互不反应的理想气体形成均匀混合气。A 组分有 6 mol，B 组分有 15 mol，总压强为 184 kPa。A 的分压约是多少？","options":["\\(131.4\\,\\mathrm{kPa}\\)","\\(52.57\\,\\mathrm{kPa}\\)","\\(73.6\\,\\mathrm{kPa}\\)","\\(8.762\\,\\mathrm{kPa}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 2 章","family":"t-dalton-partial-pressure","explanation":"各组分在同一温度和体积下服从状态方程，分压占总压的比例等于摩尔分数。 得 \\(52.57\\,\\mathrm{kPa}\\)。"},
  {"id":"t-joined-vessels-5","type":"single","points":2,"stem":"两个容积分别为 7 L、16 L 的刚性容器分别装有理想气体，压强为 240 kPa、81 kPa。两容器均已与同一恒温浴达到热平衡，打开连通阀直至新平衡。末态总压强约是多少？","options":["\\(321\\,\\mathrm{kPa}\\)","\\(160.5\\,\\mathrm{kPa}\\)","\\(191.6\\,\\mathrm{kPa}\\)","\\(129.4\\,\\mathrm{kPa}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-joined-vessels","explanation":"由初态两侧总物质的量守恒，且温度相同，有 \\(p_f(V_1+V_2)=p_1V_1+p_2V_2\\)。 得 \\(129.4\\,\\mathrm{kPa}\\)。"},
  {"id":"t-gas-mass-pressure-5","type":"single","points":2,"stem":"4 kg 氮气装在体积为 1.2 立方米的容器内，温度为 328 K。把氮气视为理想气体，取其摩尔质量 28 g/mol，求绝对压强。","options":["\\(6.493\\times10^{5}\\,\\mathrm{Pa}\\)","\\(9090\\,\\mathrm{Pa}\\)","\\(3.246\\times10^{8}\\,\\mathrm{Pa}\\)","\\(3.246\\times10^{5}\\,\\mathrm{Pa}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-gas-mass-pressure","explanation":"先以 \\(n=m/M\\) 将质量换成摩尔数，再由 \\(p=nRT/V\\) 代入。注意 \\(28\\,\\mathrm{g\\,mol^{-1}}=0.028\\,\\mathrm{kg\\,mol^{-1}}\\)。 得 \\(3.246\\times10^{5}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-van-der-waals-pressure-5","type":"single","points":3,"stem":"某气体每摩尔体积为 1.18 L/mol、温度为 299 K。范德瓦尔斯参数分别为 \\(0.182\\,\\mathrm{Pa\\,m^6\\,mol^{-2}}\\) 和 \\(0.00042\\,\\mathrm{m^3\\,mol^{-1}}\\)。求压强。","options":["\\(1.423\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.14\\times10^{6}\\,\\mathrm{Pa}\\)","\\(2.107\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.402\\times10^{6}\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-van-der-waals-pressure","explanation":"采用摩尔体积形式，\\(p=RT/(V_m-b)-a/V_m^2\\)。体积应先换成 \\(\\mathrm{m^3\\,mol^{-1}}\\)。 得 \\(3.14\\times10^{6}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-mean-free-path-5","type":"single","points":2,"stem":"温度为 298 K、压强为 160 Pa 的稀薄气体由有效直径 0.36 nm 的相同硬球分子组成。估算分子的平均自由程。","options":["\\(4.466\\times10^{-5}\\,\\mathrm m\\)","\\(6.316\\times10^{-5}\\,\\mathrm m\\)","\\(2.233\\times10^{-5}\\,\\mathrm m\\)","\\(0.0001403\\,\\mathrm m\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-mean-free-path","explanation":"由 \\(n=p/(k_\\mathrm BT)\\) 求数密度。相同硬球的平均自由程是 \\(\\lambda=1/(\\sqrt2\\,\\pi d^2 n)\\)，其中 \\(\\pi d^2\\) 为碰撞截面。 得 \\(4.466\\times10^{-5}\\,\\mathrm m\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-rms-temperature-5","type":"single","points":2,"stem":"一种理想气体的摩尔质量为 44 g/mol，分子的方均根速率为 520 m/s。求该气体的热力学温度。","options":["\\(1431\\,\\mathrm{K}\\)","\\(477\\,\\mathrm{K}\\)","\\(238.5\\,\\mathrm{K}\\)","\\(715.5\\,\\mathrm{K}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-rms-temperature","explanation":"平均平动动能为 \\(3k_\\mathrm BT/2\\)，所以 \\(v_{\\mathrm{rms}}^2=3RT/M\\)。摩尔质量应以 kg/mol 代入。 得 \\(477\\,\\mathrm{K}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-kinetic-pressure-5","type":"single","points":2,"stem":"理想气体的压强为 118 kPa，质量密度为 0.96 kg/m³。估计分子的方均根速率。","options":["\\(429.4\\,\\mathrm{m\\,s^{-1}}\\)","\\(858.8\\,\\mathrm{m\\,s^{-1}}\\)","\\(350.6\\,\\mathrm{m\\,s^{-1}}\\)","\\(607.2\\,\\mathrm{m\\,s^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-kinetic-pressure","explanation":"分子运动论给出 \\(p=\\rho v_{\\mathrm{rms}}^2/3\\)，压强换成 Pa 后求平方根。 得 \\(607.2\\,\\mathrm{m\\,s^{-1}}\\)。"},
  {"id":"t-collision-frequency-5","type":"single","points":1,"stem":"某稀薄气体分子的平均速率为 470 m/s，平均自由程为 130 nm。估计单个分子的平均碰撞频率。","options":["\\(3.615\\,\\mathrm{s^{-1}}\\)","\\(7.231\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(9.038\\times10^{8}\\,\\mathrm{s^{-1}}\\)","\\(3.615\\times10^{9}\\,\\mathrm{s^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-collision-frequency","explanation":"在平均意义下，单位时间经历的自由程数约为 \\(\\bar v/\\lambda\\)。将 nm 换成 m 再相除。 得 \\(3.615\\times10^{9}\\,\\mathrm{s^{-1}}\\)。"},
  {"id":"t-maxwell-temperature-ratio-5","type":"single","points":1,"stem":"同一种气体分别处于 330 K 和 450 K 的平衡态。后者与前者的最概然速率之比约是多少？","options":["\\(0.3636\\)","\\(0.8563\\)","\\(1.168\\)","\\(1.364\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-temperature-ratio","explanation":"同种气体的分子质量相同，最概然速率 \\(v_p=\\sqrt{2RT/M}\\) 与绝对温度的平方根成正比。 得 \\(1.168\\)。"},
  {"id":"t-barometric-ratio-5","type":"single","points":3,"stem":"把大气视为均匀摩尔质量为 31 g/mol 的理想气体，设温度恒为 286 K、重力加速度不随高度改变。海拔比基准面高 3100 m 处的气压是基准面气压的多少倍？","options":["\\(0.6727\\)","\\(1.487\\)","\\(0.3273\\)","\\(0.4525\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-barometric-ratio","explanation":"将静力平衡 \\(\\mathrm dp/\\mathrm dz=-\\rho g\\) 与 \\(\\rho=Mp/(RT)\\) 联立并积分，得到 \\(p(z)/p(0)=\\exp[-Mgz/(RT)]\\)。 得 \\(0.6727\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-two-level-population-5","type":"single","points":3,"stem":"一批可分辨的弱相互作用粒子在 370 K 达到热平衡。每个粒子仅能处在两个非简并能级，上能级比下能级高 \\(1.114\\times10^{-20}\\,\\mathrm{J}\\)。约有多大比例的粒子在上能级？","options":["\\(0.113\\)","\\(0.01278\\)","\\(0.8984\\)","\\(0.1016\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-two-level-population","explanation":"以上能级和下能级的玻尔兹曼权重分别为 \\(\\exp[-\\Delta E/(k_\\mathrm BT)]\\) 和 1，将上能级权重除以两权重之和。 得 \\(0.1016\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-mixture-equipartition-5","type":"single","points":2,"stem":"5 mol 单原子理想气体与 2 mol 刚性双原子理想气体混合，在 314 K 达到热平衡。忽略双原子分子的振动，混合气体的总内能约是多少？","options":["\\(3.263\\times10^{4}\\,\\mathrm{J}\\)","\\(4.569\\times10^{4}\\,\\mathrm{J}\\)","\\(2.741\\times10^{4}\\,\\mathrm{J}\\)","\\(6.526\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-mixture-equipartition","explanation":"按能量均分，单原子有 3 个自由度，刚性双原子有 5 个自由度。分别计算 \\(f nRT/2\\) 后相加。 得 \\(3.263\\times10^{4}\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-maxwell-concepts-5","type":"multiple","points":2,"stem":"温度为 379 K 的氧气和温度为 284 K 的氮气都处于无宏观流动的平衡态。取氧气、氮气的摩尔质量分别为 32 和 28 g/mol。关于它们的麦克斯韦速率分布，正确的是哪些？","options":["任一种气体的分子平均速度矢量为零。","同一种气体升温，最概然速率增大。","氧气与氮气的最概然速率之比约为 \\(1.081\\)。","氧气的最概然速率低于氮气。","在同一平衡态，任一种气体的最概然速率大于其方均根速率。"],"answer":[0,1,2],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-concepts","explanation":"最概然速率为 \\(v_p=\\sqrt{2RT/M}\\)。两种气体的速率之比由各自的 \\(T/M\\) 决定；升温则最概然速率增大。最概然速率小于方均根速率。平衡态无宏观流动，各方向的速度矢量平均为零。"},
  {"id":"t-isobaric-work-5","type":"single","points":1,"stem":"2.4 mol 理想气体在压强不变的情况下从 302 K 升至 357 K。气体对外做的体积功约是多少？","options":["\\(548.7\\,\\mathrm{J}\\)","\\(1646\\,\\mathrm{J}\\)","\\(1097\\,\\mathrm{J}\\)","\\(2744\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isobaric-work","explanation":"等压过程 \\(W=p(V_2-V_1)\\)。由状态方程，\\(p(V_2-V_1)=nR(T_2-T_1)\\)。 得 \\(1097\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isochoric-heating-5","type":"single","points":1,"stem":"1.5 mol 单原子理想气体在刚性容器中从 302 K 加热到 345 K，仅交换热量。气体吸热约是多少？","options":["\\(1341\\,\\mathrm{J}\\)","\\(1609\\,\\mathrm{J}\\)","\\(536.3\\,\\mathrm{J}\\)","\\(804.4\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isochoric-heating","explanation":"定容过程没有体积功，吸热等于内能增加。单原子理想气体的定容摩尔热容为 \\(3R/2\\)。 得 \\(804.4\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isothermal-work-5","type":"single","points":2,"stem":"1.3 mol 理想气体在 318 K 从体积 6 L 可逆等温膨胀到 15.12 L。气体对外做功约是多少？","options":["\\(3177\\,\\mathrm{J}\\)","\\(5224\\,\\mathrm{J}\\)","\\(2073\\,\\mathrm{J}\\)","\\(1588\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isothermal-work","explanation":"准静态做功为 \\(\\int p\\,\\mathrm dV\\)。等温时 \\(p=nRT/V\\)，积分得 \\(W=nRT\\ln(V_2/V_1)\\)。 得 \\(3177\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-adiabatic-expansion-temperature-5","type":"single","points":2,"stem":"1.7 mol 单原子理想气体初温 340 K，可逆绝热膨胀至原体积的 2.5 倍。末温约是多少？","options":["\\(215\\,\\mathrm{K}\\)","\\(136\\,\\mathrm{K}\\)","\\(184.6\\,\\mathrm{K}\\)","\\(626.3\\,\\mathrm{K}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-adiabatic-expansion-temperature","explanation":"可逆绝热过程 \\(TV^{\\gamma-1}\\) 不变，单原子气体 \\(\\gamma=5/3\\)。据此由体积比求温度比。 得 \\(184.6\\,\\mathrm{K}\\)。"},
  {"id":"t-adiabatic-compression-work-5","type":"single","points":3,"stem":"2.1 mol 刚性双原子理想气体初温为 320 K，经可逆绝热压缩，体积缩小为原来的 1/2.56。外界对气体做的功约是多少？","options":["\\(5252\\,\\mathrm{J}\\)","\\(6375\\,\\mathrm{J}\\)","\\(8926\\,\\mathrm{J}\\)","\\(2550\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-adiabatic-compression-work","explanation":"忽略振动时 \\(\\gamma=7/5\\)，由 \\(TV^{\\gamma-1}=\\text{常量}\\) 求末温。因 \\(Q=0\\)，外界做功等于 \\(\\Delta U=\\tfrac52nR(T_2-T_1)\\)。 得 \\(6375\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-linear-path-work-5","type":"single","points":2,"stem":"一份气体在准静态膨胀中体积增加 3.6 L，压强从 95 kPa 随体积线性升到 218 kPa。气体对外做功是多少？","options":["\\(442.8\\,\\mathrm{J}\\)","\\(342\\,\\mathrm{J}\\)","\\(563.4\\,\\mathrm{J}\\)","\\(784.8\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-linear-path-work","explanation":"沿直线过程，\\(p\\!-\\!V\\) 图下方的梯形面积等于平均压强乘体积变化。\\(1\\,\\mathrm{kPa\\,L}=1\\,\\mathrm J\\)。 得 \\(563.4\\,\\mathrm{J}\\)。"},
  {"id":"t-rectangular-cycle-5","type":"multiple","points":2,"stem":"理想气体沿顺时针矩形循环运行。两条等压边压强分别为 105 kPa 和 240 kPa，两条等容边体积分别为 7 L 和 16 L。关于整个循环，下列说法正确的是哪些？","options":["一周后气体总吸热一定为零。","沿两个等容段，体积功均为零。","一周后气体内能变化为零。","高压等压边与低压等压边的体积功大小相等。","气体净对外做功为 \\(1215\\,\\mathrm{J}\\)。"],"answer":[1,2,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-rectangular-cycle","explanation":"顺时针循环的净功为矩形面积 \\((p_h-p_l)(V_h-V_l)\\)。回到起态时 \\(\\Delta U=0\\)，净吸热等于净功，非零。等容段 \\(\\mathrm dV=0\\)，两条等压边体积改变量大小相同但压强不同。"},
  {"id":"t-isobaric-monatomic-budget-5","type":"multiple","points":2,"stem":"3 mol 单原子理想气体在恒压下从 324 K 加热至 376 K，只做体积功。下列数量关系正确的是哪些？","options":["气体吸热等于内能的增加量。","气体对外做功 \\(1297\\,\\mathrm{J}\\)。","气体的焓不变。","气体的内能增加 \\(1945\\,\\mathrm{J}\\)。","气体吸收热量 \\(3242\\,\\mathrm{J}\\)。"],"answer":[1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isobaric-monatomic-budget","explanation":"定压时 \\(W=nR\\Delta T\\)，内能变化为 \\(nC_V\\Delta T\\)，焓变化 \\(nC_p\\Delta T\\) 等于吸热。单原子气体 \\(C_V=3R/2,\\ C_p=5R/2\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-two-stage-heating-expansion-5","type":"single","points":3,"stem":"2.6 mol 单原子理想气体先定容地从 305 K 加热到 350 K，接着在 350 K 可逆等温膨胀，体积变为原来的 2.2 倍。两阶段总吸热约是多少？","options":["\\(8397\\,\\mathrm{J}\\)","\\(5965\\,\\mathrm{J}\\)","\\(1459\\,\\mathrm{J}\\)","\\(7424\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-two-stage-heating-expansion","explanation":"第一段等容，\\(Q_1=\\Delta U_1=\\tfrac32nR(T_2-T_1)\\)。第二段等温，\\(Q_2=W_2=nRT_2\\ln(V_f/V_i)\\)。总吸热为两段之和。 得 \\(7424\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-polytropic-work-5","type":"single","points":3,"stem":"气体从 4.5 L 准静态膨胀至 9.4 L，初压 122 kPa。过程满足 \\(pV^{1.4}\\) 为常量。气体对外做功约是多少？","options":["\\(597.8\\,\\mathrm{J}\\)","\\(404.4\\,\\mathrm{J}\\)","\\(350.3\\,\\mathrm{J}\\)","\\(213.1\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-polytropic-work","explanation":"设 \\(pV^s=C\\)，把 \\(p=CV^{-s}\\) 代入体积功积分，可得 \\(W=(p_2V_2-p_1V_1)/(1-s)\\)。用状态间的多方关系求 \\(p_2\\)。 得 \\(350.3\\,\\mathrm{J}\\)。","reference":"当 \\(a\\ne-1\\) 时，\\(\\int x^a\\,\\mathrm dx=x^{a+1}/(a+1)+C\\)。"},
  {"id":"t-compression-energy-balance-5","type":"multiple","points":2,"stem":"气体在带活塞的容器中被缓慢压缩。过程中气体吸热 1600 J，外界对气体做功 422 J，忽略其他能量交换。下列说法正确的是哪些？","options":["气体的内能变化等于 \\(1178\\,\\mathrm{J}\\)。","气体内能增加 \\(2022\\,\\mathrm{J}\\)。","热量等于外界对气体做的功。","按气体对外做功为正的约定，气体的体积功为 \\(-422\\,\\mathrm{J}\\)。","气体一定放热。"],"answer":[1,3],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-compression-energy-balance","explanation":"采用 \\(\\Delta U=Q-W_{\\mathrm{by}}\\)。吸热 \\(Q>0\\)，压缩时气体对外做功 \\(W_{\\mathrm{by}}<0\\)。内能增加量等于吸热量与外界做功之和。"},
  {"id":"t-carnot-absorbed-heat-5","type":"single","points":3,"stem":"一台可逆热机在 610 K 的高温热源与 303 K 的低温热源之间工作，每循环对外净做功 1280 J。每循环从高温热源吸热约是多少？","options":["\\(2577\\,\\mathrm{J}\\)","\\(644.2\\,\\mathrm{J}\\)","\\(1280\\,\\mathrm{J}\\)","\\(2543\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-absorbed-heat","explanation":"卡诺效率 \\(\\eta=1-T_\\mathrm c/T_\\mathrm h\\)，同时 \\(\\eta=W/Q_\\mathrm h\\)。把两式联立求 \\(Q_\\mathrm h\\)。 得 \\(2543\\,\\mathrm{J}\\)。"},
  {"id":"t-carnot-heat-balance-5","type":"multiple","points":2,"stem":"卡诺热机在 638 K、326 K 的两个热源之间运行，每周吸收高温热量 2000 J。下列说法正确的是哪些？","options":["每周向低温热源放热约 \\(1022\\,\\mathrm{J}\\)。","高温热源每周熵增约 \\(3.135\\,\\mathrm{J\\,K^{-1}}\\)。","工质每周的熵变为零。","两热源的总熵在每周内严格增加。","每周净输出功约 \\(978.1\\,\\mathrm{J}\\)。"],"answer":[0,2,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-heat-balance","explanation":"卡诺循环可逆，有 \\(Q_\\mathrm h/T_\\mathrm h=Q_\\mathrm c/T_\\mathrm c\\)。净功为两热量之差，工质状态复原。低温热源的正熵变与高温热源的负熵变抵消。"},
  {"id":"t-carnot-refrigerator-5","type":"multiple","points":2,"stem":"可逆制冷机的冷端为 267 K、热端为 339 K，每周期从冷端移走 900 J。下列说法正确的是哪些？","options":["热端每周期得到热量 \\(1143\\,\\mathrm{J}\\)。","外界每周期至少输入功 \\(242.7\\,\\mathrm{J}\\)。","在保持热端温度不变时，降低冷端温度会提高制冷系数。","热端每周期得到的热量小于冷端失去的热量。","制冷系数约为 \\(3.708\\)。"],"answer":[0,1,4],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-carnot-refrigerator","explanation":"制冷机的卡诺制冷系数为 \\(T_\\mathrm c/(T_\\mathrm h-T_\\mathrm c)\\)。由 \\(W=Q_\\mathrm c/\\varepsilon\\) 求输入功，再用 \\(Q_\\mathrm h=Q_\\mathrm c+W\\)。冷端温度降低时制冷更困难。"},
  {"id":"t-reservoir-transfer-entropy-5","type":"single","points":2,"stem":"2120 J 热量自行从恒温 456 K 的热源传给恒温 313 K 的热源，无其他作用。两个热源的总熵增约是多少？","options":["\\(2.124\\,\\mathrm{J\\,K^{-1}}\\)","\\(6.773\\,\\mathrm{J\\,K^{-1}}\\)","\\(-2.124\\,\\mathrm{J\\,K^{-1}}\\)","\\(11.42\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-reservoir-transfer-entropy","explanation":"冷热源各自在恒温下交换热量。热源失热熵变 \\(-Q/T_\\mathrm h\\)，冷源得热熵变 \\(Q/T_\\mathrm c\\)，二者相加。 得 \\(2.124\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-insulated-free-expansion-5","type":"multiple","points":2,"stem":"2 mol 理想气体在绝热刚性容器中，撤去隔板后向真空自由膨胀，最终占据原来的 2.45 倍体积。下列说法正确的是哪些？","options":["因为过程绝热，所以气体熵变为零。","气体和外界之间没有热传递，也没有体积功。","这个过程可以仅靠气体自身逆向恢复而不引起其他变化。","初态和末态温度相同。","气体熵增约 \\(14.9\\,\\mathrm{J\\,K^{-1}}\\)。"],"answer":[1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-insulated-free-expansion","explanation":"自由膨胀无外压，且绝热，因此 \\(\\Delta U=0\\)。理想气体的内能只由温度决定，初末温度相同。熵是状态函数，可用连接两平衡态的可逆等温膨胀计算 \\(\\Delta S=nR\\ln(V_f/V_i)>0\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-finite-bodies-entropy-5","type":"single","points":3,"stem":"绝热容器内有两个只交换热量的物体。第一物体热容 320 J/K、初温 312 K，第二物体热容 426 J/K、初温 413 K。热容均为常数。到达共同温度后，两物体总熵增加约多少？","options":["\\(7.069\\,\\mathrm{J\\,K^{-1}}\\)","\\(47.21\\,\\mathrm{J\\,K^{-1}}\\)","\\(-7.069\\,\\mathrm{J\\,K^{-1}}\\)","\\(54.28\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-finite-bodies-entropy","explanation":"先用能量守恒求共同温度 \\(T_f=(C_1T_1+C_2T_2)/(C_1+C_2)\\)。各物体的熵变分别是 \\(C_i\\ln(T_f/T_i)\\)，将一正一负的两项相加。 得 \\(7.069\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-ideal-mixture-entropy-5","type":"single","points":3,"stem":"绝热刚性容器中有 2.3 mol A 和 4 mol B，均为不同的理想气体，初态分置两隔间，温度和压强都相同。撤去隔板后两气体完全混合。混合熵约是多少？","options":["\\(19.27\\,\\mathrm{J\\,K^{-1}}\\)","\\(52.38\\,\\mathrm{J\\,K^{-1}}\\)","\\(34.38\\,\\mathrm{J\\,K^{-1}}\\)","\\(15.11\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-ideal-mixture-entropy","explanation":"相同初始温压下，初体积占比等于摩尔分数 \\(x_i\\)。混合后每一组分可及体积为总容积，等效可逆等温膨胀的熵增为 \\(-n_iR\\ln x_i\\)。相加得到混合熵。 得 \\(34.38\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-entropy-temperature-volume-5","type":"single","points":3,"stem":"1.95 mol 刚性双原子理想气体从 305 K 变为 390 K，体积同时扩大至原来的 1.61 倍。忽略振动，求气体的熵变。","options":["\\(2.243\\,\\mathrm{J\\,K^{-1}}\\)","\\(17.68\\,\\mathrm{J\\,K^{-1}}\\)","\\(9.964\\,\\mathrm{J\\,K^{-1}}\\)","\\(7.721\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-entropy-temperature-volume","explanation":"可选先等容升温再等温膨胀作为可逆辅助路径。分别积出 \\(nC_V\\ln(T_2/T_1)\\) 和 \\(nR\\ln(V_2/V_1)\\)，相加。 得 \\(17.68\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-steady-conduction-5","type":"single","points":2,"stem":"面积为 0.26 m²、厚度 22 mm 的均匀平板，导热系数为 0.62 W/(m·K)，两表面恒温 360 K 和 305 K。忽略侧面漏热，稳定导热速率约是多少？","options":["\\(806\\,\\mathrm W\\)","\\(0.403\\,\\mathrm W\\)","\\(403\\,\\mathrm W\\)","\\(1550\\,\\mathrm W\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-steady-conduction","explanation":"稳定的一维傅里叶导热通量为 \\(j_Q=k(T_h-T_c)/L\\)。总导热速率还要乘面积，厚度从毫米换成米。 得 \\(403\\,\\mathrm W\\)。"},
  {"id":"t-series-conduction-5","type":"single","points":3,"stem":"面积 0.28 m² 的双层墙，第一层厚 37 mm、导热系数 0.29 W/(m·K)，第二层厚 50 mm、导热系数 0.64 W/(m·K)。外表面温差为 47 K，层间接触热阻忽略。稳定导热功率约是多少？","options":["\\(63.97\\,\\mathrm W\\)","\\(140.7\\,\\mathrm W\\)","\\(168.4\\,\\mathrm W\\)","\\(103.1\\,\\mathrm W\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-series-conduction","explanation":"两层串联时同一功率穿过每层，热阻为 \\(L/(kA)\\)。把热阻相加，外表面温差除以总热阻。 得 \\(63.97\\,\\mathrm W\\)。"},
  {"id":"t-couette-shear-5","type":"single","points":2,"stem":"两块平行板间夹有牛顿流体，板间距 5.6 mm，流体动力黏度 0.12 Pa·s。下板固定，上板以 0.97 m/s 匀速移动。忽略边缘效应，若上板接触面积 0.21 m²，流体对上板黏滞力的大小约是多少？","options":["\\(0.004365\\,\\mathrm N\\)","\\(8.73\\,\\mathrm N\\)","\\(4.365\\,\\mathrm N\\)","\\(20.79\\,\\mathrm N\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-couette-shear","explanation":"平板间的速度梯度为 \\(u/h\\)。牛顿黏性定律给出剪应力 \\(\\eta u/h\\)，再乘受力面积。 得 \\(4.365\\,\\mathrm N\\)。"},
  {"id":"t-fick-steady-flow-5","type":"single","points":2,"stem":"两侧浓度分别为 2.63、0.92 mol/m³，扩散距离 4.4 cm，面积 0.07 m²。浓度沿程线性，扩散系数为 \\(2.72\\times10^{-5}\\,\\mathrm{m^2\\,s^{-1}}\\)。求通过整个截面的物质的量输运速率大小。","options":["\\(0.001057\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.0074\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.0001536\\,\\mathrm{mol\\,s^{-1}}\\)","\\(7.4\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-fick-steady-flow","explanation":"菲克定律给出的通量大小为 \\(D|\\mathrm dc/\\mathrm dx|\\)，浓度线性时是 \\(D|c_1-c_2|/L\\)。乘以截面积得到总速率。 得 \\(7.4\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)。"},
  {"id":"t-linear-expansion-5","type":"single","points":1,"stem":"自由伸缩的细杆初长 2.3 m，线膨胀系数近似恒为 \\(1.54\\times10^{-5}\\,\\mathrm{K^{-1}}\\)。升温 67 K 后，长度增加量约是多少？","options":["\\(0.002373\\,\\mathrm m\\)","\\(2.373\\times10^{-6}\\,\\mathrm m\\)","\\(0.001032\\,\\mathrm m\\)","\\(0.007119\\,\\mathrm m\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-linear-expansion","explanation":"一阶近似下 \\(\\Delta L=\\alpha L_0\\Delta T\\)。长度和温差直接以题设单位代入。 得 \\(0.002373\\,\\mathrm m\\)。"},
  {"id":"t-curved-interfaces-5","type":"multiple","points":2,"stem":"一个液滴与一个薄壁肥皂泡的半径均为 0.91 mm，界面张力均为 0.069 N/m。忽略重力导致的变形。下列说法正确的是哪些？","options":["液滴内部压强小于外界。","相同界面张力下，把肥皂泡的半径加倍，其内外压差减半。","液滴内外压差约 \\(151.6\\,\\mathrm{Pa}\\)。","肥皂膜只有一个气液界面。","肥皂泡内外压差约 \\(303.3\\,\\mathrm{Pa}\\)。"],"answer":[1,2,4],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-curved-interfaces","explanation":"球形单界面的拉普拉斯压差是 \\(2\\sigma/r\\)。液滴仅一个界面，薄壁肥皂泡近似有两个等半径的界面，两个压差相加。压差均与半径成反比。"},
  {"id":"t-capillary-rise-5","type":"single","points":2,"stem":"毛细管内半径 0.46 mm，液体完全润湿管壁，液体密度 980 kg/m³、表面张力 0.058 N/m。忽略管外液面变化，管内液面约上升多高？","options":["\\(0.02623\\,\\mathrm m\\)","\\(0.01312\\,\\mathrm m\\)","\\(0.05246\\,\\mathrm m\\)","\\(26.23\\,\\mathrm m\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-capillary-rise","explanation":"完全润湿时接触角为零。竖直表面张力为 \\(2\\pi r\\sigma\\)，平衡液柱重力 \\(\\rho g\\pi r^2 h\\)。联立求高度。 得 \\(0.02623\\,\\mathrm m\\)。","reference":"重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。"},
  {"id":"t-heating-partial-vaporization-5","type":"single","points":3,"stem":"常压下质量 0.24 kg 的水从 26 ℃ 加热到 100 ℃，随后其质量的 30% 在 100 ℃ 汽化。取水的比热容为 4180 J/(kg·K)，汽化潜热为 \\(2.25\\times10^{6}\\,\\mathrm{J\\,kg^{-1}}\\)。忽略热损失，总吸热约是多少？","options":["\\(7.424\\times10^{4}\\,\\mathrm{J}\\)","\\(2.362\\times10^{5}\\,\\mathrm{J}\\)","\\(1.62\\times10^{5}\\,\\mathrm{J}\\)","\\(6.142\\times10^{5}\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 8 章","family":"t-heating-partial-vaporization","explanation":"升温吸热 \\(Q_1=mc\\Delta T\\)。汽化阶段只用实际汽化的质量乘潜热，\\(Q_2=mfL_v\\)。总吸热为两项之和。 得 \\(2.362\\times10^{5}\\,\\mathrm{J}\\)。"},
  {"id":"t-reversible-melting-entropy-5","type":"single","points":2,"stem":"某纯物质在规定压强下的熔点为 260 K，熔化潜热为 \\(3.2\\times10^{5}\\,\\mathrm{J\\,kg^{-1}}\\)。将处于熔点的 0.31 kg 固体缓慢熔化成同温液体。物质的熵变约是多少？","options":["\\(9.92\\times10^{4}\\,\\mathrm{J\\,K^{-1}}\\)","\\(1231\\,\\mathrm{J\\,K^{-1}}\\)","\\(381.5\\,\\mathrm{J\\,K^{-1}}\\)","\\(-381.5\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-reversible-melting-entropy","explanation":"熔点处可逆等温熔化需吸收 \\(Q=mL_f\\)。等温可逆相变的熵变为 \\(Q/T_m\\)，吸热时为正。 得 \\(381.5\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-clapeyron-slope-5","type":"single","points":3,"stem":"某纯物质处在 348 K 的液气平衡线上。该点的摩尔汽化潜热为 35.2 kJ/mol，气相和液相的摩尔体积差为 0.021 m³/mol。求该点饱和压强对温度的斜率。","options":["\\(13.84\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(101.1\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(4817\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(-4817\\,\\mathrm{Pa\\,K^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-clapeyron-slope","explanation":"克拉珀龙方程 \\( \\mathrm dp_\\mathrm{sat}/\\mathrm dT=L_m/[T(V_{m,g}-V_{m,l})] \\)。把摩尔潜热从 kJ/mol 换成 J/mol 后代入，气相摩尔体积更大，因此斜率为正。 得 \\(4817\\,\\mathrm{Pa\\,K^{-1}}\\)。"},
  {"id":"t-without-replacement-6","type":"single","points":1,"stem":"袋中有 10 个红球、6 个蓝球。一次不放回地随机抽取两个球，两个都是红球的概率约是多少？","options":["\\(0.3906\\)","\\(0.1875\\)","\\(0.625\\)","\\(0.375\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-without-replacement","explanation":"在不放回抽样中，第二次取红的条件概率为 \\((r-1)/(N-1)\\)。与首次概率 \\(r/N\\) 相乘。 得 \\(0.375\\)。"},
  {"id":"t-random-walk-origin-6","type":"single","points":2,"stem":"微粒从原点出发，在一条直线上独立地走 14 步，每步等概率向左或向右移动一个单位。最后回到原点的概率约是多少？","options":["\\(6.104\\times10^{-5}\\)","\\(0.5\\)","\\(0.06667\\)","\\(0.2095\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-random-walk-origin","explanation":"回到原点要求左右各走一半步数。共有 \\(\\binom{N}{N/2}\\) 条这样的序列，总序列数为 \\(2^N\\)。 得 \\(0.2095\\)。"},
  {"id":"t-power-density-6","type":"single","points":3,"stem":"连续随机变量的概率密度在 0 到 7 之间为 \\(f(x)=C x^{3}\\)，区间外为零。该变量落在 0 到 1 之间的概率约是多少？","options":["\\(0.1429\\)","\\(5.95\\times10^{-5}\\)","\\(0.0004165\\)","\\(0.9996\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 1 章","family":"t-power-density","explanation":"归一化要求分母为 \\(\\int_0^{L}x^a\\,\\mathrm dx\\)。区间概率是 \\(\\int_0^b x^a\\,\\mathrm dx/\\int_0^L x^a\\,\\mathrm dx=(b/L)^{a+1}\\)。 得 \\(0.0004165\\)。","reference":"当 \\(a>-1\\) 时，\\(\\int_0^L x^a\\,\\mathrm dx=L^{a+1}/(a+1)\\)。"},
  {"id":"t-rigid-vessel-temperature-6","type":"single","points":1,"stem":"密闭刚性容器里装有一定量理想气体。气体从 300 K 缓慢升温到 385 K，初态绝对压强为 125 kPa。末态压强约是多少？","options":["\\(125\\,\\mathrm{kPa}\\)","\\(97.4\\,\\mathrm{kPa}\\)","\\(566.2\\,\\mathrm{kPa}\\)","\\(160.4\\,\\mathrm{kPa}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-rigid-vessel-temperature","explanation":"容积和物质的量保持恒定，状态方程给出 \\(p_2/p_1=T_2/T_1\\)。 得 \\(160.4\\,\\mathrm{kPa}\\)。"},
  {"id":"t-dalton-partial-pressure-6","type":"single","points":1,"stem":"两种互不反应的理想气体形成均匀混合气。A 组分有 7 mol，B 组分有 17 mol，总压强为 195 kPa。A 的分压约是多少？","options":["\\(8.125\\,\\mathrm{kPa}\\)","\\(138.1\\,\\mathrm{kPa}\\)","\\(56.88\\,\\mathrm{kPa}\\)","\\(80.29\\,\\mathrm{kPa}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 2 章","family":"t-dalton-partial-pressure","explanation":"各组分在同一温度和体积下服从状态方程，分压占总压的比例等于摩尔分数。 得 \\(56.88\\,\\mathrm{kPa}\\)。"},
  {"id":"t-joined-vessels-6","type":"single","points":2,"stem":"两个容积分别为 8 L、18 L 的刚性容器分别装有理想气体，压强为 250 kPa、85 kPa。两容器均已与同一恒温浴达到热平衡，打开连通阀直至新平衡。末态总压强约是多少？","options":["\\(335\\,\\mathrm{kPa}\\)","\\(135.8\\,\\mathrm{kPa}\\)","\\(167.5\\,\\mathrm{kPa}\\)","\\(199.2\\,\\mathrm{kPa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-joined-vessels","explanation":"由初态两侧总物质的量守恒，且温度相同，有 \\(p_f(V_1+V_2)=p_1V_1+p_2V_2\\)。 得 \\(135.8\\,\\mathrm{kPa}\\)。"},
  {"id":"t-gas-mass-pressure-6","type":"single","points":2,"stem":"4.5 kg 氮气装在体积为 1.3 立方米的容器内，温度为 340 K。把氮气视为理想气体，取其摩尔质量 28 g/mol，求绝对压强。","options":["\\(6.989\\times10^{5}\\,\\mathrm{Pa}\\)","\\(3.495\\times10^{5}\\,\\mathrm{Pa}\\)","\\(3.495\\times10^{8}\\,\\mathrm{Pa}\\)","\\(9785\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 1 章","family":"t-gas-mass-pressure","explanation":"先以 \\(n=m/M\\) 将质量换成摩尔数，再由 \\(p=nRT/V\\) 代入。注意 \\(28\\,\\mathrm{g\\,mol^{-1}}=0.028\\,\\mathrm{kg\\,mol^{-1}}\\)。 得 \\(3.495\\times10^{5}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-van-der-waals-pressure-6","type":"single","points":3,"stem":"某气体每摩尔体积为 1.25 L/mol、温度为 305 K。范德瓦尔斯参数分别为 \\(0.195\\,\\mathrm{Pa\\,m^6\\,mol^{-2}}\\) 和 \\(0.000445\\,\\mathrm{m^3\\,mol^{-1}}\\)。求压强。","options":["\\(1.371\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.025\\times10^{6}\\,\\mathrm{Pa}\\)","\\(2.029\\times10^{6}\\,\\mathrm{Pa}\\)","\\(3.275\\times10^{6}\\,\\mathrm{Pa}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-van-der-waals-pressure","explanation":"采用摩尔体积形式，\\(p=RT/(V_m-b)-a/V_m^2\\)。体积应先换成 \\(\\mathrm{m^3\\,mol^{-1}}\\)。 得 \\(3.025\\times10^{6}\\,\\mathrm{Pa}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-mean-free-path-6","type":"single","points":2,"stem":"温度为 305 K、压强为 170 Pa 的稀薄气体由有效直径 0.38 nm 的相同硬球分子组成。估算分子的平均自由程。","options":["\\(3.861\\times10^{-5}\\,\\mathrm m\\)","\\(1.931\\times10^{-5}\\,\\mathrm m\\)","\\(0.0001213\\,\\mathrm m\\)","\\(5.46\\times10^{-5}\\,\\mathrm m\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 3 章","family":"t-mean-free-path","explanation":"由 \\(n=p/(k_\\mathrm BT)\\) 求数密度。相同硬球的平均自由程是 \\(\\lambda=1/(\\sqrt2\\,\\pi d^2 n)\\)，其中 \\(\\pi d^2\\) 为碰撞截面。 得 \\(3.861\\times10^{-5}\\,\\mathrm m\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-rms-temperature-6","type":"single","points":2,"stem":"一种理想气体的摩尔质量为 48 g/mol，分子的方均根速率为 540 m/s。求该气体的热力学温度。","options":["\\(841.8\\,\\mathrm{K}\\)","\\(1684\\,\\mathrm{K}\\)","\\(561.2\\,\\mathrm{K}\\)","\\(280.6\\,\\mathrm{K}\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-rms-temperature","explanation":"平均平动动能为 \\(3k_\\mathrm BT/2\\)，所以 \\(v_{\\mathrm{rms}}^2=3RT/M\\)。摩尔质量应以 kg/mol 代入。 得 \\(561.2\\,\\mathrm{K}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-kinetic-pressure-6","type":"single","points":2,"stem":"理想气体的压强为 126 kPa，质量密度为 1.03 kg/m³。估计分子的方均根速率。","options":["\\(856.7\\,\\mathrm{m\\,s^{-1}}\\)","\\(605.8\\,\\mathrm{m\\,s^{-1}}\\)","\\(349.8\\,\\mathrm{m\\,s^{-1}}\\)","\\(428.4\\,\\mathrm{m\\,s^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-kinetic-pressure","explanation":"分子运动论给出 \\(p=\\rho v_{\\mathrm{rms}}^2/3\\)，压强换成 Pa 后求平方根。 得 \\(605.8\\,\\mathrm{m\\,s^{-1}}\\)。"},
  {"id":"t-collision-frequency-6","type":"single","points":1,"stem":"某稀薄气体分子的平均速率为 495 m/s，平均自由程为 142 nm。估计单个分子的平均碰撞频率。","options":["\\(3.486\\,\\mathrm{s^{-1}}\\)","\\(6.972\\times10^{9}\\,\\mathrm{s^{-1}}\\)","\\(8.715\\times10^{8}\\,\\mathrm{s^{-1}}\\)","\\(3.486\\times10^{9}\\,\\mathrm{s^{-1}}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 4 章","family":"t-collision-frequency","explanation":"在平均意义下，单位时间经历的自由程数约为 \\(\\bar v/\\lambda\\)。将 nm 换成 m 再相除。 得 \\(3.486\\times10^{9}\\,\\mathrm{s^{-1}}\\)。"},
  {"id":"t-maxwell-temperature-ratio-6","type":"single","points":1,"stem":"同一种气体分别处于 350 K 和 485 K 的平衡态。后者与前者的最概然速率之比约是多少？","options":["\\(1.386\\)","\\(1.177\\)","\\(0.3857\\)","\\(0.8495\\)"],"answer":[1],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-temperature-ratio","explanation":"同种气体的分子质量相同，最概然速率 \\(v_p=\\sqrt{2RT/M}\\) 与绝对温度的平方根成正比。 得 \\(1.177\\)。"},
  {"id":"t-barometric-ratio-6","type":"single","points":3,"stem":"把大气视为均匀摩尔质量为 32 g/mol 的理想气体，设温度恒为 290 K、重力加速度不随高度改变。海拔比基准面高 3450 m 处的气压是基准面气压的多少倍？","options":["\\(0.4072\\)","\\(1.567\\)","\\(0.3619\\)","\\(0.6381\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-barometric-ratio","explanation":"将静力平衡 \\(\\mathrm dp/\\mathrm dz=-\\rho g\\) 与 \\(\\rho=Mp/(RT)\\) 联立并积分，得到 \\(p(z)/p(0)=\\exp[-Mgz/(RT)]\\)。 得 \\(0.6381\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-two-level-population-6","type":"single","points":3,"stem":"一批可分辨的弱相互作用粒子在 400 K 达到热平衡。每个粒子仅能处在两个非简并能级，上能级比下能级高 \\(1.353\\times10^{-20}\\,\\mathrm{J}\\)。约有多大比例的粒子在上能级？","options":["\\(0.07944\\)","\\(0.9206\\)","\\(0.007447\\)","\\(0.08629\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-two-level-population","explanation":"以上能级和下能级的玻尔兹曼权重分别为 \\(\\exp[-\\Delta E/(k_\\mathrm BT)]\\) 和 1，将上能级权重除以两权重之和。 得 \\(0.07944\\)。","reference":"玻尔兹曼常数 \\(k_{\\mathrm B}=1.380649\\times10^{-23}\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-mixture-equipartition-6","type":"single","points":2,"stem":"6 mol 单原子理想气体与 3 mol 刚性双原子理想气体混合，在 325 K 达到热平衡。忽略双原子分子的振动，混合气体的总内能约是多少？","options":["\\(8.917\\times10^{4}\\,\\mathrm{J}\\)","\\(3.648\\times10^{4}\\,\\mathrm{J}\\)","\\(6.08\\times10^{4}\\,\\mathrm{J}\\)","\\(4.458\\times10^{4}\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 4 章","family":"t-mixture-equipartition","explanation":"按能量均分，单原子有 3 个自由度，刚性双原子有 5 个自由度。分别计算 \\(f nRT/2\\) 后相加。 得 \\(4.458\\times10^{4}\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-maxwell-concepts-6","type":"multiple","points":2,"stem":"温度为 405 K 的氧气和温度为 276 K 的氮气都处于无宏观流动的平衡态。取氧气、氮气的摩尔质量分别为 32 和 28 g/mol。关于它们的麦克斯韦速率分布，正确的是哪些？","options":["氧气与氮气的最概然速率之比约为 \\(1.133\\)。","氧气的最概然速率低于氮气。","任一种气体的分子平均速度矢量为零。","在同一平衡态，任一种气体的最概然速率大于其方均根速率。","同一种气体升温，最概然速率增大。"],"answer":[0,2,4],"source":"教材专题改编 · 宋锋等《热学》第 5 章","family":"t-maxwell-concepts","explanation":"最概然速率为 \\(v_p=\\sqrt{2RT/M}\\)。两种气体的速率之比由各自的 \\(T/M\\) 决定；升温则最概然速率增大。最概然速率小于方均根速率。平衡态无宏观流动，各方向的速度矢量平均为零。"},
  {"id":"t-isobaric-work-6","type":"single","points":1,"stem":"2.7 mol 理想气体在压强不变的情况下从 305 K 升至 366 K。气体对外做的体积功约是多少？","options":["\\(3423\\,\\mathrm{J}\\)","\\(1369\\,\\mathrm{J}\\)","\\(2054\\,\\mathrm{J}\\)","\\(684.7\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isobaric-work","explanation":"等压过程 \\(W=p(V_2-V_1)\\)。由状态方程，\\(p(V_2-V_1)=nR(T_2-T_1)\\)。 得 \\(1369\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isochoric-heating-6","type":"single","points":1,"stem":"1.7 mol 单原子理想气体在刚性容器中从 305 K 加热到 352 K，仅交换热量。气体吸热约是多少？","options":["\\(996.4\\,\\mathrm{J}\\)","\\(1661\\,\\mathrm{J}\\)","\\(664.3\\,\\mathrm{J}\\)","\\(1993\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isochoric-heating","explanation":"定容过程没有体积功，吸热等于内能增加。单原子理想气体的定容摩尔热容为 \\(3R/2\\)。 得 \\(996.4\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-isothermal-work-6","type":"single","points":2,"stem":"1.45 mol 理想气体在 330 K 从体积 7 L 可逆等温膨胀到 19.25 L。气体对外做功约是多少？","options":["\\(2012\\,\\mathrm{J}\\)","\\(4024\\,\\mathrm{J}\\)","\\(6962\\,\\mathrm{J}\\)","\\(2532\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-isothermal-work","explanation":"准静态做功为 \\(\\int p\\,\\mathrm dV\\)。等温时 \\(p=nRT/V\\)，积分得 \\(W=nRT\\ln(V_2/V_1)\\)。 得 \\(4024\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-adiabatic-expansion-temperature-6","type":"single","points":2,"stem":"1.9 mol 单原子理想气体初温 350 K，可逆绝热膨胀至原体积的 2.7 倍。末温约是多少？","options":["\\(180.5\\,\\mathrm{K}\\)","\\(213\\,\\mathrm{K}\\)","\\(678.6\\,\\mathrm{K}\\)","\\(129.6\\,\\mathrm{K}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-adiabatic-expansion-temperature","explanation":"可逆绝热过程 \\(TV^{\\gamma-1}\\) 不变，单原子气体 \\(\\gamma=5/3\\)。据此由体积比求温度比。 得 \\(180.5\\,\\mathrm{K}\\)。"},
  {"id":"t-adiabatic-compression-work-6","type":"single","points":3,"stem":"2.4 mol 刚性双原子理想气体初温为 330 K，经可逆绝热压缩，体积缩小为原来的 1/2.8。外界对气体做的功约是多少？","options":["\\(8389\\,\\mathrm{J}\\)","\\(6780\\,\\mathrm{J}\\)","\\(1.174\\times10^{4}\\,\\mathrm{J}\\)","\\(3356\\,\\mathrm{J}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-adiabatic-compression-work","explanation":"忽略振动时 \\(\\gamma=7/5\\)，由 \\(TV^{\\gamma-1}=\\text{常量}\\) 求末温。因 \\(Q=0\\)，外界做功等于 \\(\\Delta U=\\tfrac52nR(T_2-T_1)\\)。 得 \\(8389\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-linear-path-work-6","type":"single","points":2,"stem":"一份气体在准静态膨胀中体积增加 4 L，压强从 100 kPa 随体积线性升到 230 kPa。气体对外做功是多少？","options":["\\(520\\,\\mathrm{J}\\)","\\(660\\,\\mathrm{J}\\)","\\(400\\,\\mathrm{J}\\)","\\(920\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-linear-path-work","explanation":"沿直线过程，\\(p\\!-\\!V\\) 图下方的梯形面积等于平均压强乘体积变化。\\(1\\,\\mathrm{kPa\\,L}=1\\,\\mathrm J\\)。 得 \\(660\\,\\mathrm{J}\\)。"},
  {"id":"t-rectangular-cycle-6","type":"multiple","points":2,"stem":"理想气体沿顺时针矩形循环运行。两条等压边压强分别为 110 kPa 和 255 kPa，两条等容边体积分别为 8 L 和 18 L。关于整个循环，下列说法正确的是哪些？","options":["沿两个等容段，体积功均为零。","一周后气体总吸热一定为零。","高压等压边与低压等压边的体积功大小相等。","气体净对外做功为 \\(1450\\,\\mathrm{J}\\)。","一周后气体内能变化为零。"],"answer":[0,3,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-rectangular-cycle","explanation":"顺时针循环的净功为矩形面积 \\((p_h-p_l)(V_h-V_l)\\)。回到起态时 \\(\\Delta U=0\\)，净吸热等于净功，非零。等容段 \\(\\mathrm dV=0\\)，两条等压边体积改变量大小相同但压强不同。"},
  {"id":"t-isobaric-monatomic-budget-6","type":"multiple","points":2,"stem":"3.5 mol 单原子理想气体在恒压下从 330 K 加热至 389 K，只做体积功。下列数量关系正确的是哪些？","options":["气体对外做功 \\(1717\\,\\mathrm{J}\\)。","气体吸热等于内能的增加量。","气体的焓不变。","气体吸收热量 \\(4292\\,\\mathrm{J}\\)。","气体的内能增加 \\(2575\\,\\mathrm{J}\\)。"],"answer":[0,3,4],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-isobaric-monatomic-budget","explanation":"定压时 \\(W=nR\\Delta T\\)，内能变化为 \\(nC_V\\Delta T\\)，焓变化 \\(nC_p\\Delta T\\) 等于吸热。单原子气体 \\(C_V=3R/2,\\ C_p=5R/2\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。"},
  {"id":"t-two-stage-heating-expansion-6","type":"single","points":3,"stem":"3 mol 单原子理想气体先定容地从 310 K 加热到 360 K，接着在 360 K 可逆等温膨胀，体积变为原来的 2.4 倍。两阶段总吸热约是多少？","options":["\\(1871\\,\\mathrm{J}\\)","\\(1.098\\times10^{4}\\,\\mathrm{J}\\)","\\(7861\\,\\mathrm{J}\\)","\\(9732\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-two-stage-heating-expansion","explanation":"第一段等容，\\(Q_1=\\Delta U_1=\\tfrac32nR(T_2-T_1)\\)。第二段等温，\\(Q_2=W_2=nRT_2\\ln(V_f/V_i)\\)。总吸热为两段之和。 得 \\(9732\\,\\mathrm{J}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-polytropic-work-6","type":"single","points":3,"stem":"气体从 5 L 准静态膨胀至 10.5 L，初压 130 kPa。过程满足 \\(pV^{1.445}\\) 为常量。气体对外做功约是多少？","options":["\\(715\\,\\mathrm{J}\\)","\\(410.7\\,\\mathrm{J}\\)","\\(482.3\\,\\mathrm{J}\\)","\\(244.7\\,\\mathrm{J}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-polytropic-work","explanation":"设 \\(pV^s=C\\)，把 \\(p=CV^{-s}\\) 代入体积功积分，可得 \\(W=(p_2V_2-p_1V_1)/(1-s)\\)。用状态间的多方关系求 \\(p_2\\)。 得 \\(410.7\\,\\mathrm{J}\\)。","reference":"当 \\(a\\ne-1\\) 时，\\(\\int x^a\\,\\mathrm dx=x^{a+1}/(a+1)+C\\)。"},
  {"id":"t-compression-energy-balance-6","type":"multiple","points":2,"stem":"气体在带活塞的容器中被缓慢压缩。过程中气体吸热 1775 J，外界对气体做功 465 J，忽略其他能量交换。下列说法正确的是哪些？","options":["按气体对外做功为正的约定，气体的体积功为 \\(-465\\,\\mathrm{J}\\)。","气体内能增加 \\(2240\\,\\mathrm{J}\\)。","热量等于外界对气体做的功。","气体的内能变化等于 \\(1310\\,\\mathrm{J}\\)。","气体一定放热。"],"answer":[0,1],"source":"教材专题改编 · 宋锋等《热学》第 2 章","family":"t-compression-energy-balance","explanation":"采用 \\(\\Delta U=Q-W_{\\mathrm{by}}\\)。吸热 \\(Q>0\\)，压缩时气体对外做功 \\(W_{\\mathrm{by}}<0\\)。内能增加量等于吸热量与外界做功之和。"},
  {"id":"t-carnot-absorbed-heat-6","type":"single","points":3,"stem":"一台可逆热机在 645 K 的高温热源与 315 K 的低温热源之间工作，每循环对外净做功 1450 J。每循环从高温热源吸热约是多少？","options":["\\(741.9\\,\\mathrm{J}\\)","\\(1450\\,\\mathrm{J}\\)","\\(2969\\,\\mathrm{J}\\)","\\(2834\\,\\mathrm{J}\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-absorbed-heat","explanation":"卡诺效率 \\(\\eta=1-T_\\mathrm c/T_\\mathrm h\\)，同时 \\(\\eta=W/Q_\\mathrm h\\)。把两式联立求 \\(Q_\\mathrm h\\)。 得 \\(2834\\,\\mathrm{J}\\)。"},
  {"id":"t-carnot-heat-balance-6","type":"multiple","points":2,"stem":"卡诺热机在 670 K、335 K 的两个热源之间运行，每周吸收高温热量 2250 J。下列说法正确的是哪些？","options":["两热源的总熵在每周内严格增加。","高温热源每周熵增约 \\(3.358\\,\\mathrm{J\\,K^{-1}}\\)。","每周向低温热源放热约 \\(1125\\,\\mathrm{J}\\)。","每周净输出功约 \\(1125\\,\\mathrm{J}\\)。","工质每周的熵变为零。"],"answer":[2,3,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-carnot-heat-balance","explanation":"卡诺循环可逆，有 \\(Q_\\mathrm h/T_\\mathrm h=Q_\\mathrm c/T_\\mathrm c\\)。净功为两热量之差，工质状态复原。低温热源的正熵变与高温热源的负熵变抵消。"},
  {"id":"t-carnot-refrigerator-6","type":"multiple","points":2,"stem":"可逆制冷机的冷端为 272 K、热端为 345 K，每周期从冷端移走 1000 J。下列说法正确的是哪些？","options":["热端每周期得到的热量小于冷端失去的热量。","外界每周期至少输入功 \\(268.4\\,\\mathrm{J}\\)。","在保持热端温度不变时，降低冷端温度会提高制冷系数。","制冷系数约为 \\(3.726\\)。","热端每周期得到热量 \\(1268\\,\\mathrm{J}\\)。"],"answer":[1,3,4],"source":"教材专题改编 · 常树人《热学》第 6 章","family":"t-carnot-refrigerator","explanation":"制冷机的卡诺制冷系数为 \\(T_\\mathrm c/(T_\\mathrm h-T_\\mathrm c)\\)。由 \\(W=Q_\\mathrm c/\\varepsilon\\) 求输入功，再用 \\(Q_\\mathrm h=Q_\\mathrm c+W\\)。冷端温度降低时制冷更困难。"},
  {"id":"t-reservoir-transfer-entropy-6","type":"single","points":2,"stem":"2400 J 热量自行从恒温 475 K 的热源传给恒温 325 K 的热源，无其他作用。两个热源的总熵增约是多少？","options":["\\(12.44\\,\\mathrm{J\\,K^{-1}}\\)","\\(2.332\\,\\mathrm{J\\,K^{-1}}\\)","\\(7.385\\,\\mathrm{J\\,K^{-1}}\\)","\\(-2.332\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-reservoir-transfer-entropy","explanation":"冷热源各自在恒温下交换热量。热源失热熵变 \\(-Q/T_\\mathrm h\\)，冷源得热熵变 \\(Q/T_\\mathrm c\\)，二者相加。 得 \\(2.332\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-insulated-free-expansion-6","type":"multiple","points":2,"stem":"2.3 mol 理想气体在绝热刚性容器中，撤去隔板后向真空自由膨胀，最终占据原来的 2.7 倍体积。下列说法正确的是哪些？","options":["气体和外界之间没有热传递，也没有体积功。","因为过程绝热，所以气体熵变为零。","这个过程可以仅靠气体自身逆向恢复而不引起其他变化。","初态和末态温度相同。","气体熵增约 \\(18.99\\,\\mathrm{J\\,K^{-1}}\\)。"],"answer":[0,3,4],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-insulated-free-expansion","explanation":"自由膨胀无外压，且绝热，因此 \\(\\Delta U=0\\)。理想气体的内能只由温度决定，初末温度相同。熵是状态函数，可用连接两平衡态的可逆等温膨胀计算 \\(\\Delta S=nR\\ln(V_f/V_i)>0\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-finite-bodies-entropy-6","type":"single","points":3,"stem":"绝热容器内有两个只交换热量的物体。第一物体热容 355 J/K、初温 315 K，第二物体热容 465 J/K、初温 425 K。热容均为常数。到达共同温度后，两物体总熵增加约多少？","options":["\\(8.878\\,\\mathrm{J\\,K^{-1}}\\)","\\(55.26\\,\\mathrm{J\\,K^{-1}}\\)","\\(-8.878\\,\\mathrm{J\\,K^{-1}}\\)","\\(64.14\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 宋锋等《热学》第 3 章","family":"t-finite-bodies-entropy","explanation":"先用能量守恒求共同温度 \\(T_f=(C_1T_1+C_2T_2)/(C_1+C_2)\\)。各物体的熵变分别是 \\(C_i\\ln(T_f/T_i)\\)，将一正一负的两项相加。 得 \\(8.878\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-ideal-mixture-entropy-6","type":"single","points":3,"stem":"绝热刚性容器中有 2.6 mol A 和 4.4 mol B，均为不同的理想气体，初态分置两隔间，温度和压强都相同。撤去隔板后两气体完全混合。混合熵约是多少？","options":["\\(38.39\\,\\mathrm{J\\,K^{-1}}\\)","\\(58.2\\,\\mathrm{J\\,K^{-1}}\\)","\\(16.99\\,\\mathrm{J\\,K^{-1}}\\)","\\(21.41\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-ideal-mixture-entropy","explanation":"相同初始温压下，初体积占比等于摩尔分数 \\(x_i\\)。混合后每一组分可及体积为总容积，等效可逆等温膨胀的熵增为 \\(-n_iR\\ln x_i\\)。相加得到混合熵。 得 \\(38.39\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-entropy-temperature-volume-6","type":"single","points":3,"stem":"2.15 mol 刚性双原子理想气体从 310 K 变为 402 K，体积同时扩大至原来的 1.7 倍。忽略振动，求气体的熵变。","options":["\\(21.1\\,\\mathrm{J\\,K^{-1}}\\)","\\(11.61\\,\\mathrm{J\\,K^{-1}}\\)","\\(2.128\\,\\mathrm{J\\,K^{-1}}\\)","\\(9.485\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 7 章","family":"t-entropy-temperature-volume","explanation":"可选先等容升温再等温膨胀作为可逆辅助路径。分别积出 \\(nC_V\\ln(T_2/T_1)\\) 和 \\(nR\\ln(V_2/V_1)\\)，相加。 得 \\(21.1\\,\\mathrm{J\\,K^{-1}}\\)。","reference":"气体常数 \\(R=8.314\\,\\mathrm{J\\,mol^{-1}\\,K^{-1}}\\)。积分表（\\(x>0\\)）：\\(\\int \\frac{\\mathrm dx}{x}=\\ln x+C\\)。"},
  {"id":"t-steady-conduction-6","type":"single","points":2,"stem":"面积为 0.29 m²、厚度 24 mm 的均匀平板，导热系数为 0.67 W/(m·K)，两表面恒温 365 K 和 308 K。忽略侧面漏热，稳定导热速率约是多少？","options":["\\(1591\\,\\mathrm W\\)","\\(0.4615\\,\\mathrm W\\)","\\(461.5\\,\\mathrm W\\)","\\(922.9\\,\\mathrm W\\)"],"answer":[2],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-steady-conduction","explanation":"稳定的一维傅里叶导热通量为 \\(j_Q=k(T_h-T_c)/L\\)。总导热速率还要乘面积，厚度从毫米换成米。 得 \\(461.5\\,\\mathrm W\\)。"},
  {"id":"t-series-conduction-6","type":"single","points":3,"stem":"面积 0.3 m² 的双层墙，第一层厚 40 mm、导热系数 0.31 W/(m·K)，第二层厚 52 mm、导热系数 0.68 W/(m·K)。外表面温差为 51 K，层间接触热阻忽略。稳定导热功率约是多少？","options":["\\(164.6\\,\\mathrm W\\)","\\(118.6\\,\\mathrm W\\)","\\(74.45\\,\\mathrm W\\)","\\(200.1\\,\\mathrm W\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-series-conduction","explanation":"两层串联时同一功率穿过每层，热阻为 \\(L/(kA)\\)。把热阻相加，外表面温差除以总热阻。 得 \\(74.45\\,\\mathrm W\\)。"},
  {"id":"t-couette-shear-6","type":"single","points":2,"stem":"两块平行板间夹有牛顿流体，板间距 6 mm，流体动力黏度 0.135 Pa·s。下板固定，上板以 1.1 m/s 匀速移动。忽略边缘效应，若上板接触面积 0.235 m²，流体对上板黏滞力的大小约是多少？","options":["\\(5.816\\,\\mathrm N\\)","\\(24.75\\,\\mathrm N\\)","\\(0.005816\\,\\mathrm N\\)","\\(11.63\\,\\mathrm N\\)"],"answer":[0],"source":"教材专题改编 · 常树人《热学》第 5 章","family":"t-couette-shear","explanation":"平板间的速度梯度为 \\(u/h\\)。牛顿黏性定律给出剪应力 \\(\\eta u/h\\)，再乘受力面积。 得 \\(5.816\\,\\mathrm N\\)。"},
  {"id":"t-fick-steady-flow-6","type":"single","points":2,"stem":"两侧浓度分别为 2.85、1.03 mol/m³，扩散距离 5 cm，面积 0.08 m²。浓度沿程线性，扩散系数为 \\(3\\times10^{-5}\\,\\mathrm{m^2\\,s^{-1}}\\)。求通过整个截面的物质的量输运速率大小。","options":["\\(0.001092\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.008736\\,\\mathrm{mol\\,s^{-1}}\\)","\\(8.736\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)","\\(0.0001862\\,\\mathrm{mol\\,s^{-1}}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 6 章","family":"t-fick-steady-flow","explanation":"菲克定律给出的通量大小为 \\(D|\\mathrm dc/\\mathrm dx|\\)，浓度线性时是 \\(D|c_1-c_2|/L\\)。乘以截面积得到总速率。 得 \\(8.736\\times10^{-5}\\,\\mathrm{mol\\,s^{-1}}\\)。"},
  {"id":"t-linear-expansion-6","type":"single","points":1,"stem":"自由伸缩的细杆初长 2.6 m，线膨胀系数近似恒为 \\(1.65\\times10^{-5}\\,\\mathrm{K^{-1}}\\)。升温 74 K 后，长度增加量约是多少？","options":["\\(0.009524\\,\\mathrm m\\)","\\(3.175\\times10^{-6}\\,\\mathrm m\\)","\\(0.003175\\,\\mathrm m\\)","\\(0.001221\\,\\mathrm m\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-linear-expansion","explanation":"一阶近似下 \\(\\Delta L=\\alpha L_0\\Delta T\\)。长度和温差直接以题设单位代入。 得 \\(0.003175\\,\\mathrm m\\)。"},
  {"id":"t-curved-interfaces-6","type":"multiple","points":2,"stem":"一个液滴与一个薄壁肥皂泡的半径均为 1 mm，界面张力均为 0.071 N/m。忽略重力导致的变形。下列说法正确的是哪些？","options":["液滴内部压强小于外界。","肥皂泡内外压差约 \\(284\\,\\mathrm{Pa}\\)。","肥皂膜只有一个气液界面。","相同界面张力下，把肥皂泡的半径加倍，其内外压差减半。","液滴内外压差约 \\(142\\,\\mathrm{Pa}\\)。"],"answer":[1,3,4],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-curved-interfaces","explanation":"球形单界面的拉普拉斯压差是 \\(2\\sigma/r\\)。液滴仅一个界面，薄壁肥皂泡近似有两个等半径的界面，两个压差相加。压差均与半径成反比。"},
  {"id":"t-capillary-rise-6","type":"single","points":2,"stem":"毛细管内半径 0.5 mm，液体完全润湿管壁，液体密度 1000 kg/m³、表面张力 0.061 N/m。忽略管外液面变化，管内液面约上升多高？","options":["\\(0.01244\\,\\mathrm m\\)","\\(24.87\\,\\mathrm m\\)","\\(0.04975\\,\\mathrm m\\)","\\(0.02487\\,\\mathrm m\\)"],"answer":[3],"source":"教材专题改编 · 宋锋等《热学》第 7 章","family":"t-capillary-rise","explanation":"完全润湿时接触角为零。竖直表面张力为 \\(2\\pi r\\sigma\\)，平衡液柱重力 \\(\\rho g\\pi r^2 h\\)。联立求高度。 得 \\(0.02487\\,\\mathrm m\\)。","reference":"重力加速度 \\(g=9.81\\,\\mathrm{m\\,s^{-2}}\\)。"},
  {"id":"t-heating-partial-vaporization-6","type":"single","points":3,"stem":"常压下质量 0.265 kg 的水从 28 ℃ 加热到 100 ℃，随后其质量的 34% 在 100 ℃ 汽化。取水的比热容为 4180 J/(kg·K)，汽化潜热为 \\(2.25\\times10^{6}\\,\\mathrm{J\\,kg^{-1}}\\)。忽略热损失，总吸热约是多少？","options":["\\(6.76\\times10^{5}\\,\\mathrm{J}\\)","\\(7.975\\times10^{4}\\,\\mathrm{J}\\)","\\(2.825\\times10^{5}\\,\\mathrm{J}\\)","\\(2.027\\times10^{5}\\,\\mathrm{J}\\)"],"answer":[2],"source":"教材专题改编 · 宋锋等《热学》第 8 章","family":"t-heating-partial-vaporization","explanation":"升温吸热 \\(Q_1=mc\\Delta T\\)。汽化阶段只用实际汽化的质量乘潜热，\\(Q_2=mfL_v\\)。总吸热为两项之和。 得 \\(2.825\\times10^{5}\\,\\mathrm{J}\\)。"},
  {"id":"t-reversible-melting-entropy-6","type":"single","points":2,"stem":"某纯物质在规定压强下的熔点为 265 K，熔化潜热为 \\(3.3\\times10^{5}\\,\\mathrm{J\\,kg^{-1}}\\)。将处于熔点的 0.35 kg 固体缓慢熔化成同温液体。物质的熵变约是多少？","options":["\\(1245\\,\\mathrm{J\\,K^{-1}}\\)","\\(435.8\\,\\mathrm{J\\,K^{-1}}\\)","\\(1.155\\times10^{5}\\,\\mathrm{J\\,K^{-1}}\\)","\\(-435.8\\,\\mathrm{J\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-reversible-melting-entropy","explanation":"熔点处可逆等温熔化需吸收 \\(Q=mL_f\\)。等温可逆相变的熵变为 \\(Q/T_m\\)，吸热时为正。 得 \\(435.8\\,\\mathrm{J\\,K^{-1}}\\)。"},
  {"id":"t-clapeyron-slope-6","type":"single","points":3,"stem":"某纯物质处在 355 K 的液气平衡线上。该点的摩尔汽化潜热为 37 kJ/mol，气相和液相的摩尔体积差为 0.022 m³/mol。求该点饱和压强对温度的斜率。","options":["\\(104.2\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(4738\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(-4738\\,\\mathrm{Pa\\,K^{-1}}\\)","\\(13.35\\,\\mathrm{Pa\\,K^{-1}}\\)"],"answer":[1],"source":"教材专题改编 · 常树人《热学》第 8 章","family":"t-clapeyron-slope","explanation":"克拉珀龙方程 \\( \\mathrm dp_\\mathrm{sat}/\\mathrm dT=L_m/[T(V_{m,g}-V_{m,l})] \\)。把摩尔潜热从 kJ/mol 换成 J/mol 后代入，气相摩尔体积更大，因此斜率为正。 得 \\(4738\\,\\mathrm{Pa\\,K^{-1}}\\)。"}
]);
